:root {
  --bg-top: #f8fafc;
  --bg-mid: rgba(219, 234, 254, 0.4);   /* blue-50 */
  --bg-bottom: rgba(238, 242, 255, 0.5); /* indigo-50 */
  --accent: #0284c7;                     /* bright cyan / royal blue */
  --indigo: #4f46e5;
  --cyan: #06b6d4;
  --emerald: #059669;
  --rose: #e11d48;
  --amber: #b45309;
  --text: #0f172a;                       /* midnight navy */
  --charcoal: #18181b;                   /* card text */
  --muted: #64748b;                      /* slate-500 */
  --white: #ffffff;
  --glass: rgba(255, 255, 255, 0.8);
  --glass-strong: rgba(255, 255, 255, 0.92);
  --border-soft: rgba(255, 255, 255, 0.6);
  --border-line: #e2e8f0;                /* slate-200 */
  --border-line-2: #cbd5e1;              /* slate-300 */
  --hover: #f1f5f9;                      /* slate-100 */
  --chip-bg: #f1f5f9;
  --wrong-bg: #fff1f2;
  --grad: linear-gradient(135deg, #4f46e5 0%, #06b6d4 100%);
  --grad-soft: linear-gradient(135deg, rgba(79, 70, 229, 0.09), rgba(6, 182, 212, 0.08));
  --shadow: 0 12px 30px rgba(12, 74, 110, 0.07);
  --glow: 0 6px 20px rgba(79, 70, 229, 0.28);
  --radius: 14px;
}

:root[data-theme="dark"] {
  --bg-top: #0b1220;
  --bg-mid: rgba(30, 41, 59, 0.5);
  --bg-bottom: rgba(15, 23, 42, 0.65);
  --text: #e2e8f0;
  --charcoal: #f1f5f9;
  --muted: #94a3b8;
  --white: #111a2c;
  --glass: rgba(23, 32, 48, 0.78);
  --glass-strong: rgba(23, 32, 48, 0.95);
  --border-soft: rgba(148, 163, 184, 0.15);
  --border-line: #263247;
  --border-line-2: #3b4a63;
  --hover: #1e293b;
  --chip-bg: #1e293b;
  --wrong-bg: rgba(225, 29, 72, 0.18);
  --shadow: 0 12px 30px rgba(0, 0, 0, 0.5);
  --glow: 0 6px 22px rgba(99, 102, 241, 0.4);
}

html.fs-compact { zoom: 0.92; }
html.fs-large { zoom: 1.12; }

* { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  color: var(--text);
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  line-height: 1.55;
  background: linear-gradient(135deg, var(--bg-top), var(--bg-mid), var(--bg-bottom));
  overflow-x: hidden;
}

body::before {
  content: "";
  position: fixed;
  inset: -25%;
  z-index: -1;
  pointer-events: none;
  background:
    radial-gradient(30% 26% at 22% 18%, rgba(56, 189, 248, 0.08), transparent 65%),
    radial-gradient(26% 22% at 80% 28%, rgba(99, 102, 241, 0.07), transparent 65%),
    radial-gradient(24% 22% at 60% 82%, rgba(217, 70, 239, 0.04), transparent 65%);
  filter: blur(34px);
  animation: aurora 26s ease-in-out infinite alternate;
}

@keyframes aurora {
  0%   { transform: translate3d(-2%, -1%, 0) scale(1); }
  50%  { transform: translate3d(2%, 1.5%, 0) scale(1.06); }
  100% { transform: translate3d(-1.5%, 2%, 0) scale(1.01); }
}

::selection { background: rgba(79, 70, 229, 0.18); }

::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
  background: rgba(99, 102, 241, 0.25);
  border-radius: 999px;
  border: 2px solid var(--bg-top);
}
::-webkit-scrollbar-thumb:hover { background: rgba(99, 102, 241, 0.4); }

.app { display: flex; min-height: 100vh; }

/* ---------------------------------------------------------------- sidebar */

.sidebar {
  width: 250px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  background: var(--glass);
  backdrop-filter: blur(14px);
  border-right: 1px solid var(--border-line);
  padding: 18px 14px;
  position: sticky;
  top: 0;
  height: 100vh;
}

.brand { display: flex; align-items: center; gap: 10px; margin-bottom: 18px; }

.brand-mark {
  width: 38px; height: 38px;
  display: grid; place-items: center;
  border-radius: 11px;
  background: var(--grad);
  font-weight: 800; font-size: 14px; letter-spacing: .5px; color: #fff;
  box-shadow: var(--glow);
}

.brand-text { display: flex; flex-direction: column; line-height: 1.2; }
.brand-text strong { font-size: 14px; color: var(--text); }
.brand-text span { font-size: 11px; color: var(--muted); }

.new-deck {
  width: 100%;
  padding: 9px 12px;
  border: 1px dashed #7dd3fc;
  border-radius: 10px;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  transition: background .15s, border-color .15s;
}
.new-deck:hover { background: #f0f9ff; border-color: var(--accent); }

.deck-head {
  margin: 16px 4px 6px;
  font-size: 11px; font-weight: 700; letter-spacing: 1.2px;
  color: var(--muted); text-transform: uppercase;
}

.deck-list { list-style: none; margin: 0; padding: 0; overflow-y: auto; flex: 1; }

.deck-item {
  display: flex; align-items: center; gap: 8px;
  padding: 9px 10px; margin-bottom: 4px;
  border-radius: 10px; cursor: pointer;
  border: 1px solid transparent;
  transition: background .12s, border-color .12s;
}
.deck-item:hover { background: rgba(224, 231, 255, 0.55); }  /* indigo-100 tint */
.deck-item.active {
  background: linear-gradient(135deg, rgba(79, 70, 229, 0.09), rgba(6, 182, 212, 0.07));
  border-color: rgba(99, 102, 241, 0.3);
}
.deck-item .name { flex: 1; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--text); }
.deck-item .meta { font-size: 11px; color: var(--muted); white-space: nowrap; }
.deck-item .meta .due-num { color: #d97706; font-weight: 700; }

.sidebar-foot { margin-top: 12px; padding-top: 12px; border-top: 1px solid var(--border-line); }
.model-info { font-size: 11px; color: var(--muted); overflow-wrap: anywhere; }
.model-info b { color: var(--text); }
.model-info .mock-tag {
  display: inline-block; margin-top: 4px; padding: 1px 7px;
  background: #fef3c7; color: #b45309;
  border-radius: 999px; font-size: 10px; font-weight: 700;
}

/* ---------------------------------------------------------------- main */

.main { flex: 1; min-width: 0; display: flex; flex-direction: column; }

.topbar {
  display: flex; align-items: center; justify-content: space-between; gap: 14px;
  padding: 14px 26px;
  border-bottom: 1px solid var(--border-line);
  background: var(--glass);
  backdrop-filter: blur(14px);
  position: sticky; top: 0; z-index: 10;
  flex-wrap: wrap;
}

.tabs { display: flex; gap: 4px; }
.tabs button {
  background: transparent; border: none; color: var(--muted);
  padding: 8px 14px; font-size: 13px; font-weight: 600; cursor: pointer;
  border-radius: 10px; transition: background .12s, color .12s;
}
.tabs button:hover { background: rgba(224, 231, 255, 0.55); color: var(--text); }
.tabs button.active {
  background: var(--grad-soft);
  color: var(--indigo);
  box-shadow: inset 0 0 0 1px rgba(99, 102, 241, 0.3), 0 4px 12px rgba(79, 70, 229, 0.12);
}

.badge {
  font-size: 10px; background: #e0e7ff; color: #4338ca;   /* indigo-100 / indigo-700 */
  border-radius: 999px; padding: 1px 7px; font-weight: 700; margin-left: 2px;
}
.badge.accent { background: #e0e7ff; color: #4338ca; }
.badge.warn { background: #fef3c7; color: #b45309; }

.topbar-right { display: flex; align-items: center; gap: 10px; }
.deck-title { font-size: 14px; font-weight: 700; color: var(--text); }

.content { padding: 24px 26px 80px; max-width: 1100px; width: 100%; }

.tab { display: grid; gap: 18px; }
.tab.hidden { display: none; }

.panel {
  background: var(--glass);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  padding: 20px;
  backdrop-filter: blur(12px);
  box-shadow: var(--shadow);
}
.panel h2 { margin: 0 0 6px; font-size: 16px; color: var(--text); }
.panel h2 .inline { font-weight: 400; }

.sub { color: var(--muted); font-size: 13px; margin: 0 0 12px; }

.row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; margin: 12px 0; }
.row.options label { display: flex; align-items: center; gap: 6px; font-size: 13px; color: var(--muted); }
.row.options label input { width: 64px; }
.row.options label.model-pick select {
  max-width: 220px; padding: 5px 8px; border-radius: 8px;
  border: 1px solid var(--border-line); background: var(--white); color: var(--text);
  font: 12.5px/1.4 inherit;
}
.row.options label.model-pick select:focus { outline: none; border-color: var(--accent); }

label.chk {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 12.5px; color: var(--muted);
  padding: 6px 10px; border-radius: 999px;
  background: var(--glass);
  border: 1px solid var(--border-line);
  cursor: pointer; user-select: none;
}
label.chk input { width: auto; accent-color: var(--accent); }
label.chk:hover { border-color: var(--accent); }

textarea, input[type="text"].search {
  width: 100%;
  background: var(--glass-strong);
  color: var(--text);
  border: 1px solid var(--border-line);
  border-radius: 10px;
  padding: 11px 12px;
  font: 13px/1.6 Consolas, "Cascadia Mono", monospace;
  resize: vertical;
}
input[type="number"], .search { width: auto; }
input[type="number"] {
  background: var(--glass-strong); color: var(--text);
  border: 1px solid var(--border-line); border-radius: 8px;
  padding: 6px 8px;
}
textarea:focus, input:focus, input:focus-visible {
  outline: none;
  border-color: rgba(79, 70, 229, 0.6);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.12);
}
input[type="text"] { background: var(--glass-strong); color: var(--text); border: 1px solid var(--border-line); border-radius: 8px; padding: 7px 10px; }
input[type="text"] { width: 220px; }

button {
  background: var(--white);
  color: var(--text);
  border: 1px solid var(--border-line-2);
  border-radius: 10px;
  padding: 9px 15px;
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  transition: filter .15s, transform .05s, border-color .15s, box-shadow .2s, background .15s;
}
button:hover { background: var(--hover); border-color: #94a3b8; }
button:active { transform: translateY(1px); }
button:disabled { opacity: .45; cursor: not-allowed; }
button.primary {
  background: var(--grad);
  border-color: transparent; color: #fff;
  box-shadow: var(--glow);
}
button.primary:hover { filter: brightness(1.07); box-shadow: 0 8px 24px rgba(79, 70, 229, 0.35); }
button.ghost { background: transparent; }
button.ghost:hover { background: rgba(224, 231, 255, 0.4); }
button.sm { padding: 6px 12px; font-size: 12px; }
button.danger:hover { border-color: var(--rose); color: var(--rose); background: rgba(225, 29, 72, 0.06); }

.file-btn {
  display: inline-block; cursor: pointer; font-size: 13px;
  background: var(--white); border: 1px solid var(--border-line-2);
  border-radius: 10px; padding: 9px 15px; font-weight: 600;
  transition: filter .15s, border-color .15s, background .15s;
}
.file-btn:hover { filter: brightness(0.98); background: var(--hover); border-color: #94a3b8; }
.file-btn input { display: none; }

.status { font-size: 12px; color: var(--muted); }
.status.err { color: var(--rose); }
.status.ok { color: var(--emerald); }

/* ---------------------------------------------------------------- progress */

.progress { margin-top: 4px; }
.progress.hidden, .hidden { display: none; }
.bar {
  height: 8px; border-radius: 999px;
  background: var(--border-line); overflow: hidden;
  border: 1px solid var(--border-line);
}
.fill {
  height: 100%; width: 0%;
  background: var(--grad);
  border-radius: 999px;
  box-shadow: 0 0 10px rgba(79, 70, 229, 0.4);
  transition: width .4s ease;
}
#genStatus { margin-top: 8px; }
.bar.indeterminate .fill { width: 30%; animation: slide 1.2s ease-in-out infinite; }
@keyframes slide { 0% { margin-left: -30%; } 100% { margin-left: 100%; } }

/* ---------------------------------------------------------------- card grid */

.toolbar { display: flex; align-items: center; gap: 12px; margin-bottom: 14px; flex-wrap: wrap; }
.toolbar h2 { margin: 0; }
.toolbar .search { max-width: 280px; }
.toolbar .search { width: auto; }
.spacer { flex: 1; }
.hint { font-size: 12px; color: var(--muted); }

.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 14px;
}

.flip-card { perspective: 1100px; }
.flip-card .flip-inner {
  position: relative; width: 100%; height: 150px;
  transform-style: preserve-3d;
  transition: transform .45s cubic-bezier(.4, .2, .2, 1);
  cursor: pointer;
}
.flip-card.flipped .flip-inner { transform: rotateY(180deg); }
.flip-card.big .flip-inner { height: 260px; }

.face {
  position: absolute; inset: 0;
  backface-visibility: hidden; -webkit-backface-visibility: hidden;
  border-radius: 12px;
  border: 1px solid var(--border-soft);
  background: var(--white);
  box-shadow: 0 8px 22px rgba(12, 74, 110, 0.08);
  padding: 16px;
  display: flex; flex-direction: column;
  overflow: hidden;
}
.flip-card:not(.flipped) .face.front { transition: box-shadow .25s, transform .25s; }
.flip-card:not(.flipped):hover .face.front {
  box-shadow: 0 12px 30px rgba(79, 70, 229, 0.16);
  transform: translateY(-2px);
}

.face .face-text {
  flex: 1; font-size: 14px; overflow-y: auto;
  display: flex; align-items: center;
  color: var(--charcoal);
}
.face.back .face-text { align-items: flex-start; }
.face .face-meta {
  margin-top: 8px; padding-top: 8px;
  border-top: 1px solid var(--border-line);
  display: flex; gap: 6px; align-items: center; flex-wrap: wrap;
  font-size: 11px; color: var(--muted);
}
.face.back {
  transform: rotateY(180deg);
  border-color: rgba(5, 150, 105, 0.3);
  background: linear-gradient(160deg, #ecfdf5, #f0fdff); /* emerald-50 â†’ cyan-50 */
}

.chip {
  background: #e0f2fe; color: #0369a1;                 /* sky-100 / sky-700 */
  border: 1px solid rgba(3, 105, 161, 0.15);
  border-radius: 999px; padding: 1px 8px; font-size: 10px; font-weight: 700;
}
.chip.tags { background: var(--chip-bg); color: var(--muted); border-color: transparent; font-weight: 600; }

mark, .cloze-hl {
  background: #fef08a; color: #451a03;                /* yellow-200 highlighter / amber-950 */
  border-radius: 4px; padding: 0 3px; font-weight: 700;
}

.card-actions { display: flex; gap: 6px; margin-top: 8px; }
.card-actions button { padding: 5px 10px; font-size: 11px; background: var(--hover); }

.card-editor { width: 100%; }
.card-editor textarea { min-height: 54px; margin-bottom: 6px; font-size: 12px; }
.card-editor .controls { display: flex; gap: 6px; justify-content: flex-end; }
.card-editor .controls button { padding: 5px 12px; font-size: 11px; }
.card-editor .save { background: var(--emerald); border-color: var(--emerald); color: #fff; }

.empty { text-align: center; padding: 42px 20px; color: var(--muted); }
.empty-title { font-size: 16px; font-weight: 700; color: var(--text); margin-bottom: 6px; }
.empty p { margin: 0; font-size: 13px; }

/* ---------------------------------------------------------------- review */

.review-stage { max-width: 640px; margin: 0 auto; }
.review-flip { margin-bottom: 14px; }
.review-actions { display: flex; gap: 8px; justify-content: center; flex-wrap: wrap; }
.review-actions button { min-width: 84px; }
.review-actions .q1 { border-color: #fda4af; color: #be123c; }
.review-actions .q3 { border-color: #fcd34d; color: #b45309; }
.review-actions .q4 { border-color: #6ee7b7; color: #047857; }
.review-actions .q5 { background: linear-gradient(135deg, #10b981, #06b6d4); border-color: transparent; color: #fff; box-shadow: 0 5px 16px rgba(16, 185, 129, 0.3); }
.review-progress { text-align: center; color: var(--muted); font-size: 12px; margin-top: 12px; }
.review-result { text-align: center; font-size: 13px; margin-top: 10px; }
.review-result.ok { color: var(--emerald); }
.review-result .interval-line { color: var(--muted); font-size: 12px; }

/* ---------------------------------------------------------------- quiz */

.quiz-box { max-width: 720px; margin: 0 auto; }
.quiz-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; color: var(--muted); font-size: 13px; }
.quiz-q { font-size: 16px; font-weight: 700; margin-bottom: 14px; color: var(--text); }
.quiz-opts { display: grid; gap: 8px; margin-bottom: 12px; }
.quiz-opt {
  display: flex; align-items: center; gap: 10px; text-align: left;
  background: var(--white); padding: 11px 14px;
  border-radius: 11px;
  box-shadow: 0 2px 8px rgba(12, 74, 110, 0.04);
}
.quiz-opt:hover:not(.locked):not(.correct):not(.wrong) { border-color: rgba(99, 102, 241, 0.55); background: var(--hover); }
.quiz-opt .key { color: var(--muted); font-weight: 700; font-size: 12px; min-width: 18px; }
.quiz-opt.correct { border-color: rgba(5, 150, 105, 0.6); background: #ecfdf5; box-shadow: 0 0 14px rgba(5, 150, 105, 0.12); }
.quiz-opt.wrong { border-color: rgba(225, 29, 72, 0.55); background: var(--wrong-bg); }
.quiz-opt.locked { opacity: .7; }
.quiz-opt.locked:not(.correct):not(.wrong) { opacity: .4; }
.quiz-expl {
  font-size: 13px; color: var(--muted);
  border-top: 1px dashed var(--border-line-2); padding-top: 10px; margin-bottom: 12px;
  min-height: 18px;
}
.quiz-nav { display: flex; gap: 8px; align-items: center; justify-content: space-between; }
.quiz-nav .nav-btns { display: flex; gap: 8px; }
.quiz-list { margin-top: 26px; border-top: 1px solid var(--border-line); padding-top: 14px; }
.quiz-list-title { font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: 1.2px; margin-bottom: 8px; }
.quiz-entry {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 10px; border-radius: 9px; cursor: pointer;
  font-size: 13px; color: var(--muted);
}
.quiz-entry:hover { background: rgba(224, 231, 255, 0.55); color: var(--text); }
.quiz-entry.active {
  background: var(--grad-soft); color: var(--indigo); font-weight: 600;
  box-shadow: inset 0 0 0 1px rgba(99, 102, 241, 0.3);
}
.quiz-entry .acc { margin-left: auto; font-size: 11px; }
.quiz-entry .del { margin-left: 6px; padding: 2px 8px; font-size: 11px; }
.acc-good { color: var(--emerald); } .acc-bad { color: #d97706; } .acc-none { color: var(--muted); }

/* ---------------------------------------------------------------- toasts */

.toasts {
  position: fixed; bottom: 20px; right: 20px; z-index: 100;
  display: flex; flex-direction: column; gap: 8px; max-width: 340px;
}
.toast {
  background: var(--glass-strong);
  border: 1px solid var(--border-line);
  border-left: 3px solid #6366f1;
  backdrop-filter: blur(10px);
  padding: 11px 14px; border-radius: 11px;
  font-size: 13px; color: var(--text);
  box-shadow: var(--shadow);
  animation: toast-in .25s ease;
}
.toast.ok { border-left-color: var(--emerald); }
.toast.err { border-left-color: var(--rose); }
.toast.out { animation: toast-out .3s ease forwards; }
@keyframes toast-in { from { transform: translateY(10px); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes toast-out { to { transform: translateY(8px); opacity: 0; } }

/* ---------------------------------------------------------------- modal */

.modal-backdrop {
  position: fixed; inset: 0; z-index: 90;
  background: rgba(15, 23, 42, 0.25);
  display: grid; place-items: center;
  backdrop-filter: blur(4px);
}
.modal {
  width: min(420px, 90vw);
  background: var(--glass-strong);
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  padding: 22px;
  backdrop-filter: blur(14px);
  box-shadow: 0 20px 50px rgba(12, 74, 110, 0.15);
}
.modal h3 { margin: 0 0 12px; font-size: 15px; color: var(--text); }
.modal .row { margin: 0; }
.modal .actions { display: flex; gap: 8px; justify-content: flex-end; margin-top: 16px; }
.modal .actions .confirm { background: var(--rose); border-color: var(--rose); color: #fff; }

.prefs-row { display: flex; align-items: center; gap: 12px; margin: 12px 0; }
.prefs-row label { font-size: 13px; font-weight: 600; color: var(--text); width: 76px; flex-shrink: 0; }
.seg { display: flex; gap: 4px; background: var(--chip-bg); border: 1px solid var(--border-line); border-radius: 10px; padding: 3px; }
.seg button { border: none; background: transparent; color: var(--muted); font-size: 12px; padding: 6px 12px; border-radius: 8px; cursor: pointer; }
.seg button:hover { color: var(--text); }
.seg button.active { background: var(--grad); color: #fff; font-weight: 600; box-shadow: var(--glow); }
.accents { display: flex; gap: 8px; }
.accents button {
  width: 26px; height: 26px; border-radius: 50%; border: 2px solid transparent; cursor: pointer;
  background: var(--sw); box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.25);
}
.accents button:hover { transform: scale(1.1); }
.accents button.active { border-color: var(--text); box-shadow: 0 0 0 3px var(--glow); }
.icon-btn {
  background: transparent; border: none; color: var(--muted); font-size: 17px;
  width: 34px; height: 34px; border-radius: 10px; cursor: pointer; line-height: 1;
}
.icon-btn:hover { color: var(--text); background: var(--hover); }

.tips ul { margin: 8px 0 0; padding-left: 18px; font-size: 13px; color: var(--muted); }
.tips li { margin-bottom: 6px; }
.tips strong { color: var(--text); }

/* ---------------------------------------------------------------- responsive */

#menuBtn, .sidebar-backdrop { display: none; }

@media (max-width: 820px) {
  #menuBtn { display: inline-flex; }
  .app { flex-direction: column; }
  .sidebar {
    position: fixed;
    inset: 0 auto 0 0;
    width: 286px;
    height: 100%;
    flex-direction: column;
    align-items: stretch;
    z-index: 60;
    transform: translateX(-104%);
    transition: transform .22s ease;
    box-shadow: none;
  }
  .sidebar.open { transform: none; box-shadow: 0 12px 44px rgba(12, 74, 110, 0.28); }
  .sidebar-backdrop {
    display: block;
    position: fixed; inset: 0; z-index: 55;
    background: rgba(15, 23, 42, 0.4);
    opacity: 0; pointer-events: none;
    transition: opacity .2s ease;
  }
  .sidebar-backdrop.show { opacity: 1; pointer-events: auto; }
  .deck-list { flex-direction: column; align-items: stretch; }
  .deck-item { padding: 10px 12px; }
  .tabs { overflow-x: auto; flex-wrap: nowrap; -webkit-overflow-scrolling: touch; scrollbar-width: none; }
  .tabs::-webkit-scrollbar { display: none; }
  .topbar { padding: 12px 16px; }
  .content { padding: 16px 16px 80px; }
  .topbar-right .deck-title { display: none; }
  .card-grid { grid-template-columns: 1fr; }
}

/* ---------------------------------------------------------------- platform-aware */

body[data-platform="android"] button { min-height: 42px; }
body[data-platform="android"] .tabs button { padding: 10px 16px; }
body[data-platform="android"] .deck-item { padding: 12px; }
body[data-platform="android"] .new-deck, body[data-platform="android"] .file-btn { padding: 12px 16px; }
body[data-platform="android"] .row.options label input[type="number"] { width: 76px; padding: 9px; }
body[data-platform="android"] .quiz-opt { padding: 14px 16px; }
body[data-platform="android"] .review-actions button { min-height: 48px; flex: 1; min-width: 0; }
body[data-platform="android"] .review-actions { gap: 6px; }

body[data-platform="desktop"] .content { max-width: 1280px; }

.platform-chip {
  font-size: 11px; font-weight: 700; color: var(--accent);
  border: 1px solid rgba(2, 132, 199, 0.25);
  background: rgba(2, 132, 199, 0.08);
  padding: 3px 10px; border-radius: 999px;
  letter-spacing: .3px; white-space: nowrap;
}

button:focus-visible, .file-btn:focus-visible, .deck-item:focus-visible,
.quiz-opt:focus-visible, select:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.empty-icon {
  width: 46px; height: 46px; margin: 0 auto 12px;
  display: grid; place-items: center;
  border-radius: 14px;
  background: var(--grad-soft);
  color: var(--indigo);
}
.empty-icon svg { width: 24px; height: 24px; }

#generateBtn.busy::before {
  content: "";
  width: 12px; height: 12px; margin-right: 8px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.35);
  border-top-color: #fff;
  display: inline-block;
  vertical-align: -2px;
  animation: spin .7s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

metadata.preview:
"use strict";

/* ---------------------------------------------------------------- state */

const S = {
  decks: [],
  deckId: null,
  deck: null, // {id, name, cards: [], mcqs: []}
  tab: "generate",
  job: null, // job id being polled
  filter: "",
  review: [], // due cards being reviewed this session
  reviewIdx: 0,
  quizIdx: 0,
  quizAnswered: {}, // mcq id -> user choice
  quizScore: { answered: 0, correct: 0 },
  model: null,
  modalOpen: false,
};

display.text:
"use strict";

/* ---------------------------------------------------------------- state */

const S = {
  decks: [],
  deckId: null,
  deck: null, // {id, name, cards: [], mcqs: []}
  tab: "generate",
  job: null, // job id being polled
  filter: "",
  review: [], // due cards being reviewed this session
  reviewIdx: 0,
  quizIdx: 0,
  quizAnswered: {}, // mcq id -> user choice
  quizScore: { answered: 0, correct: 0 },
  model: null,
  modalOpen: false,
};

const $ = (id) => document.getElementById(id);

/* ---------------------------------------------------------------- platform */

function detectPlatform() {
  const p = new URLSearchParams(location.search).get("platform");
  if (p === "android" || p === "desktop") return p;
  return /FlashcardQuiz/i.test(navigator.userAgent) ? "android" : "web";
}

const PLATFORM = detectPlatform();
document.body.dataset.platform = PLATFORM;

const SAMPLE = `Cell Biology — Lecture 01

The mitochondrion is the powerhouse of the cell, responsible for producing ATP via cellular respiration.

DNA replication: Helicase unwinds the double helix by breaking hydrogen bonds between base pairs. DNA Polymerase synthesizes the new complementary strand in the 5' to 3' direction. RNA Primase lays down short RNA primers to initiate synthesis. DNA Ligase seals nicks in the sugar-phosphate backbone.

Protein synthesis happens at the ribosome, where mRNA codons are translated into amino acid chains.

The Golgi apparatus modifies, sorts, and packages proteins for secretion.

The nucleus stores genetic material as chromatin and coordinates cell activities.`;

/* ---------------------------------------------------------------- helpers */

async function api(path, options = {}) {
  const res = await fetch(path, {
    headers:
      options.body && !(options.body instanceof FormData)
        ? { "Content-Type": "application/json" }
        : {},
    ...options,
  });
  if (!res.ok) {
    let detail = res.statusText;
    try { detail = (await res.json()).detail || detail; } catch (_) {}
    throw new Error(detail);
  }
  return res.json();
}

function esc(s) {
  return String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
}

function clozeHtml(text) {
  return esc(text).replace(/\{\{c\d+::(.*?)\}\}/g, '<mark>$1</mark>');
}

function today() {
  return new Date().toISOString().slice(0, 10);
}

function toast(msg, kind = "") {
  const box = document.createElement("div");
  box.className = "toast " + kind;
  box.textContent = msg;
  $("toasts").appendChild(box);
  setTimeout(() => {
    box.classList.add("out");
    setTimeout(() => box.remove(), 320);
  }, 3200);
}

/* ---------------------------------------------------------------- modal */

function openModal(title, bodyHtml) {
  const root = document.createElement("div");
  root.className = "modal-backdrop";
  root.innerHTML = `<div class="modal"><h3>${esc(title)}</h3>${bodyHtml}</div>`;
  $("modalRoot").appendChild(root);
  S.modalOpen = true;
  const close = () => {
    if (!root.isConnected) return;
    S.modalOpen = false;
    root.remove();
  };
  root.addEventListener("click", (e) => { if (e.target === root) close(); });
  return { root, close, $: (sel) => root.querySelector(sel) };
}

function confirmModal(title, message, confirmLabel = "Confirm") {
  return new Promise((resolve) => {
    const m = openModal(
      title,
      `<p style="color:var(--muted);font-size:13px;margin:0">${esc(message)}</p>
       <div class="actions">
         <button data-cancel>Cancel</button>
         <button class="confirm" data-confirm>${esc(confirmLabel)}</button>
       </div>`
    );
    m.$("[data-cancel]").onclick = () => { m.close(); resolve(false); };
    m.$("[data-confirm]").onclick = () => { m.close(); resolve(true); };
  });
}

/* ---------------------------------------------------------------- prefs */

const PALETTES = {
  indigo: { accent: "#4f46e5", indigo: "#4f46e5", cyan: "#06b6d4" },
  cyan: { accent: "#0284c7", indigo: "#0284c7", cyan: "#06b6d4" },
  emerald: { accent: "#059669", indigo: "#059669", cyan: "#14b8a6" },
  rose: { accent: "#e11d48", indigo: "#e11d48", cyan: "#f43f5e" },
  amber: { accent: "#d97706", indigo: "#d97706", cyan: "#f59e0b" },
};

function loadPrefs() {
  try { return Object.assign({ theme: "light", accent: "indigo", size: "normal" }, JSON.parse(localStorage.getItem("fq_prefs") || "{}")); }
  catch (_) { return { theme: "light", accent: "indigo", size: "normal" }; }
}

function savePrefs(prefs) {
  try { localStorage.setItem("fq_prefs", JSON.stringify(prefs)); } catch (_) {}
}

function mediaDark() {
  return window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches;
}

function applyPrefs() {
  const prefs = loadPrefs();
  const theme = prefs.theme === "auto" ? (mediaDark() ? "dark" : "light") : prefs.theme;
  document.documentElement.dataset.theme = theme;
  const p = PALETTES[prefs.accent] || PALETTES.indigo;
  const root = document.documentElement.style;
  root.setProperty("--accent", p.accent);
  root.setProperty("--indigo", p.indigo);
  root.setProperty("--cyan", p.cyan);
  root.setProperty("--grad", `linear-gradient(135deg, ${p.indigo} 0%, ${p.cyan} 100%)`);
  root.setProperty("--glow", `0 6px 20px ${hexA(p.indigo, 0.28)}`);
  for (const cls of ["fs-compact", "fs-large"]) document.documentElement.classList.remove(cls);
  if (prefs.size !== "normal") document.documentElement.classList.add(`fs-${prefs.size}`);
  return prefs;
}

function hexA(hex, a) {
  const n = parseInt(hex.slice(1), 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
}

function openPrefs() {
  const prefs = loadPrefs();
  const tpl = $("prefsTpl");
  const m = openModal("Settings", tpl ? tpl.innerHTML : "");
  const row = (sel, key, onChange) => {
    const els = m.root.querySelectorAll(sel);
    els.forEach((b) => b.classList.toggle("active", b.dataset[key] === String(prefs[key])));
    els.forEach((b) => b.addEventListener("click", () => {
      prefs[key] = b.dataset[key];
      savePrefs(prefs);
      els.forEach((x) => x.classList.toggle("active", x === b));
      onChange && onChange();
    }));
  };
  row('[data-theme]', "theme", applyPrefs);
  row('[data-accent]', "accent", applyPrefs);
  row('[data-size]', "size", applyPrefs);
}

/* ---------------------------------------------------------------- init */

async function init() {
  applyPrefs();
  const mq = window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)");
  if (mq && mq.addEventListener) mq.addEventListener("change", () => { if (loadPrefs().theme === "auto") applyPrefs(); });
  try {
    S.model = await api("/api/settings");
    renderModelInfo();
    await loadModels();
  } catch (_) {}
  await refreshDecks();
  if (S.decks.length) {
    S.deckId = S.decks[0].id;
    resetStudyState();
    await loadDeck();
  }
  renderSidebar();
  bindEvents();
}

async function refreshDecks() {
  S.decks = await api("/api/decks");
}

async function loadDeck() {
  S.deck = await api(`/api/decks/${S.deckId}`);
  renderAll();
}

function resetStudyState() {
  S.quizAnswered = {};
  S.quizIdx = 0;
  S.quizScore = { answered: 0, correct: 0 };
  S.review = [];
  S.reviewIdx = 0;
}

async function selectDeck(id) {
  S.deckId = id;
  resetStudyState();
  await loadDeck();
}

/* ---------------------------------------------------------------- render */

function renderAll() {
  renderSidebar();
  renderHeader();
  renderCards();
  renderReview();
  renderQuiz();
}

function renderSidebar() {
  const list = $("deckList");
  list.innerHTML = "";
  for (const d of S.decks) {
    const li = document.createElement("li");
    li.className = "deck-item" + (d.id === S.deckId ? " active" : "");
    li.innerHTML = `
      <span class="name">${esc(d.name)}</span>
      <span class="meta">${d.cards} cards${d.due ? ' · <span class="due-num">' + d.due + ' due</span>' : ""}</span>`;
    li.onclick = () => selectDeck(d.id);
    list.appendChild(li);
  }
}

function renderHeader() {
  $("deckTitle").textContent = S.deck ? S.deck.name : "—";
  const cards = S.deck ? S.deck.cards.length : 0;
  const due = S.deck ? S.deck.cards.filter((c) => c.due <= today()).length : 0;
  const mcqs = S.deck ? S.deck.mcqs.length : 0;
  $("cardsBadge").textContent = cards;
  $("dueBadge").textContent = due;
  $("dueBadge").className = "badge" + (due ? " warn" : " accent");
  $("quizBadge").textContent = mcqs;
  $("exportBtn").disabled = cards === 0;
}

function renderModelInfo() {
  if (!S.model) return;
  $("modelInfo").innerHTML =
    `<b>${esc(S.model.model)}</b>${S.model.mock ? '<span class="mock-tag">MOCK MODE</span>' : ""}`;
}

async function loadModels() {
  const sel = $("modelSelect");
  try {
    const models = await api("/api/models");
    const cur = JSON.stringify({ base_url: S.model.base_url, model: S.model.model });
    sel.innerHTML = "";
    for (const m of models) {
      const opt = document.createElement("option");
      opt.value = JSON.stringify({ base_url: m.base_url, model: m.model });
      opt.textContent = m.label + (m.base_url.includes("127.0.0.1") ? " (local)" : "");
      if (opt.value === cur) opt.selected = true;
      sel.appendChild(opt);
    }
    sel.disabled = false;
  } catch (_) {
    sel.disabled = true;
  }
}

async function onModelChange() {
  const sel = $("modelSelect");
  if (!sel.value) return;
  const pick = JSON.parse(sel.value);
  try {
    S.model = await api("/api/settings", {
      method: "PATCH",
      body: JSON.stringify(pick),
    });
    renderModelInfo();
    toast(`Model switched to ${pick.model}`, "ok");
  } catch (err) {
    toast("Could not switch model: " + err.message, "err");
    await loadModels();
  }
}

function switchTab(tab) {
  S.tab = tab;
  document.querySelectorAll("#tabs button").forEach((b) => {
    b.classList.toggle("active", b.dataset.tab === tab);
  });
  document.querySelectorAll(".tab").forEach((t) => {
    t.classList.toggle("hidden", t.id !== "tab-" + tab);
  });
  if (tab === "cards") renderCards();
  if (tab === "review") renderReview();
  if (tab === "quiz") renderQuiz();
  if (tab === "generate") loadModels();
}

/* ---------------------------------------------------------------- generate */

function setGenBusy(busy) {
  const b = $("generateBtn");
  b.disabled = busy;
  b.classList.toggle("busy", busy);
  if (busy) {
    if (!b.dataset.idle) b.dataset.idle = b.textContent || "Generate";
    b.textContent = "Generating\u2026";
  } else {
    b.textContent = b.dataset.idle || "Generate";
  }
}

async function startGenerate() {
  const source = $("sourceText").value.trim();
  if (!source) return toast("Add source material first (paste notes or upload a file).", "err");
  const numCards = Math.min(60, Math.max(1, parseInt($("numCards").value, 10) || 10));
  const numMcqs = Math.min(30, Math.max(1, parseInt($("numMcqs").value, 10) || 3));
  const tags = $("tags").value.split(",").map((t) => t.trim()).filter(Boolean);
  setGenBusy(true);
  setProgress(true, "Starting generation...");
  try {
    const res = await api(`/api/decks/${S.deckId}/generate`, {
      method: "POST",
      body: JSON.stringify({
        source_text: source, flashcards: true, mcqs: true,
        num_cards: numCards, num_mcqs: numMcqs, tags,
      }),
    });
    S.job = res.job_id;
    toast("Generation started — cards will appear as they are created.", "ok");
    pollJob();
  } catch (err) {
    setProgress(false);
    toast("Error: " + err.message, "err");
    setGenBusy(false);
  }
}

function setProgress(visible, text) {
  $("genProgress").classList.toggle("hidden", !visible);
  if (text !== undefined) $("genStatus").textContent = text;
}

async function pollJob() {
  if (!S.job) return;
  let job;
  try {
    job = await api(`/api/jobs/${S.job}`);
  } catch (_) {
    setProgress(false);
    S.job = null;
    setGenBusy(false);
    return;
  }
  const total = job.target_cards + job.target_mcqs;
  const done = job.cards + job.mcqs;
  const fill = $("genFill");
  fill.classList.toggle("indeterminate", job.status === "running" && done === 0);
  fill.style.width = total ? Math.round((done / total) * 100) + "%" : "0%";

  // live refresh: badges + card grid, without disturbing a review/quiz session
  if (job.cards || job.mcqs) {
    try {
      S.deck = await api(`/api/decks/${S.deckId}`);
      renderSidebar();
      renderHeader();
      if (S.tab === "cards") renderCards();
    } catch (_) {}
  }

  if (job.status === "running") {
    setProgress(true, `Generating... ${job.cards}/${job.target_cards} cards, ${job.mcqs}/${job.target_mcqs} questions`);
    setTimeout(pollJob, 1600);
    return;
  }
  if (job.status === "paused") {
    const when = job.reset_ms ? new Date(job.reset_ms).toLocaleTimeString() : "soon";
    const mins = Math.max(1, Math.round(job.wait_s / 60));
    setProgress(true, `Rate limit hit — auto-resuming at ${when} (~${mins} min). Adding 10 credits on OpenRouter unlocks 1000 free req/day.`);
    setTimeout(pollJob, 15000);
    return;
  }
  setProgress(false);
  if (job.status === "error") {
    toast("Generation failed: " + (job.error || "unknown error"), "err");
  } else {
    toast(`Done: ${job.cards} cards, ${job.mcqs} questions added.`, "ok");
  }
  S.job = null;
  setGenBusy(false);
  await loadDeck();
}

/* ---------------------------------------------------------------- cards */

function renderCards() {
  const grid = $("cardGrid");
  const q = S.filter.toLowerCase();
  const cards = (S.deck ? S.deck.cards : []).filter((c) => {
    if (!q) return true;
    return ((c.front || c.text) + " " + (c.back || "")).toLowerCase().includes(q);
  });
  $("cardCount").textContent = `${cards.length} of ${S.deck ? S.deck.cards.length : 0} cards`;
  $("cardsEmpty").classList.toggle("hidden", cards.length > 0);
  grid.innerHTML = "";
  cards.forEach((card) => grid.appendChild(cardEl(card)));
}

function cardEl(card) {
  const wrap = document.createElement("div");
  wrap.className = "flip-card";
  const isCloze = card.type === "Cloze";
  const front = isCloze ? clozeHtml(card.text) : esc(card.front);
  const back = esc(card.back || (isCloze ? "Cloze card — hidden terms are revealed when imported into Anki." : ""));
  wrap.innerHTML = `
    <div class="flip-inner">
      <div class="face front">
        <div class="face-text">${front || '<span style="opacity:.5">(empty)</span>'}</div>
        <div class="face-meta">
          <span class="chip">${card.type}</span>
          ${(card.tags || []).slice(0, 3).map((t) => `<span class="chip tags">#${esc(t)}</span>`).join("")}
          ${card.source ? `<span style="margin-left:auto">${esc(card.source)}</span>` : ""}
        </div>
      </div>
      <div class="face back">
        <div class="face-text">${back || '<span style="opacity:.5">No answer</span>'}</div>
        <div class="face-meta">
          <span class="chip" style="background:rgba(52,199,123,.15);color:var(--ok)">Answer</span>
          ${card.source ? `<span style="margin-left:auto">${esc(card.source)}</span>` : ""}
        </div>
      </div>
    </div>
    <div class="card-actions">
      <button data-act="edit">Edit</button>
      <button data-act="del">Delete</button>
    </div>`;
  wrap.querySelector(".flip-inner").onclick = () => wrap.classList.toggle("flipped");
  wrap.querySelector('[data-act="edit"]').onclick = () => editCardModal(card);
  wrap.querySelector('[data-act="del"]').onclick = () => deleteCard(card);
  return wrap;
}

function editCardModal(card) {
  const isCloze = card.type === "Cloze";
  const m = openModal(
    "Edit card",
    `<label style="font-size:12px;color:var(--muted)">Front / Cloze text</label>
     <textarea id="editFront" rows="3">${esc(isCloze ? card.text : card.front)}</textarea>
     ${isCloze ? "" : '<label style="font-size:12px;color:var(--muted);display:block;margin-top:8px">Back</label>'}
     ${isCloze ? "" : `<textarea id="editBack" rows="2">${esc(card.back)}</textarea>`}
     <div class="actions">
       <button data-cancel>Cancel</button>
       <button class="primary" data-save>Save</button>
     </div>`
  );
  m.$("[data-save]").onclick = async () => {
    const body = isCloze
      ? { text: m.$("#editFront").value }
      : { front: m.$("#editFront").value, back: m.$("#editBack").value };
    try {
      await api(`/api/decks/${S.deckId}/cards/${card.id}`, { method: "PATCH", body: JSON.stringify(body) });
      m.close();
      await loadDeck();
      toast("Card updated.", "ok");
    } catch (err) {
      toast("Error: " + err.message, "err");
    }
  };
  m.$("[data-cancel]").onclick = () => m.close();
}

async function deleteCard(card) {
  const ok = await confirmModal(
    "Delete card",
    `"${(card.front || card.text).slice(0, 60)}..." will be permanently removed.`,
    "Delete"
  );
  if (!ok) return;
  await api(`/api/decks/${S.deckId}/cards/${card.id}`, { method: "DELETE" });
  await loadDeck();
  toast("Card deleted.", "ok");
}

/* ---------------------------------------------------------------- review */

async function renderReview() {
  const area = $("reviewArea");
  $("reviewDueCount").textContent = S.deck ? S.deck.cards.filter((c) => c.due <= today()).length : 0;

  if (!S.review.length) {
    const due = S.deck ? S.deck.cards.filter((c) => c.due <= today()) : [];
    if (!due.length) {
      area.innerHTML = `
        <div class="empty">
          <div class="empty-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg></div>
          <div class="empty-title">All caught up</div>
          <p>No cards are due today. Generate more cards or come back tomorrow — SM-2 schedules each card's next review.</p>
        </div>`;
      return;
    }
    S.review = due;
    S.reviewIdx = 0;
  }

  const card = S.review[S.reviewIdx];
  const isCloze = card.type === "Cloze";
  const front = isCloze ? clozeHtml(card.text) : esc(card.front);
  const back = esc(card.back || "");
  area.innerHTML = `
    <div class="review-stage">
      <div class="flip-card big review-flip">
        <div class="flip-inner">
          <div class="face front">
            <div class="face-text" style="justify-content:center;text-align:center;font-size:17px">${front}</div>
            <div class="face-meta"><span class="chip">${card.type}</span><span style="margin-left:auto;opacity:.8">Click to reveal</span></div>
          </div>
          <div class="face back">
            <div class="face-text" style="justify-content:center;text-align:center;font-size:16px">${back}</div>
            <div class="face-meta"><span class="chip" style="background:rgba(52,199,123,.15);color:var(--ok)">Answer</span></div>
          </div>
        </div>
      </div>
      <div class="review-actions" id="qualityBtns">
        <button class="q1" data-q="1">Again (1)</button>
        <button class="q3" data-q="3">Hard (2)</button>
        <button class="q4" data-q="4">Good (3)</button>
        <button class="q5" data-q="5">Easy (4)</button>
      </div>
      <div class="review-progress">${S.reviewIdx + 1} of ${S.review.length} due · press 1–4 on the keyboard</div>
      <div id="reviewResult" class="review-result"></div>
    </div>`;
  area.querySelector(".flip-inner").onclick = () =>
    area.querySelector(".flip-card").classList.toggle("flipped");
  area.querySelector("#qualityBtns").addEventListener("click", (e) => {
    const btn = e.target.closest("button[data-q]");
    if (btn) submitReview(card, parseInt(btn.dataset.q, 10));
  });
}

async function submitReview(card, quality) {
  if (!S.review.includes(card)) return; // already submitted (double keypress)
  const labels = { 1: "Again", 3: "Hard", 4: "Good", 5: "Easy" };
  try {
    const res = await api("/api/review", {
      method: "POST",
      body: JSON.stringify({ deck_id: S.deckId, card_id: card.id, quality }),
    });
    S.review = S.review.filter((c) => c !== card);
    const result = $("reviewResult");
    if (result) {
      result.innerHTML = `${labels[quality]} — next review in <b>${res.interval}</b> day${res.interval === 1 ? "" : "s"} (ease ${res.ease.toFixed(2)})`;
      result.className = "review-result ok";
    }
    if (S.review.length) {
      setTimeout(() => { S.reviewIdx = 0; renderReview(); }, 700);
    } else {
      setTimeout(() => {
        S.review = [];
        S.reviewIdx = 0;
        renderReview();
        toast("Review session complete. Well done!", "ok");
        loadDeck();
      }, 900);
    }
  } catch (err) {
    toast("Error: " + err.message, "err");
  }
}

/* ---------------------------------------------------------------- quiz */

function renderQuiz() {
  const area = $("quizArea");
  const mcqs = S.deck ? S.deck.mcqs : [];
  $("quizSessionScore").textContent = S.quizScore.answered
    ? `Session: ${S.quizScore.correct}/${S.quizScore.answered} correct (${Math.round((S.quizScore.correct / S.quizScore.answered) * 100)}%)`
    : "";
  if (!mcqs.length) {
    area.innerHTML = `
      <div class="empty">
        <div class="empty-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/></svg></div>
        <div class="empty-title">No questions yet</div>
        <p>Generate MCQs from your notes on the Generate tab, then test yourself here.</p>
      </div>`;
    return;
  }
  S.quizIdx = Math.min(S.quizIdx, mcqs.length - 1);
  const m = mcqs[S.quizIdx];
  const chosen = S.quizAnswered[m.id];
  const answered = chosen !== undefined;

  let html = `
    <div class="quiz-box">
      <div class="quiz-head">
        <span>Question ${S.quizIdx + 1} of ${mcqs.length}</span>
        <span>${m.answered ? "Accuracy: " + Math.round((m.correct / m.answered) * 100) + "%" : "Not answered yet"}</span>
      </div>
      <div class="quiz-q">${esc(m.question)}</div>
      <div class="quiz-opts">`;
  const keys = ["1", "2", "3", "4"];
  m.options.forEach((opt, i) => {
    let cls = "quiz-opt";
    if (answered) {
      if (i === m.correct_index) cls += " correct";
      else if (i === chosen) cls += " wrong";
      else cls += " locked";
    }
    html += `<button class="${cls}" data-choice="${i}"><span class="key">${keys[i]}</span>${esc(opt)}</button>`;
  });
  const expl = answered
    ? (chosen === m.correct_index ? m.explanation : (m.distractor_explanations[String(chosen)] || m.explanation))
    : "";
  html += `</div>
      <div class="quiz-expl">${answered ? esc(expl) : ""}</div>
      <div class="quiz-nav">
        <div class="nav-btns">
          <button id="quizPrev">← Prev</button>
          <button id="quizNext">Next →</button>
        </div>
        <button id="quizSkip" class="ghost sm">${answered ? "Next question" : "Skip"}</button>
      </div>
    </div>
    <div class="quiz-list">
      <div class="quiz-list-title">All questions</div>
      ${mcqs.map((q, i) => {
        const acc = q.answered ? Math.round((q.correct / q.answered) * 100) + "%" : "—";
        const accCls = !q.answered ? "acc-none" : q.correct / q.answered >= 0.6 ? "acc-good" : "acc-bad";
        return `<div class="quiz-entry ${i === S.quizIdx ? "active" : ""}" data-i="${i}">
          <span>Q${i + 1}</span>
          <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(q.question)}</span>
          <span class="acc ${accCls}">${acc}</span>
          <button class="del" data-del="${q.id}">Delete</button>
        </div>`;
      }).join("")}
    </div>`;

  area.innerHTML = html;

  area.querySelectorAll(".quiz-opt").forEach((btn) => {
    btn.onclick = () => answerQuiz(m, parseInt(btn.dataset.choice, 10));
  });
  area.querySelector("#quizPrev").onclick = () => { S.quizIdx = (S.quizIdx - 1 + mcqs.length) % mcqs.length; renderQuiz(); };
  area.querySelector("#quizNext").onclick = () => { S.quizIdx = (S.quizIdx + 1) % mcqs.length; renderQuiz(); };
  area.querySelector("#quizSkip").onclick = () => { S.quizIdx = (S.quizIdx + 1) % mcqs.length; renderQuiz(); };
  area.querySelectorAll(".quiz-entry").forEach((entry) => {
    entry.onclick = (e) => {
      if (e.target.classList.contains("del")) return;
      S.quizIdx = parseInt(entry.dataset.i, 10);
      renderQuiz();
    };
  });
  area.querySelectorAll(".quiz-entry .del").forEach((btn) => {
    btn.onclick = async () => {
      const ok = await confirmModal("Delete question", "This multiple-choice question will be removed.", "Delete");
      if (!ok) return;
      await api(`/api/decks/${S.deckId}/mcqs/${btn.dataset.del}`, { method: "DELETE" });
      await loadDeck();
      toast("Question deleted.", "ok");
    };
  });
}

async function answerQuiz(m, choice) {
  if (S.quizAnswered[m.id] !== undefined) return;
  try {
    const res = await api(`/api/decks/${S.deckId}/quiz/answer`, {
      method: "POST",
      body: JSON.stringify({ mcq_id: m.id, choice }),
    });
    S.quizAnswered[m.id] = choice;
    S.quizScore.answered++;
    if (res.correct) S.quizScore.correct++;
    m.answered = (m.answered || 0) + 1;
    m.correct = (m.correct || 0) + (res.correct ? 1 : 0);
    renderQuiz();
    toast(res.correct ? "Correct!" : "Not quite — check the explanation.", res.correct ? "ok" : "err");
  } catch (err) {
    toast("Error: " + err.message, "err");
  }
}

/* ---------------------------------------------------------------- decks */

function createDeck() {
  const m = openModal(
    "New deck",
    `<input type="text" id="deckName" placeholder="e.g. Lecture 02 — Genetics" style="width:100%" />
     <div class="actions">
       <button data-cancel>Cancel</button>
       <button class="primary" data-create>Create</button>
     </div>`
  );
  const doCreate = async () => {
    const name = m.$("#deckName").value.trim();
    if (!name) { m.$("#deckName").focus(); return; }
    try {
      const deck = await api("/api/decks", { method: "POST", body: JSON.stringify({ name }) });
      m.close();
      await refreshDecks();
      await selectDeck(deck.id);
      toast(`Deck "${name}" created.`, "ok");
    } catch (err) {
      toast("Error: " + err.message, "err");
    }
  };
  m.$("[data-create]").onclick = doCreate;
  m.$("[data-cancel]").onclick = () => m.close();
  m.$("#deckName").onkeydown = (e) => { if (e.key === "Enter") doCreate(); };
  m.$("#deckName").focus();
}

async function deleteDeck() {
  if (!S.deck) return;
  const ok = await confirmModal(
    "Delete deck",
    `Deck "${S.deck.name}" and all its cards and questions will be permanently deleted.`,
    "Delete"
  );
  if (!ok) return;
  await api(`/api/decks/${S.deckId}`, { method: "DELETE" });
  await refreshDecks();
  S.deckId = S.decks.length ? S.decks[0].id : null;
  if (S.deckId) await selectDeck(S.deckId);
  else { S.deck = null; resetStudyState(); renderAll(); }
  toast("Deck deleted.", "ok");
}

/* ---------------------------------------------------------------- export */

async function exportDeck() {
  if (!S.deck || !S.deck.cards.length) return;
  try {
    const res = await fetch(`/api/decks/${S.deckId}/export`);
    if (!res.ok) throw new Error((await res.json().catch(() => ({}))).detail || "export failed");
    const blob = await res.blob();
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = (S.deck.name || "deck").replace(/[^a-zA-Z0-9 _-]/g, "").replace(/\s+/g, "_") + ".apkg";
    a.click();
    URL.revokeObjectURL(a.href);
    toast("Deck exported — import the .apkg in Anki (File → Import).", "ok");
  } catch (err) {
    toast("Error: " + err.message, "err");
  }
}

/* ---------------------------------------------------------------- events */

function bindEvents() {
  if (PLATFORM !== "web") {
    const chip = $("platformChip");
    chip.textContent = PLATFORM === "android" ? "Android app" : "Desktop app";
    chip.hidden = false;
  }
  const sidebar = $("sidebar");
  const backdrop = $("sidebarBackdrop");
  const setDrawer = (open) => {
    sidebar.classList.toggle("open", open);
    backdrop.classList.toggle("show", open);
  };
  $("menuBtn").onclick = () => setDrawer(!sidebar.classList.contains("open"));
  backdrop.onclick = () => setDrawer(false);

  document.querySelectorAll("#tabs button").forEach((b) => {
    b.onclick = () => switchTab(b.dataset.tab);
  });
  $("generateBtn").onclick = startGenerate;
  $("sourceText").addEventListener("keydown", (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key === "Enter") {
      e.preventDefault();
      startGenerate();
    }
  });
  $("modelSelect").onchange = onModelChange;
  $("exportBtn").onclick = exportDeck;
  $("prefsBtn").onclick = openPrefs;
  $("newDeckBtn").onclick = createDeck;
  $("deleteDeckBtn").onclick = deleteDeck;
  $("loadSample").onclick = () => {
    $("sourceText").value = SAMPLE;
    toast("Sample notes loaded.", "ok");
  };
  $("cardFilter").oninput = (e) => {
    S.filter = e.target.value;
    renderCards();
  };
  $("fileInput").onchange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const fd = new FormData();
    fd.append("file", file);
    fd.append("use_ocr", String($("ocrToggle").checked));
    $("fileStatus").textContent = "Reading file...";
    try {
      const res = await api("/api/upload", { method: "POST", body: fd });
      $("sourceText").value = res.text;
      const ocrNote = res.ocr ? " (OCR)" : "";
      $("fileStatus").textContent = `Loaded ${file.name}${ocrNote} (${res.text.length.toLocaleString()} chars).`;
      $("fileStatus").className = "status ok";
      toast("Source material loaded." + ocrNote, "ok");
    } catch (err) {
      $("fileStatus").textContent = "Error: " + err.message;
      $("fileStatus").className = "status err";
    }
    e.target.value = "";
  };

  document.addEventListener("keydown", (e) => {
    if (S.modalOpen || e.ctrlKey || e.metaKey || e.altKey) return;
    if (e.target.matches("input, textarea")) return;
    const num = parseInt(e.key, 10);
    if (!num || num < 1 || num > 4) return;
    if (S.tab === "review" && S.review.length) {
      submitReview(S.review[S.reviewIdx], [1, 3, 4, 5][num - 1]);
    } else if (S.tab === "quiz" && S.deck && S.deck.mcqs.length) {
      const m = S.deck.mcqs[S.quizIdx];
      if (m && num - 1 < m.options.length) answerQuiz(m, num - 1);
    }
  });
}

init();

