html.fs-compact { zoom: 0.92; }
html.fs-large { zoom: 1.12; }

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  color: var(--text);
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  line-height: 1.6;
  background: linear-gradient(135deg, var(--bg-top), var(--bg-mid), var(--bg-bottom));
  overflow-x: hidden;
  min-height: 100vh;
}

body::before {
  content: "";
  position: fixed;
  inset: -25%;
  z-index: -1;
  pointer-events: none;
  background:
    radial-gradient(32% 28% at 24% 16%, rgba(56, 189, 248, 0.09), transparent 65%),
    radial-gradient(28% 24% at 78% 24%, rgba(99, 102, 241, 0.08), transparent 65%),
    radial-gradient(24% 22% at 60% 85%, rgba(232, 121, 249, 0.05), transparent 65%);
  animation: aurora 26s ease-in-out infinite alternate;
}

@keyframes aurora {
  0%   { transform: translate3d(-2%, -1%, 0) scale(1); }
  50%  { transform: translate3d(2%, 1.5%, 0) scale(1.06); }
  100% { transform: translate3d(-1.5%, 2%, 0) scale(1.01); }
}

::selection { background: rgba(79, 70, 229, 0.18); }

/* ---------------------------------------------------------------- nav */

.nav {
  position: sticky; top: 0; z-index: 50;
  backdrop-filter: blur(14px);
  background: var(--glass);
  border-bottom: 1px solid var(--border-line);
}

.nav-inner {
  max-width: 1080px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 22px;
}

.brand { display: flex; align-items: center; gap: 10px; text-decoration: none; color: var(--text); }

.brand-mark {
  width: 36px; height: 36px;
  display: grid; place-items: center;
  border-radius: 10px;
  background: var(--grad);
  font-weight: 800; font-size: 13px; color: #fff;
  box-shadow: var(--glow);
}

.brand-text { display: flex; flex-direction: column; line-height: 1.2; }
.brand-text strong { font-size: 14px; }
.brand-text span { font-size: 11px; color: var(--muted); }

.nav-links { display: flex; align-items: center; gap: 22px; }
.nav-links a { color: var(--muted); text-decoration: none; font-size: 14px; font-weight: 600; transition: color .15s; }
.nav-links a:hover { color: var(--text); }
.nav-links a:not(.nav-cta) { display: inline-block; }
@media (max-width: 640px) {
  .nav-links a:not(.nav-cta) { display: none; }
}

/* ---------------------------------------------------------------- buttons */

.btn-primary, .btn-ghost {
  display: inline-block;
  text-decoration: none;
  font-weight: 700;
  border-radius: 12px;
  padding: 11px 22px;
  font-size: 14px;
  transition: transform .12s, box-shadow .2s, filter .15s, background .15s;
  cursor: pointer;
}

.btn-primary {
  background: var(--grad);
  color: #fff;
  box-shadow: 0 8px 22px rgba(79, 70, 229, 0.28);
}
.btn-primary:hover { filter: brightness(1.07); transform: translateY(-1px); box-shadow: 0 12px 28px rgba(79, 70, 229, 0.35); }
.btn-primary.big { padding: 15px 30px; font-size: 15px; border-radius: 14px; }

.btn-ghost {
  border: 1px solid var(--border-line);
  color: var(--text);
  background: var(--glass);
  backdrop-filter: blur(6px);
}
.btn-ghost:hover { background: var(--white); border-color: var(--border-line-2); transform: translateY(-1px); }
.btn-ghost.big { padding: 15px 30px; font-size: 15px; border-radius: 14px; }

.btn-primary:focus-visible, .btn-ghost:focus-visible, .cta-link:focus-visible,
.nav-links a:focus-visible, #themeToggle:focus-visible, .dl-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

/* ---------------------------------------------------------------- platform-aware */

.app-note { display: none; }
body[data-platform="android"] .app-note,
body[data-platform="desktop"] .app-note { display: block; }

body[data-platform="android"] .web-only,
body[data-platform="desktop"] .web-only { display: none !important; }

body[data-platform="android"] #get,
body[data-platform="desktop"] #get,
body[data-platform="android"] .cta-band,
body[data-platform="desktop"] .cta-band { display: none; }

body.web-mobile .android-card { order: -1; }
body.web-mobile .android-card.featured {
  box-shadow: 0 0 0 2px var(--indigo), 0 18px 40px rgba(12, 74, 110, 0.12);
}

/* ---------------------------------------------------------------- hero */

.hero {
  max-width: 1080px; margin: 0 auto;
  padding: 76px 22px 40px;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 40px;
  align-items: center;
}

.hero-badge {
  display: inline-block;
  padding: 6px 14px;
  border-radius: 999px;
  font-size: 12px; font-weight: 700;
  color: #334155;                       /* slate-700 */
  background: var(--hover);                  /* slate-100 */
  border: 1px solid var(--border-line); /* slate-200 */
  margin-bottom: 20px;
}

.hero h1 {
  font-size: clamp(34px, 5vw, 56px);
  line-height: 1.08;
  margin: 0 0 18px;
  letter-spacing: -0.5px;
  color: var(--text);
}

.grad-text {
  background: linear-gradient(90deg, var(--accent), var(--indigo));
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: grad-slide 6s ease-in-out infinite alternate;
}

@keyframes grad-slide {
  from { background-position: 0% 50%; }
  to   { background-position: 100% 50%; }
}

