/* ---------------------------------------------------------------- tokens */

:root {
  --bg: #fafbfc;
  --bg-alt: #f1f3f5;
  --surface: #ffffff;
  --surface-elevated: #ffffff;
  --accent: #2563eb;
  --accent-soft: #dbeafe;
  --text: #111827;
  --text-secondary: #4b5563;
  --text-muted: #9ca3af;
  --border: #e5e7eb;
  --border-strong: #d1d5db;
  --green: #059669;
  --green-soft: #d1fae5;
  --rose: #e11d48;
  --amber: #d97706;
  --grad: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow: 0 4px 12px rgba(0,0,0,0.06);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.08);
  --radius: 12px;
  --radius-lg: 18px;
  --font: "DM Sans", system-ui, -apple-system, sans-serif;
  --font-mono: "JetBrains Mono", "Cascadia Mono", monospace;
}

:root[data-theme="dark"] {
  --bg: #0a0a0f;
  --bg-alt: #111118;
  --surface: #16161f;
  --surface-elevated: #1c1c27;
  --accent: #60a5fa;
  --accent-soft: rgba(37,99,235,0.15);
  --text: #e5e7eb;
  --text-secondary: #9ca3af;
  --text-muted: #6b7280;
  --border: #26262e;
  --border-strong: #33333d;
  --green-soft: rgba(5,150,105,0.15);
  --grad: linear-gradient(135deg, #60a5fa 0%, #a78bfa 100%);
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.2);
  --shadow: 0 4px 12px rgba(0,0,0,0.3);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.4);
}

html.fs-compact { zoom: 0.92; }
html.fs-large { zoom: 1.12; }

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }

body {
  margin: 0;
  color: var(--text);
  font-family: var(--font);
  line-height: 1.6;
  background: var(--bg);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

::selection { background: rgba(37,99,235,0.15); }

/* ---------------------------------------------------------------- nav */

.nav {
  position: sticky; top: 0; z-index: 50;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  max-width: 1120px; margin: 0 auto;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 24px; height: 64px;
}

.brand {
  display: flex; align-items: center; gap: 10px;
  text-decoration: none; color: var(--text);
}

.brand-mark {
  width: 36px; height: 36px;
  display: grid; place-items: center;
  border-radius: 10px;
  background: var(--grad);
  color: #fff;
  box-shadow: 0 2px 8px rgba(37,99,235,0.3);
}

.brand-name { font-size: 15px; font-weight: 700; letter-spacing: -0.3px; }

.nav-right { display: flex; align-items: center; gap: 8px; }

.nav-link {
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 14px; font-weight: 500;
  padding: 6px 12px; border-radius: 8px;
  transition: color .15s, background .15s;
}
.nav-link:hover { color: var(--text); background: var(--bg-alt); }

.icon-btn {
  background: transparent; border: none; color: var(--text-secondary);
  width: 36px; height: 36px; border-radius: 8px; cursor: pointer;
  display: grid; place-items: center;
  transition: background .15s, color .15s;
}
.icon-btn:hover { background: var(--bg-alt); color: var(--text); }

/* theme icons */
:root[data-theme="dark"] .icon-sun { display: block; }
:root[data-theme="dark"] .icon-moon { display: none; }
:root:not([data-theme="dark"]) .icon-sun { display: none; }
:root:not([data-theme="dark"]) .icon-moon { display: block; }

/* ---------------------------------------------------------------- buttons */

.btn-primary, .btn-ghost {
  display: inline-flex; align-items: center;
  text-decoration: none;
  font-weight: 600;
  border-radius: var(--radius);
  padding: 10px 20px;
  font-size: 14px;
  transition: transform .1s, box-shadow .2s, background .15s;
  cursor: pointer;
  border: none;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
  box-shadow: 0 2px 8px rgba(37,99,235,0.25);
}
.btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(37,99,235,0.35);
}

.btn-ghost {
  background: var(--surface);
  color: var(--text);
  border: 1px solid var(--border);
}
.btn-ghost:hover {
  background: var(--bg-alt);
  border-color: var(--border-strong);
  transform: translateY(-1px);
}

.btn-lg { padding: 14px 28px; font-size: 15px; border-radius: 14px; }

.nav-cta { margin-left: 8px; }

.btn-primary:focus-visible, .btn-ghost:focus-visible, .icon-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* ---------------------------------------------------------------- hero */

.hero {
  max-width: 1120px; margin: 0 auto;
  padding: 80px 24px 60px;
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 48px;
  align-items: center;
}

.hero-badge {
  display: inline-block;
  padding: 5px 14px;
  border-radius: 999px;
  font-size: 12px; font-weight: 600;
  color: var(--accent);
  background: var(--accent-soft);
  margin-bottom: 20px;
}

.hero-title {
  font-size: clamp(36px, 5vw, 52px);
  line-height: 1.08;
  margin: 0 0 16px;
  letter-spacing: -0.6px;
  font-weight: 700;
  color: var(--text);
}

.grad-text {
  background: var(--grad);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.hero-sub {
  color: var(--text-secondary);
  font-size: 17px;
  max-width: 540px;
  margin: 0 0 28px;
  line-height: 1.65;
}

.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; align-items: center; }

.hero-proof {
  display: flex; gap: 20px; flex-wrap: wrap;
  margin-top: 24px;
}

.proof-item {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 13px; color: var(--text-muted); font-weight: 500;
}
.proof-item svg { color: var(--green); flex-shrink: 0; }

/* hero visual - stacked cards */

.hero-visual {
  position: relative;
  height: 340px;
  perspective: 1200px;
}

.visual-stack {
  position: relative;
  width: 100%;
  height: 100%;
}

.vcard {
  position: absolute;
  width: 260px;
  border-radius: var(--radius-lg);
  background: var(--surface);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-lg);
  padding: 20px;
  display: flex; flex-direction: column;
}

.vcard-1 { top: 20px; left: 0; transform: rotate(-6deg); z-index: 1; }
.vcard-2 { top: 0; left: 90px; transform: rotate(1deg); z-index: 3; }
.vcard-3 { top: 50px; left: 190px; transform: rotate(6deg); z-index: 2; }

.vcard-chip {
  display: inline-block;
  font-size: 10px; font-weight: 700; letter-spacing: 0.6px;
  color: #4338ca;
  background: #e0e7ff;
  padding: 2px 8px; border-radius: 999px;
  text-transform: uppercase;
  width: fit-content;
}
.vcard-chip.cloze { color: #0369a1; background: #e0f2fe; }
.vcard-chip.answer { color: #047857; background: var(--green-soft); }

.vcard-text {
  font-size: 14px; font-weight: 500;
  margin: 12px 0 0; line-height: 1.45;
  color: var(--text);
}

.vcard mark {
  background: #fef08a;
  color: #451a03;
  border-radius: 3px;
  padding: 0 3px;
  font-weight: 600;
}

.vcard-foot {
  margin-top: auto; padding-top: 12px;
  border-top: 1px solid var(--border);
  font-size: 11px; color: var(--text-muted);
}

@media (max-width: 900px) {
  .hero { grid-template-columns: 1fr; padding-top: 48px; }
  .hero-visual { height: 280px; }
  .vcard-2 { left: 50%; transform: translateX(-50%) rotate(1deg); }
  .vcard-1 { left: 5%; }
  .vcard-3 { right: 5%; left: auto; }
}

@media (max-width: 640px) {
  .hero { padding-top: 32px; }
  .hero-visual { height: 220px; }
  .vcard-3 { display: none; }
  .hero-actions { flex-direction: column; align-items: stretch; }
  .hero-actions .btn-primary, .hero-actions .btn-ghost { text-align: center; justify-content: center; }
}

/* ---------------------------------------------------------------- sections */

.section { padding: 72px 24px; }
.section-alt { background: var(--bg-alt); border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }

.section-inner { max-width: 1120px; margin: 0 auto; }

.section-header {
  text-align: center;
  margin-bottom: 48px;
}

.section-header h2 {
  font-size: clamp(26px, 3.5vw, 36px);
  letter-spacing: -0.4px;
  margin: 0 0 8px;
  font-weight: 700;
  color: var(--text);
}

.section-header p {
  color: var(--text-secondary);
  margin: 0;
  font-size: 16px;
  max-width: 500px;
  margin-left: auto; margin-right: auto;
}

/* ---------------------------------------------------------------- features */

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.feature-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: transform .15s, box-shadow .2s, border-color .15s;
}
.feature-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
  border-color: var(--border-strong);
}

.f-icon {
  width: 44px; height: 44px;
  display: grid; place-items: center;
  border-radius: 11px;
  background: var(--accent-soft);
  color: var(--accent);
  margin-bottom: 16px;
}

.feature-card h3 { margin: 0 0 6px; font-size: 15px; font-weight: 600; }
.feature-card p { margin: 0; color: var(--text-secondary); font-size: 14px; line-height: 1.55; }

@media (max-width: 800px) { .feature-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 540px) { .feature-grid { grid-template-columns: 1fr; } }

/* ---------------------------------------------------------------- steps */

.steps {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
}

.step {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px 24px;
  text-align: center;
  flex: 1;
  max-width: 300px;
}

.step-connector {
  color: var(--text-muted);
  flex-shrink: 0;
  padding: 0 8px;
}

.step-num {
  width: 44px; height: 44px;
  margin: 0 auto 14px;
  display: grid; place-items: center;
  border-radius: 50%;
  background: var(--grad);
  color: #fff;
  font-weight: 700; font-size: 17px;
  font-family: var(--font-mono);
  box-shadow: 0 2px 8px rgba(37,99,235,0.25);
}

.step h3 { margin: 0 0 6px; font-size: 15px; font-weight: 600; }
.step p { margin: 0; color: var(--text-secondary); font-size: 14px; }

@media (max-width: 740px) {
  .steps { flex-direction: column; gap: 12px; }
  .step { max-width: 100%; }
  .step-connector { transform: rotate(90deg); padding: 0; }
}

/* ---------------------------------------------------------------- get cards */

.get-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.get-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  display: flex; flex-direction: column;
  transition: transform .15s, box-shadow .2s;
}
.get-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-lg);
}

.get-card-featured {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent), var(--shadow);
}

.get-icon {
  width: 44px; height: 44px;
  display: grid; place-items: center;
  border-radius: 11px;
  background: var(--accent-soft);
  color: var(--accent);
  margin-bottom: 16px;
}

.get-card h3 { margin: 0 0 6px; font-size: 15px; font-weight: 600; }
.get-card p { margin: 0 0 16px; color: var(--text-secondary); font-size: 14px; }

.dl-btn { text-align: center; justify-content: center; }

.get-note { font-size: 12px; margin-top: auto; padding-top: 12px; color: var(--text-muted); }

.install-steps {
  margin: 0 0 12px;
  padding-left: 16px;
  font-size: 13px;
  color: var(--text-secondary);
}
.install-steps li { margin-bottom: 3px; }
.install-steps code {
  background: var(--accent-soft);
  color: var(--accent);
  border-radius: 4px;
  padding: 1px 5px;
  font-family: var(--font-mono);
  font-size: 12px;
}

@media (max-width: 800px) { .get-grid { grid-template-columns: 1fr; max-width: 400px; margin: 0 auto; } }

/* ---------------------------------------------------------------- cta band */

.cta-band {
  padding: 72px 24px;
}

.cta-inner {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 24px;
  padding: 56px 32px;
  box-shadow: var(--shadow-lg);
}

.cta-inner h2 {
  font-size: clamp(24px, 3vw, 32px);
  margin: 0 0 8px;
  letter-spacing: -0.3px;
}
.cta-inner p {
  color: var(--text-secondary);
  margin: 0 0 24px;
  font-size: 16px;
}

/* ---------------------------------------------------------------- footer */

footer {
  text-align: center;
  color: var(--text-muted);
  font-size: 13px;
  padding: 24px 20px 36px;
  border-top: 1px solid var(--border);
}

/* ---------------------------------------------------------------- reveal animation */

.reveal {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity .6s ease, transform .6s ease;
}
.reveal.visible {
  opacity: 1;
  transform: none;
}

/* ---------------------------------------------------------------- platform */

.app-note { display: none; }
body[data-platform="android"] .app-note,
body[data-platform="desktop"] .app-note { display: block; }
body[data-platform="android"] .web-only,
body[data-platform="desktop"] .web-only { display: none !important; }
body[data-platform="android"] #get,
body[data-platform="desktop"] #get,
body[data-platform="android"] .cta-band,
body[data-platform="desktop"] .cta-band { display: none; }

body.web-mobile .get-card-featured { order: -1; }

/* ---------------------------------------------------------------- toast */

.toast-lite {
  position: fixed; bottom: 20px; right: 20px; z-index: 200;
  background: var(--surface);
  border: 1px solid var(--border);
  border-left: 3px solid var(--accent);
  box-shadow: var(--shadow-lg);
  padding: 11px 15px;
  border-radius: var(--radius);
  font-size: 13px; font-weight: 500;
  color: var(--text);
  animation: tl-in .2s ease;
}
.toast-lite.ok { border-left-color: var(--green); }
.toast-lite.err { border-left-color: var(--rose); }
.toast-lite.out { animation: tl-out .25s ease forwards; }
@keyframes tl-in { from { transform: translateY(8px); opacity: 0; } }
@keyframes tl-out { to { transform: translateY(6px); opacity: 0; } }

"use strict";

/* ---------------------------------------------------------------- platform */

function detectPlatform() {
  const p = new URLSearchParams(location.search).get("platform");
  if (p === "android" || p === "desktop") return p;
  return /FlashcardQuiz/i.test(navigator.userAgent) ? "android" : "web";
}

const PLATFORM = detectPlatform();
const IS_MOBILE =
  (window.matchMedia && window.matchMedia("(pointer: coarse)").matches) ||
  window.innerWidth <= 760;

document.body.dataset.platform = PLATFORM;
if (PLATFORM === "web" && IS_MOBILE) document.body.classList.add("web-mobile");

(function platformUi() {
  if (PLATFORM !== "web") {
    document.querySelectorAll("#downloadBtn, #ctaDownloadBtn, .dl-btn").forEach((a) => {
      if (a.href && a.href.includes("/api/download/")) a.href = "/app";
    });
    document.querySelectorAll(".nav .brand").forEach((a) => { a.href = "/app"; });
    return;
  }
  if (IS_MOBILE) {
    const swap = (btn) => {
      if (!btn) return;
      btn.href = "/api/download/android";
    };
    swap(document.getElementById("downloadBtn"));
    const card = document.getElementById("getAndroidCard");
    if (card) card.classList.add("get-card-featured");
  }
})();

/* theme toggle */
function fqPrefs() {
  try { return JSON.parse(localStorage.getItem("fq_prefs") || "{}") || {}; } catch (_) { return {}; }
}

function applyTheme(theme) {
  document.documentElement.dataset.theme = theme;
}

(function initTheme() {
  const p = fqPrefs();
  const dark = p.theme === "dark" || (p.theme !== "light" && window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches);
  applyTheme(dark ? "dark" : "light");

  const btn = document.getElementById("themeToggle");
  if (btn) btn.addEventListener("click", () => {
    const next = document.documentElement.dataset.theme === "dark" ? "light" : "dark";
    const prefs = fqPrefs();
    prefs.theme = next;
    try { localStorage.setItem("fq_prefs", JSON.stringify(prefs)); } catch (_) {}
    applyTheme(next);
  });
})();

/* scroll reveal */
const reveals = document.querySelectorAll(".reveal, .feature-card, .step, .get-card, .section-header");
if ("IntersectionObserver" in window) {
  const io = new IntersectionObserver(
    (entries) => {
      entries.forEach((e) => {
        if (e.isIntersecting) {
          e.target.classList.add("visible");
          io.unobserve(e.target);
        }
      });
    },
    { threshold: 0.1, rootMargin: "0px 0px -40px 0px" }
  );
  reveals.forEach((el) => {
    el.classList.add("reveal");
    io.observe(el);
  });
} else {
  reveals.forEach((el) => el.classList.add("visible"));
}

/* download toast */
function toastLite(msg, kind) {
  const box = document.createElement("div");
  box.className = "toast-lite " + (kind || "");
  box.textContent = msg;
  document.body.appendChild(box);
  setTimeout(() => {
    box.classList.add("out");
    setTimeout(() => box.remove(), 280);
  }, 3200);
}

document.querySelectorAll(".dl-btn").forEach((btn) => {
  if (!btn.href || !btn.href.includes("/api/download/")) return;
  btn.addEventListener("click", () => {
    toastLite("Download started — check your downloads.", "ok");
  });
});

/* ---------------------------------------------------------------- tokens */

:root {
  --bg: #fafbfc;
  --bg-alt: #f1f3f5;
  --surface: #ffffff;
  --surface-elevated: #ffffff;
  --accent: #2563eb;
  --accent-soft: #dbeafe;
  --accent-hover: #1d4ed8;
  --text: #111827;
  --text-secondary: #4b5563;
  --text-muted: #9ca3af;
  --border: #e5e7eb;
  --border-strong: #d1d5db;
  --green: #059669;
  --green-soft: #d1fae5;
  --rose: #e11d48;
  --rose-soft: #ffe4e6;
  --amber: #d97706;
  --amber-soft: #fef3c7;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow: 0 2px 8px rgba(0,0,0,0.06);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.08);
  --radius: 10px;
  --radius-lg: 14px;
  --font: "DM Sans", system-ui, -apple-system, sans-serif;
  --font-mono: "JetBrains Mono", "Cascadia Mono", monospace;
  --sidebar-w: 240px;
}

:root[data-theme="dark"] {
  --bg: #0a0a0f;
  --bg-alt: #111118;
  --surface: #16161f;
  --surface-elevated: #1c1c27;
  --accent: #60a5fa;
  --accent-soft: rgba(37,99,235,0.15);
  --accent-hover: #93bbfd;
  --text: #e5e7eb;
  --text-secondary: #9ca3af;
  --text-muted: #6b7280;
  --border: #26262e;
  --border-strong: #33333d;
  --green-soft: rgba(5,150,105,0.15);
  --rose-soft: rgba(225,29,72,0.15);
  --amber-soft: rgba(217,119,6,0.15);
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.2);
  --shadow: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.4);
}

html.fs-compact { zoom: 0.92; }
html.fs-large { zoom: 1.12; }
*, *::before, *::after { box-sizing: border-box; }
html, body { height: 100%; }

body {
  margin: 0;
  color: var(--text);
  font-family: var(--font);
  line-height: 1.55;
  background: var(--bg);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

::selection { background: rgba(37,99,235,0.15); }

::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--border-strong); border-radius: 999px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

.app { display: flex; min-height: 100vh; }

/* ---------------------------------------------------------------- sidebar */

.sidebar {
  width: var(--sidebar-w);
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border-right: 1px solid var(--border);
  padding: 16px 12px;
  position: sticky;
  top: 0;
  height: 100vh;
}

.brand { display: flex; align-items: center; gap: 9px; margin-bottom: 16px; }

.brand-mark {
  width: 34px; height: 34px;
  display: grid; place-items: center;
  border-radius: 9px;
  background: linear-gradient(135deg, var(--accent), #7c3aed);
  color: #fff;
  box-shadow: 0 2px 6px rgba(37,99,235,0.3);
}

.brand-name { font-size: 14px; font-weight: 700; letter-spacing: -0.3px; }

.new-deck {
  width: 100%;
  padding: 9px 12px;
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius);
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  font-family: var(--font);
  display: flex; align-items: center; justify-content: center; gap: 6px;
  transition: background .12s, border-color .12s;
}
.new-deck:hover { background: var(--accent-soft); border-color: var(--accent); }

.deck-header {
  margin: 14px 4px 6px;
  font-size: 11px; font-weight: 600; letter-spacing: 0.8px;
  color: var(--text-muted); text-transform: uppercase;
}

.deck-list { list-style: none; margin: 0; padding: 0; overflow-y: auto; flex: 1; }

.deck-item {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 10px; margin-bottom: 3px;
  border-radius: var(--radius); cursor: pointer;
  border: 1px solid transparent;
  transition: background .1s, border-color .1s;
}
.deck-item:hover { background: var(--bg-alt); }
.deck-item.active {
  background: var(--accent-soft);
  border-color: var(--accent);
}
.deck-item .name { flex: 1; font-size: 13px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.deck-item .meta { font-size: 11px; color: var(--text-muted); white-space: nowrap; }
.deck-item .meta .due-num { color: var(--amber); font-weight: 700; }

.sidebar-footer { margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--border); }
.model-info { font-size: 11px; color: var(--text-muted); overflow-wrap: anywhere; }
.model-info b { color: var(--text); }
.model-info .mock-tag {
  display: inline-block; margin-top: 4px; padding: 1px 6px;
  background: var(--amber-soft); color: var(--amber);
  border-radius: 999px; font-size: 10px; font-weight: 700;
}

/* ---------------------------------------------------------------- main */

.main { flex: 1; min-width: 0; display: flex; flex-direction: column; }

.topbar {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 0 20px; height: 52px;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
  position: sticky; top: 0; z-index: 10;
}

.tabs { display: flex; gap: 2px; }
.tabs button {
  background: transparent; border: none; color: var(--text-muted);
  padding: 6px 12px; font-size: 13px; font-weight: 600; cursor: pointer;
  border-radius: 8px; font-family: var(--font);
  transition: background .1s, color .1s;
}
.tabs button:hover { background: var(--bg-alt); color: var(--text); }
.tabs button.active {
  background: var(--accent-soft);
  color: var(--accent);
}

.badge {
  font-size: 10px; background: var(--accent-soft); color: var(--accent);
  border-radius: 999px; padding: 1px 6px; font-weight: 700; margin-left: 2px;
}
.badge-warn { background: var(--amber-soft); color: var(--amber); }

.topbar-right { display: flex; align-items: center; gap: 8px; }
.deck-title { font-size: 14px; font-weight: 700; }

.content { padding: 20px 20px 80px; max-width: 1060px; width: 100%; }

.tab { display: grid; gap: 16px; }
.tab.hidden { display: none; }

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
}
.panel h2 { margin: 0 0 4px; font-size: 16px; font-weight: 600; }
.panel-muted { background: var(--bg-alt); }

.sub { color: var(--text-secondary); font-size: 13px; margin: 0 0 12px; }
.muted { font-size: 12px; color: var(--text-muted); }
.sm { font-size: 11px; }
.spacer { flex: 1; }

/* ---------------------------------------------------------------- buttons */

.btn-primary, .btn-ghost {
  display: inline-flex; align-items: center; justify-content: center;
  font-weight: 600; border-radius: var(--radius); padding: 9px 16px;
  font-size: 13px; font-family: var(--font); cursor: pointer; border: none;
  transition: transform .08s, box-shadow .15s, background .12s;
}
.btn-primary {
  background: var(--accent); color: #fff;
  box-shadow: 0 2px 6px rgba(37,99,235,0.25);
}
.btn-primary:hover { background: var(--accent-hover); box-shadow: 0 4px 12px rgba(37,99,235,0.3); }
.btn-primary:active { transform: translateY(1px); }
.btn-primary:disabled { opacity: .45; cursor: not-allowed; }

.btn-ghost {
  background: var(--surface); color: var(--text);
  border: 1px solid var(--border);
}
.btn-ghost:hover { background: var(--bg-alt); border-color: var(--border-strong); }
.btn-ghost:active { transform: translateY(1px); }

.btn-sm { padding: 6px 12px; font-size: 12px; }
.btn-danger:hover { border-color: var(--rose); color: var(--rose); background: var(--rose-soft); }

.icon-btn {
  background: transparent; border: none; color: var(--text-muted);
  width: 34px; height: 34px; border-radius: var(--radius); cursor: pointer;
  display: grid; place-items: center; font-family: var(--font);
  transition: background .12s, color .12s;
}
.icon-btn:hover { color: var(--text); background: var(--bg-alt); }

/* ---------------------------------------------------------------- form elements */

textarea, .search-input {
  width: 100%;
  background: var(--surface);
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 10px 12px;
  font: 13px/1.6 var(--font-mono);
  resize: vertical;
  font-family: var(--font-mono);
}
textarea:focus, .search-input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(37,99,235,0.1);
}

input[type="number"] {
  background: var(--surface); color: var(--text);
  border: 1px solid var(--border); border-radius: 8px;
  padding: 6px 8px; width: 60px; font-family: var(--font);
}

label.chk {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 12px; color: var(--text-secondary);
  padding: 5px 10px; border-radius: 999px;
  background: var(--surface);
  border: 1px solid var(--border);
  cursor: pointer; user-select: none;
}
label.chk input { width: auto; accent-color: var(--accent); }
label.chk:hover { border-color: var(--accent); }

select {
  padding: 6px 8px; border-radius: 8px;
  border: 1px solid var(--border); background: var(--surface); color: var(--text);
  font: 12px/1.4 var(--font); max-width: 220px;
}
select:focus { outline: none; border-color: var(--accent); }

/* ---------------------------------------------------------------- drop zone */

.drop-zone {
  border: 2px dashed var(--border-strong);
  border-radius: var(--radius-lg);
  padding: 32px 20px;
  text-align: center;
  transition: border-color .15s, background .15s;
  cursor: pointer;
  margin-bottom: 12px;
}
.drop-zone.dragover {
  border-color: var(--accent);
  background: var(--accent-soft);
}
.drop-zone input { display: none; }
.drop-icon { color: var(--text-muted); margin-bottom: 8px; }
.drop-text { margin: 0 0 4px; font-size: 14px; color: var(--text-secondary); }
.drop-hint { margin: 0; font-size: 12px; color: var(--text-muted); }
.file-link { color: var(--accent); font-weight: 600; cursor: pointer; text-decoration: underline; }

.file-preview {
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 10px 14px;
  margin-bottom: 12px;
}
.file-info { display: flex; align-items: center; gap: 8px; font-size: 13px; }
.file-info svg { color: var(--accent); flex-shrink: 0; }
.file-size { color: var(--text-muted); font-size: 12px; }

/* ---------------------------------------------------------------- gen options */

.gen-row { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; margin: 10px 0; }
.gen-options {
  display: flex; gap: 10px; align-items: flex-end; flex-wrap: wrap;
  margin: 10px 0 4px;
}
.opt-label {
  display: flex; flex-direction: column; gap: 3px;
  font-size: 12px; color: var(--text-muted); font-weight: 500;
}

/* ---------------------------------------------------------------- progress */

.progress { margin-top: 4px; }
.progress.hidden, .hidden { display: none; }
.progress-bar {
  height: 6px; border-radius: 999px;
  background: var(--border); overflow: hidden;
}
.progress-fill {
  height: 100%; width: 0%;
  background: linear-gradient(90deg, var(--accent), #7c3aed);
  border-radius: 999px;
  transition: width .4s ease;
}
.progress-fill.indeterminate { width: 30%; animation: slide 1.2s ease-in-out infinite; }
@keyframes slide { 0% { margin-left: -30%; } 100% { margin-left: 100%; } }
.status { font-size: 12px; color: var(--text-muted); margin-top: 6px; }
.status.err { color: var(--rose); }
.status.ok { color: var(--green); }

/* ---------------------------------------------------------------- card grid */

.toolbar { display: flex; align-items: center; gap: 10px; margin-bottom: 14px; flex-wrap: wrap; }
.toolbar h2 { margin: 0; }
.search-input { max-width: 260px; width: auto; }

.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 12px;
}

.flip-card { perspective: 1000px; }
.flip-card .flip-inner {
  position: relative; width: 100%; height: 140px;
  transform-style: preserve-3d;
  transition: transform .4s cubic-bezier(.4, .2, .2, 1);
  cursor: pointer;
}
.flip-card.flipped .flip-inner { transform: rotateY(180deg); }
.flip-card.big .flip-inner { height: 240px; }

.face {
  position: absolute; inset: 0;
  backface-visibility: hidden; -webkit-backface-visibility: hidden;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  background: var(--surface);
  box-shadow: var(--shadow-sm);
  padding: 14px;
  display: flex; flex-direction: column;
  overflow: hidden;
}
.flip-card:not(.flipped) .face.front { transition: box-shadow .2s, transform .2s; }
.flip-card:not(.flipped):hover .face.front {
  box-shadow: var(--shadow);
  transform: translateY(-2px);
}

.face .face-text {
  flex: 1; font-size: 13px; overflow-y: auto;
  display: flex; align-items: center;
  color: var(--text);
}
.face.back .face-text { align-items: flex-start; }
.face .face-meta {
  margin-top: 8px; padding-top: 8px;
  border-top: 1px solid var(--border);
  display: flex; gap: 5px; align-items: center; flex-wrap: wrap;
  font-size: 11px; color: var(--text-muted);
}
.face.back {
  transform: rotateY(180deg);
  border-color: var(--green);
  background: linear-gradient(160deg, #ecfdf5, #f0fdfa);
}
:root[data-theme="dark"] .face.back {
  background: linear-gradient(160deg, rgba(5,150,105,0.08), rgba(20,184,166,0.05));
}

.chip {
  background: var(--accent-soft); color: var(--accent);
  border-radius: 999px; padding: 1px 7px; font-size: 10px; font-weight: 700;
}
.chip.tags { background: var(--bg-alt); color: var(--text-muted); font-weight: 600; }

mark, .cloze-hl {
  background: #fef08a; color: #451a03;
  border-radius: 3px; padding: 0 3px; font-weight: 600;
}
:root[data-theme="dark"] mark { background: rgba(254,240,138,0.2); color: #fde68a; }

.card-actions { display: flex; gap: 5px; margin-top: 6px; }
.card-actions button { padding: 4px 8px; font-size: 11px; background: var(--bg-alt); border: 1px solid var(--border); border-radius: 6px; cursor: pointer; font-family: var(--font); }

.card-editor { width: 100%; }
.card-editor textarea { min-height: 48px; margin-bottom: 6px; font-size: 12px; }
.card-editor .controls { display: flex; gap: 6px; justify-content: flex-end; }
.card-editor .controls button { padding: 5px 10px; font-size: 11px; }
.card-editor .save { background: var(--green); border-color: var(--green); color: #fff; border-radius: 6px; }

.empty { text-align: center; padding: 40px 20px; color: var(--text-muted); }
.empty-icon {
  width: 52px; height: 52px; margin: 0 auto 12px;
  display: grid; place-items: center;
  border-radius: 14px;
  background: var(--accent-soft);
