/* ---------------------------------------------------------------- review */

.review-stage { max-width: 600px; margin: 0 auto; }
.review-flip { margin-bottom: 14px; }
.review-actions { display: flex; gap: 8px; justify-content: center; flex-wrap: wrap; }
.review-actions button { min-width: 80px; }
.review-actions .q1 { border: 1px solid #fda4af; color: #be123c; background: var(--rose-soft); }
.review-actions .q3 { border: 1px solid #fcd34d; color: #b45309; background: var(--amber-soft); }
.review-actions .q4 { border: 1px solid #6ee7b7; color: #047857; background: var(--green-soft); }
.review-actions .q5 { background: linear-gradient(135deg, #10b981, #06b6d4); border-color: transparent; color: #fff; box-shadow: 0 4px 12px rgba(16,185,129,0.3); }
.review-progress { text-align: center; color: var(--text-muted); font-size: 12px; margin-top: 10px; }
.review-result { text-align: center; font-size: 13px; margin-top: 8px; }
.review-result.ok { color: var(--green); }
.review-result .interval-line { color: var(--text-muted); font-size: 12px; }

/* ---------------------------------------------------------------- quiz */

.quiz-box { max-width: 680px; margin: 0 auto; }
.quiz-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; color: var(--text-muted); font-size: 13px; }
.quiz-q { font-size: 15px; font-weight: 600; margin-bottom: 12px; }
.quiz-opts { display: grid; gap: 8px; margin-bottom: 10px; }
.quiz-opt {
  display: flex; align-items: center; gap: 10px; text-align: left;
  background: var(--surface); padding: 10px 14px;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  cursor: pointer;
  font-family: var(--font); font-size: 13px;
  transition: border-color .1s, background .1s;
}
.quiz-opt:hover:not(.locked):not(.correct):not(.wrong) { border-color: var(--accent); background: var(--accent-soft); }
.quiz-opt .key { color: var(--text-muted); font-weight: 700; font-size: 12px; min-width: 16px; font-family: var(--font-mono); }
.quiz-opt.correct { border-color: var(--green); background: var(--green-soft); }
.quiz-opt.wrong { border-color: var(--rose); background: var(--rose-soft); }
