.quiz-list { margin-top: 20px; border-top: 1px solid var(--border); padding-top: 12px; }
.quiz-list-title { font-size: 11px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.8px; margin-bottom: 6px; font-weight: 600; }
.quiz-entry {
