body[data-platform="android"] .new-deck, body[data-platform="android"] .drop-zone { padding: 14px 16px; }
body[data-platform="android"] .quiz-opt { padding: 12px 14px; }
body[data-platform="android"] .review-actions button { min-height: 44px; flex: 1; min-width: 0; }
body[data-platform="android"] .review-actions { gap: 6px; }

body[data-platform="desktop"] .content { max-width: 1240px; }

.platform-chip {
  font-size: 11px; font-weight: 700; color: var(--accent);
  border: 1px solid var(--accent-soft);
  background: var(--accent-soft);
  padding: 3px 10px; border-radius: 999px;
}

button:focus-visible, .file-link:focus-visible, .deck-item:focus-visible,
.quiz-opt:focus-visible, select:focus-visible {
  outline: 2px solid var(--accent);
