            "2": "Incorrect. The Golgi apparatus modifies and packages proteins.",
            "3": "Incorrect. The nucleus stores genetic material.",
        },
        "tags": ["mock", "Biology"],
    },
]


def _client() -> OpenAI:
    s = get_settings()
    return OpenAI(api_key=s.openai_api_key, base_url=s.openai_base_url)


def _extract_json(text: str, model: type[T]) -> list[T]:
    """Parse a JSON array (or single object / wrapped object) into typed models."""
    text = text.strip()
    if text.startswith("```"):
        text = text.strip("`")
        if text.startswith("json"):
            text = text[4:]
    if not text.startswith("["):
        obj = json.loads(text)
        if isinstance(obj, dict):
            for key in ("flashcards", "mcqs", "cards", "data", "items"):
                if key in obj:
                    text = json.dumps(obj[key])
                    break
            else:
                # single card/question object (e.g. {"type": "Basic", ...})
                text = f"[{text}]"
    data = json.loads(text)
    if not isinstance(data, list):
        raise ValueError("Expected a JSON array from the model")
    items: list[T] = []
    for item in data:
        try:
            items.append(model.model_validate(item))
        except Exception:
            continue  # skip malformed items instead of failing the whole batch
    return items


def _cache_key(system: str, user: str) -> str:
    s = get_settings()
    raw = f"{PROMPT_VERSION}|{s.llm_model}|{s.llm_temperature}|{system}\n{user}"
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def _chat(system: str, user: str) -> str:
    """Raw chat call with JSON-mode enabled; retries without it if the
    provider/model rejects response_format (some OpenRouter/NVIDIA models)."""
    s = get_settings()
    kwargs = dict(
        model=s.llm_model,
        temperature=s.llm_temperature,
        messages=[
            {"role": "system", "content": system},
            {"role": "user", "content": user},
        ],
    )
    client = _client()
    try:
        resp = client.chat.completions.create(**kwargs, response_format={"type": "json_object"})
    except OpenAIError as exc:
        _raise_rate_limit(exc)
        try:
            resp = client.chat.completions.create(**kwargs)
        except OpenAIError as exc2:
            _raise_rate_limit(exc2)
            raise
    content = resp.choices[0].message.content or ""
    if not content.strip():
        raise RuntimeError("Empty LLM response (reasoning-only output?)")
    return content


def _raise_rate_limit(exc: Exception) -> None:
    """If `exc` is a 429, raise RateLimitError with the reset timestamp."""
    from openai import RateLimitError as OpenAILimit

    if not isinstance(exc, OpenAILimit):
        return
    reset_ms = None
    try:
        body = exc.body if isinstance(exc.body, dict) else {}
        meta = body.get("error", {}).get("metadata", {})
        reset_ms = int(meta.get("headers", {}).get("X-RateLimit-Reset", 0) or 0) or None
        if not reset_ms:
            reset_ms = int(exc.headers.get("x-ratelimit-reset", 0) or 0) or None
    except (AttributeError, TypeError, ValueError):
        reset_ms = None
    raise RateLimitError(reset_ms) from exc


def _chat_with_retry(system: str, user: str, on_pause: OnPause = None) -> str:
    """Cached LLM call; on 429, sleep until the quota resets and retry,
    keeping the caller's generator alive so progress resumes in place.
    Identical requests replay from the cache for free."""
    key = _cache_key(system, user)
    while True:
        cached = db.llm_cache_get(key)
        if cached is not None:
            return cached
        try:
            content = _chat(system, user)
            db.llm_cache_put(key, content)
            return content
        except RateLimitError as exc:
            if exc.reset_ts_ms:
                wait = exc.reset_ts_ms / 1000.0 - time.time() + RETRY_PAD_SECONDS
            else:
                wait = 3600.0
            wait = max(wait, 10.0)
            if wait > MAX_PAUSE_SECONDS:
                raise
            if on_pause:
                on_pause(exc.reset_ts_ms, wait)
            time.sleep(wait)
            if on_pause:
                on_pause(None, 0.0)  # back in business


def generate_flashcards_iter(
    source_text: str, num_cards: int, tags: list[str], on_pause: OnPause = None
) -> Iterator[list[Flashcard]]:
    """Yield batches of unique new flashcards until the target is reached.

    Whole-book sources are split into chunks and each chunk is mined with its
    own budget, so cards come from across the entire book, not just the first
    40k characters. Dedupe spans chunks."""
    if _mock_mode():
        yield _merge_tags([Flashcard.model_validate(c) for c in MOCK_FLASHCARDS], tags)[:num_cards]
        return
    cards: list[Flashcard] = []
    chunks = _split_chunks(source_text)
    for ci, chunk in enumerate(chunks):
        if len(cards) >= num_cards:
            break
        per_chunk = _ceil_div(num_cards - len(cards), len(chunks) - ci)
        for _ in range(6):
            if len(cards) >= num_cards:
                break
            user = (
                f"Source material (between START and END):\nSTART\n{chunk}\nEND\n\n"
                f"Generate flashcards following the schema."
                + _already_generated_cards(cards)
                + "Return a JSON array of distinct new cards."
            )
            batch = _extract_json(_chat_with_retry(FLASHCARD_SYSTEM, user, on_pause), Flashcard)
            known = {_card_key(x) for x in cards}
            added = [c for c in batch if _card_key(c) not in known][:per_chunk]
            if not added:
                break  # model produced nothing new; stop refilling this chunk
            cards += added
            yield _merge_tags(added, tags)


def generate_mcqs_iter(
    source_text: str, num_mcqs: int, tags: list[str], on_pause: OnPause = None
) -> Iterator[list[MCQ]]:
    """Yield batches of unique new MCQs until the target is reached (chunked
    like flashcards, so a whole book is covered)."""
    if _mock_mode():
        yield _merge_tags([MCQ.model_validate(m) for m in MOCK_MCQS], tags)[:num_mcqs]
        return
    mcqs: list[MCQ] = []
    chunks = _split_chunks(source_text)
    for ci, chunk in enumerate(chunks):
        if len(mcqs) >= num_mcqs:
            break
        per_chunk = _ceil_div(num_mcqs - len(mcqs), len(chunks) - ci)
        for _ in range(6):
            if len(mcqs) >= num_mcqs:
                break
            user = (
                f"Source material (between START and END):\nSTART\n{chunk}\nEND\n\n"
                f"Generate multiple-choice questions following the schema."
                + _already_generated_mcqs(mcqs)
                + "Return a JSON array of distinct new questions."
            )
            batch = _extract_json(_chat_with_retry(MCQ_SYSTEM, user, on_pause), MCQ)
            known = {_mcq_key(m) for m in mcqs}
            added = [m for m in batch if _mcq_key(m) not in known][:per_chunk]
            if not added:
                break
            mcqs += added
            yield _merge_tags(added, tags)


def _mock_mode() -> bool:
    s = get_settings()
    return s.mock_llm or not s.openai_api_key


def _card_key(c: Flashcard) -> str:
    return (c.text or c.front).strip().lower()


def _mcq_key(m: MCQ) -> str:
    return m.question.strip().lower()


def _split_chunks(text: str, size: int = 35000) -> list[str]:
    """Split source into roughly `size`-char chunks (whole-book support)."""
    text = text.strip()
    return [text[i : i + size] for i in range(0, len(text), size)] or [""]


def _ceil_div(a: int, b: int) -> int:
    return -(-a // b) if b else a


def _already_generated_cards(cards: list[Flashcard]) -> str:
    if not cards:
        return ""
    fronts = "; ".join((c.text or c.front)[:60] for c in cards[-15:])
    return f"\nAlready generated (do NOT repeat these): {fronts}."


def _already_generated_mcqs(mcqs: list[MCQ]) -> str:
    if not mcqs:
        return ""
    questions = "; ".join(m.question[:60] for m in mcqs[-15:])
    return f"\nAlready generated (do NOT repeat these): {questions}."


def _merge_tags(items: list, tags: list[str]) -> list:
    for item in items:
        for t in tags:
            if t not in item.tags:
                item.tags.append(t)
    return items

"""Multi-modal ingestion: PDF text extraction with cloud OCR (ocr.space)
as primary engine and RapidOCR as local fallback. Supports images too."""

from __future__ import annotations

import io
import threading

from pypdf import PdfReader

_ocr_lock = threading.Lock()
_ocr_engine = None

MAX_PAGES = 5000
OCR_MAX_PAGES = 300


def ocrspace_available() -> bool:
    from .config import get_settings
    return bool(get_settings().ocrspace_api_key)


def rapidocr_available() -> bool:
    try:
        import rapidocr_onnxruntime  # noqa: F401
        return True
    except ImportError:
        return False


def any_ocr_available() -> bool:
    return ocrspace_available() or rapidocr_available()


def _get_rapidocr():
    global _ocr_engine
    if _ocr_engine is None:
        from rapidocr_onnxruntime import RapidOCR
        _ocr_engine = RapidOCR()
    return _ocr_engine


# ---------------------------------------------------------------- ocr.space

def _ocrspace_image(pil_image) -> str:
    """OCR a PIL image via ocr.space cloud API."""
    import httpx
    from .config import get_settings

    buf = io.BytesIO()
    pil_image.convert("RGB").save(buf, format="PNG")
    b64 = __import__("base64").b64encode(buf.getvalue()).decode()

    resp = httpx.post(
        "https://api.ocr.space/parse/image",
        data={
            "apikey": get_settings().ocrspace_api_key,
            "base64Image": f"data:image/png;base64,{b64}",
            "language": "eng",
            "isOverlayRequired": "false",
            "OCREngine": "2",
        },
        timeout=30.0,
    )
    resp.raise_for_status()
    result = resp.json()

    if result.get("IsErroredOnProcessing"):
        msgs = result.get("ErrorMessage", ["OCR failed"])
        raise RuntimeError(f"ocr.space error: {msgs}")

    texts = []
    for p in result.get("ParsedResults", []):
        txt = p.get("ParsedText", "")
        if txt:
            texts.append(txt)
    return "\n".join(texts).strip()


def _ocrspace_pdf_page(data: bytes, page_idx: int) -> str:
    """OCR a single PDF page via ocr.space."""
    import httpx
    from .config import get_settings

    b64 = __import__("base64").b64encode(data).decode()

    resp = httpx.post(
        "https://api.ocr.space/parse/image",
        data={
            "apikey": get_settings().ocrspace_api_key,
            "base64Image": f"data:application/pdf;base64,{b64}",
            "language": "eng",
            "isOverlayRequired": "false",
            "OCREngine": "2",
            "pageIndex": str(page_idx),
        },
        timeout=60.0,
    )
    resp.raise_for_status()
    result = resp.json()

    if result.get("IsErroredOnProcessing"):
        msgs = result.get("ErrorMessage", ["OCR failed"])
        raise RuntimeError(f"ocr.space error: {msgs}")

    texts = []
    for p in result.get("ParsedResults", []):
        txt = p.get("ParsedText", "")
        if txt:
            texts.append(txt)
    return "\n".join(texts).strip()


# ---------------------------------------------------------------- rapidocr (local fallback)

def _rapidocr_image(pil_image) -> str:
    import numpy as np
    with _ocr_lock:
        result, _ = _get_rapidocr()(np.array(pil_image.convert("RGB")))
    if not result:
        return ""
    lines = [t.strip() for _, t, conf in result if conf >= 0.5 and t and t.strip()]
    return "\n".join(lines)


# ---------------------------------------------------------------- unified OCR entry points

def ocr_image(pil_image) -> str:
    """OCR a PIL image, trying ocr.space first then RapidOCR."""
    if ocrspace_available():
        try:
            text = _ocrspace_image(pil_image)
            if text:
                return text
        except Exception:
            pass  # fall through to local
    if rapidocr_available():
        return _rapidocr_image(pil_image)
    raise ValueError(
        "OCR is not available. Set OCRSPACE_API_KEY in .env or install rapidocr_onnxruntime."
    )


def ocr_pdf_page(data: bytes, page_idx: int) -> str:
    """OCR a single page of a PDF, trying ocr.space first then RapidOCR rendering."""
    if ocrspace_available():
        try:
            text = _ocrspace_pdf_page(data, page_idx)
            if text:
                return text
        except Exception:
            pass  # fall through to local
    if rapidocr_available():
        import pypdfium2 as pdfium
        pdf = pdfium.PdfDocument(data)
        try:
            pil = pdf[page_idx].render(scale=2.0).to_pil()
            return _rapidocr_image(pil)
        finally:
            pdf.close()
    raise ValueError(
        "OCR is not available. Set OCRSPACE_API_KEY in .env or install rapidocr_onnxruntime."
    )


# ---------------------------------------------------------------- PDF extraction

def extract_pdf_text(data: bytes, max_pages: int = MAX_PAGES, ocr: bool = True) -> str:
    """Extract text from a PDF (whole books included).

    Pages with no extractable text are treated as scans: when `ocr` is True
    they are OCR'd (ocr.space cloud first, RapidOCR local fallback).
    OCR work is capped at OCR_MAX_PAGES per call.
    """
    reader = PdfReader(io.BytesIO(data))
    chunks: list[str] = []
    scan_pages: list[int] = []

    for i, page in enumerate(reader.pages[:max_pages]):
        text = page.extract_text() or ""
        if text.strip():
            chunks.append(f"[Page {i + 1}]\n{text.strip()}")
        else:
            scan_pages.append(i)

    ocr_pages = scan_pages[:OCR_MAX_PAGES]
    ocr_did_run = False

    if ocr and ocr_pages and any_ocr_available():
        ocr_did_run = True
        for i, page_idx in enumerate(ocr_pages):
            try:
                text = ocr_pdf_page(data, page_idx)
            except Exception:
                continue
            if text:
                chunks.append(f"[Page {page_idx + 1} (OCR)]\n{text}")

        if len(scan_pages) > OCR_MAX_PAGES:
            chunks.append(f"[Note: {len(scan_pages) - OCR_MAX_PAGES} more scanned pages skipped (OCR cap).]")

    if not chunks:
        if ocr and not any_ocr_available():
            raise ValueError(
                "This PDF has no extractable text (scanned). "
                "Set OCRSPACE_API_KEY in .env or run: pip install rapidocr_onnxruntime pypdfium2"
            )
        if ocr and ocr_did_run:
            raise ValueError("OCR ran but found no readable text in this PDF.")
        raise ValueError(
            "No text found — this PDF looks scanned. Tick \"OCR scanned pages\" to read it."
        )

    return "\n\n".join(chunks)


# ---------------------------------------------------------------- image extraction

def extract_image_text(data: bytes) -> str:
    """OCR a photo/scan (PNG, JPEG, WEBP, BMP, TIFF) directly."""
    from PIL import Image

    if not any_ocr_available():
        raise ValueError(
            "Image OCR is not available. Set OCRSPACE_API_KEY in .env or install rapidocr_onnxruntime."
        )
    img = Image.open(io.BytesIO(data))
    return ocr_image(img)

"""SQLite persistence: decks, flashcards, MCQs, SM-2 scheduling, quiz stats."""

from __future__ import annotations

import json
import os
import sqlite3
import sys
import threading
from datetime import date, timedelta
from pathlib import Path

from . import sm2
from .schemas import Flashcard, FlashcardUpdate, MCQ, SM2Card


def _data_dir() -> Path:
    """SQLite lives next to the code in dev; in %LOCALAPPDATA% when frozen (.exe)."""
    if getattr(sys, "frozen", False):
        data = Path(os.environ.get("LOCALAPPDATA") or Path.home()) / "FlashcardQuiz"
        data.mkdir(parents=True, exist_ok=True)
        return data
    return Path(__file__).resolve().parent


DB_PATH = _data_dir() / "data.db"

SCHEMA = """
CREATE TABLE IF NOT EXISTS decks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS flashcards (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    deck_id INTEGER NOT NULL REFERENCES decks(id) ON DELETE CASCADE,
    type TEXT NOT NULL DEFAULT 'Basic',
    front TEXT NOT NULL DEFAULT '',
    back TEXT NOT NULL DEFAULT '',
    text TEXT NOT NULL DEFAULT '',
    tags TEXT NOT NULL DEFAULT '[]',
    source TEXT NOT NULL DEFAULT '',
    ease REAL NOT NULL DEFAULT 2.5,
    interval INTEGER NOT NULL DEFAULT 0,
    reps INTEGER NOT NULL DEFAULT 0,
    due TEXT NOT NULL DEFAULT '1970-01-01'
);
CREATE TABLE IF NOT EXISTS mcqs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    deck_id INTEGER NOT NULL REFERENCES decks(id) ON DELETE CASCADE,
    question TEXT NOT NULL,
    options TEXT NOT NULL DEFAULT '[]',
    correct_index INTEGER NOT NULL DEFAULT 0,
    explanation TEXT NOT NULL DEFAULT '',
    distractor_explanations TEXT NOT NULL DEFAULT '{}',
    tags TEXT NOT NULL DEFAULT '[]',
    answered INTEGER NOT NULL DEFAULT 0,
    correct INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_flashcards_deck ON flashcards(deck_id);
CREATE INDEX IF NOT EXISTS idx_mcqs_deck ON mcqs(deck_id);
CREATE TABLE IF NOT EXISTS llm_cache (
    cache_key TEXT PRIMARY KEY,
    response TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
"""

_conn: sqlite3.Connection | None = None
_lock = threading.Lock()


def _db() -> sqlite3.Connection:
    global _conn
    if _conn is None:
        _conn = sqlite3.connect(DB_PATH, check_same_thread=False)
        _conn.row_factory = sqlite3.Row
        _conn.execute("PRAGMA foreign_keys = ON")
    return _conn


def _query(sql: str, params: tuple = ()) -> list[sqlite3.Row]:
    """Run a SELECT while holding the connection lock."""
    with _lock:
        return _db().execute(sql, params).fetchall()


def _execute(sql: str, params: tuple = ()) -> sqlite3.Cursor:
    """Run a write and commit while holding the connection lock."""
    with _lock:
        cur = _db().execute(sql, params)
        _db().commit()
        return cur


def init_db() -> None:
    _db().executescript(SCHEMA)
    if not _query("SELECT id FROM decks"):
        _execute(
            "INSERT INTO decks (name, created_at) VALUES (?, ?)",
            ("Lecture 01", date.today().isoformat()),
        )


# ---------------------------------------------------------------- llm cache

def llm_cache_get(key: str) -> str | None:
    rows = _query("SELECT response FROM llm_cache WHERE cache_key=?", (key,))
    return rows[0]["response"] if rows else None


def llm_cache_put(key: str, response: str) -> None:
    _execute(
        "INSERT INTO llm_cache (cache_key, response) VALUES (?, ?) "
        "ON CONFLICT(cache_key) DO UPDATE SET response=excluded.response",
        (key, response),
    )


def llm_cache_clear() -> None:
    _execute("DELETE FROM llm_cache")


# ---------------------------------------------------------------- decks

def list_decks() -> list[dict]:
    today = date.today().isoformat()
    rows = _query(
        """
        SELECT d.id, d.name, d.created_at,
               (SELECT COUNT(*) FROM flashcards f WHERE f.deck_id = d.id) AS cards,
               (SELECT COUNT(*) FROM mcqs m WHERE m.deck_id = d.id) AS mcqs,
               (SELECT COUNT(*) FROM flashcards f WHERE f.deck_id = d.id AND f.due <= ?) AS due
        FROM decks d ORDER BY d.id
        """,
        (today,),
    )
    return [dict(r) for r in rows]


def create_deck(name: str) -> dict:
    cur = _execute(
        "INSERT INTO decks (name, created_at) VALUES (?, ?)",
        (name, date.today().isoformat()),
    )
    return {"id": cur.lastrowid, "name": name, "created_at": date.today().isoformat(), "cards": 0, "mcqs": 0, "due": 0}


def delete_deck(deck_id: int) -> None:
    _execute("DELETE FROM decks WHERE id=?", (deck_id,))


def deck_exists(deck_id: int) -> bool:
    return bool(_query("SELECT id FROM decks WHERE id=?", (deck_id,)))


# ---------------------------------------------------------------- flashcards

def _card_row_to_dict(r: sqlite3.Row) -> dict:
    return {
        "id": r["id"], "deck_id": r["deck_id"], "type": r["type"], "front": r["front"],
        "back": r["back"], "text": r["text"], "tags": json.loads(r["tags"]),
        "source": r["source"], "ease": r["ease"], "interval": r["interval"],
        "reps": r["reps"], "due": r["due"],
    }


def _mcq_row_to_dict(r: sqlite3.Row) -> dict:
    return {
        "id": r["id"], "deck_id": r["deck_id"], "question": r["question"],
        "options": json.loads(r["options"]), "correct_index": r["correct_index"],
        "explanation": r["explanation"],
        "distractor_explanations": json.loads(r["distractor_explanations"]),
        "tags": json.loads(r["tags"]), "answered": r["answered"], "correct": r["correct"],
    }


def get_deck(deck_id: int) -> dict:
    deck = _query("SELECT * FROM decks WHERE id=?", (deck_id,))
    if not deck:
        raise ValueError("Deck not found")
    cards = _query("SELECT * FROM flashcards WHERE deck_id=? ORDER BY id", (deck_id,))
    mcqs = _query("SELECT * FROM mcqs WHERE deck_id=? ORDER BY id", (deck_id,))
    r = deck[0]
    return {
        "id": r["id"], "name": r["name"], "created_at": r["created_at"],
        "cards": [_card_row_to_dict(c) for c in cards],
        "mcqs": [_mcq_row_to_dict(m) for m in mcqs],
    }


def add_flashcards(deck_id: int, cards: list[Flashcard]) -> None:
    if not deck_exists(deck_id):
        raise ValueError("Deck was deleted")
    with _lock:
        _db().executemany(
            "INSERT INTO flashcards (deck_id, type, front, back, text, tags, source) VALUES (?,?,?,?,?,?,?)",
            [(deck_id, c.type, c.front, c.back, c.text, json.dumps(c.tags), c.source) for c in cards],
        )
        _db().commit()


def get_card(deck_id: int, card_id: int) -> dict:
    rows = _query("SELECT * FROM flashcards WHERE id=? AND deck_id=?", (card_id, deck_id))
    if not rows:
        raise ValueError("Card not found")
    return _card_row_to_dict(rows[0])


def update_flashcard(deck_id: int, card_id: int, data: FlashcardUpdate) -> dict:
    fields = data.model_dump(exclude_none=True)
    if "tags" in fields:
        fields["tags"] = json.dumps(fields["tags"])
    if not fields:
        return get_card(deck_id, card_id)
    sets = ", ".join(f"{k}=?" for k in fields)
    cur = _execute(
        f"UPDATE flashcards SET {sets} WHERE id=? AND deck_id=?",
        (*fields.values(), card_id, deck_id),
    )
    if cur.rowcount == 0:
        raise ValueError("Card not found")
    return get_card(deck_id, card_id)


def delete_flashcard(deck_id: int, card_id: int) -> None:
    cur = _execute("DELETE FROM flashcards WHERE id=? AND deck_id=?", (card_id, deck_id))
    if cur.rowcount == 0:
        raise ValueError("Card not found")


def due_cards(deck_id: int) -> list[dict]:
    rows = _query(
        "SELECT * FROM flashcards WHERE deck_id=? AND due<=? ORDER BY due, id",
        (deck_id, date.today().isoformat()),
    )
    return [_card_row_to_dict(r) for r in rows]


def apply_review(deck_id: int, card_id: int, quality: int) -> dict:
    card = get_card(deck_id, card_id)
    sm = sm2.review(
        SM2Card(front=card["front"], back=card["back"],
                ease=card["ease"], interval=card["interval"], reps=card["reps"]),
        quality,
    )
    due_date = (date.today() + timedelta(days=sm.interval)).isoformat()
    _execute(
        "UPDATE flashcards SET ease=?, interval=?, reps=?, due=? WHERE id=? AND deck_id=?",
        (sm.ease, sm.interval, sm.reps, due_date, card_id, deck_id),
    )
    return {"card_id": card_id, "ease": sm.ease, "interval": sm.interval, "reps": sm.reps, "due": due_date}


# ---------------------------------------------------------------- mcqs

def add_mcqs(deck_id: int, mcqs: list[MCQ]) -> None:
    if not deck_exists(deck_id):
        raise ValueError("Deck was deleted")
    with _lock:
        _db().executemany(
            "INSERT INTO mcqs (deck_id, question, options, correct_index, explanation, distractor_explanations, tags) VALUES (?,?,?,?,?,?,?)",
            [
                (deck_id, m.question, json.dumps(m.options), m.correct_index, m.explanation,
                 json.dumps(m.distractor_explanations), json.dumps(m.tags))
                for m in mcqs
            ],
        )
        _db().commit()


def get_mcq(deck_id: int, mcq_id: int) -> dict | None:
    rows = _query("SELECT * FROM mcqs WHERE id=? AND deck_id=?", (mcq_id, deck_id))
    return _mcq_row_to_dict(rows[0]) if rows else None


def delete_mcq(deck_id: int, mcq_id: int) -> None:
    cur = _execute("DELETE FROM mcqs WHERE id=? AND deck_id=?", (mcq_id, deck_id))
    if cur.rowcount == 0:
        raise ValueError("Question not found")


def record_answer(deck_id: int, mcq_id: int, correct: bool) -> None:
    _execute(
        "UPDATE mcqs SET answered=answered+1, correct=correct+? WHERE id=? AND deck_id=?",
        (1 if correct else 0, mcq_id, deck_id),
    )

"""Pydantic models shared between API, LLM output and Anki export."""

from __future__ import annotations

from typing import Literal, Optional

from pydantic import BaseModel, Field, field_validator, model_validator


class Flashcard(BaseModel):
    type: Literal["Basic", "Cloze"] = "Basic"
    front: str = ""
    back: str = ""
    text: str = ""  # for Cloze: the sentence with {{c1::...}} markers
    tags: list[str] = Field(default_factory=list)
    source: str = ""  # slide number / timestamp / page ref

    @model_validator(mode="after")
    def _require_content(self) -> "Flashcard":
        """A card must be usable: Basic needs a front and back, Cloze needs text."""
        if self.type == "Cloze":
            if not self.text.strip():
                raise ValueError("Cloze card needs a 'text' field with {{c1::...}} markers")
        elif not (self.front.strip() and self.back.strip()):
            raise ValueError("Basic card needs a non-empty front and back")
        return self


class MCQ(BaseModel):
    question: str
    options: list[str]
    correct_index: int
    explanation: str = ""
    distractor_explanations: dict[str, str] = Field(default_factory=dict)
    tags: list[str] = Field(default_factory=list)

    @field_validator("distractor_explanations", mode="before")
    @classmethod
    def _keep_only_index_keys(cls, v):
        """Tolerate models that merge stray keys (e.g. "tags") into the map."""
        if not isinstance(v, dict):
            return {}
        return {k: str(val) for k, val in v.items() if k.isdigit() and isinstance(val, str)}

    @model_validator(mode="after")
    def _check_options(self) -> "MCQ":
        """A question must have options and a valid answer index."""
        if len(self.options) < 2:
            raise ValueError("A question needs at least 2 options")
        if not 0 <= self.correct_index < len(self.options):
            raise ValueError("correct_index is out of range for the given options")
        return self


class GenerateRequest(BaseModel):
    source_text: str
    flashcards: bool = True
    mcqs: bool = True
    num_cards: int = Field(default=15, ge=1, le=200)
    num_mcqs: int = Field(default=5, ge=1, le=100)
    tags: list[str] = Field(default_factory=list)


class GenerationResult(BaseModel):
    flashcards: list[Flashcard] = Field(default_factory=list)
    mcqs: list[MCQ] = Field(default_factory=list)


class FlashcardUpdate(BaseModel):
    front: Optional[str] = None
    back: Optional[str] = None
    text: Optional[str] = None
    tags: Optional[list[str]] = None
    source: Optional[str] = None

    @model_validator(mode="after")
    def _not_empty(self) -> "FlashcardUpdate":
        for field in ("front", "back", "text"):
            value = getattr(self, field)
            if value is not None and not value.strip():
                raise ValueError(f"{field} cannot be empty")
        return self


class ReviewRequest(BaseModel):
    deck_id: int
    card_id: int
    quality: int = Field(ge=0, le=5)  # SM-2 grade 0..5


class SM2Card(BaseModel):
    front: str
    back: str
    ease: float = 2.5
    interval: int = 0
    reps: int = 0
    due: int = 0

"use strict";

/* ---------------------------------------------------------------- state */

const S = {
  decks: [],
  deckId: null,
  deck: null,
  tab: "generate",
  job: null,
  filter: "",
  review: [],
  reviewIdx: 0,
  quizIdx: 0,
  quizAnswered: {},
  quizScore: { answered: 0, correct: 0 },
  model: null,
  modalOpen: false,
};

const $ = (id) => document.getElementById(id);

/* ---------------------------------------------------------------- platform */

function detectPlatform() {
