 /* ---------------------------------------------------------------- toasts */

 .toasts {
   position: fixed; bottom: 20px; right: 20px; z-index: 100;
   display: flex; flex-direction: column; gap: 6px; max-width: 320px;
 }
 .toast {
   background: var(--surface);
   border: 1px solid var(--border);
   border-left: 3px solid var(--accent);
   padding: 10px 14px; border-radius: var(--radius);
   font-size: 13px; color: var(--text);
   box-shadow: var(--shadow-lg);
-  animation: toast-in .2s ease;
+  animation: fadeIn 0.25s ease;
+  backdrop-filter: blur(8px);
 }
 .toast.ok { border-left-color: var(--green); }
 .toast.err { border-left-color: var(--rose); }
-.toast.out { animation: toast-out .25s ease forwards; }
-@keyframes toast-in { from { transform: translateY(6px); opacity: 0; } }
-@keyframes toast-out { to { transform: translateY(4px); opacity: 0; } }
+.toast.out { animation: fadeOut 0.25s ease forwards; }
+@keyframes fadeOut { to { opacity: 0; transform: translateY(4px); } }

 /* ---------------------------------------------------------------- modal */

 .modal-backdrop {
   position: fixed; inset: 0; z-index: 90;
   background: rgba(0,0,0,0.4);
   display: grid; place-items: center;
   backdrop-filter: blur(4px);
+  animation: fadeIn 0.2s ease;
 }
 .modal {
   width: min(400px, 90vw);
   background: var(--surface);
   border: 1px solid var(--border);
   border-radius: var(--radius-lg);
   padding: 20px;
   box-shadow: var(--shadow-lg);
+  animation: scaleIn 0.2s ease;
 }
 .modal h3 { margin: 0 0 10px; font-size: 15px; font-weight: 600; }
 .modal .row { margin: 0; }
 .modal .actions { display: flex; gap: 8px; justify-content: flex-end; margin-top: 14px; }
 .modal .actions .confirm { background: var(--rose); border-color: var(--rose); color: #fff; }

 .prefs-row { display: flex; align-items: center; gap: 10px; margin: 10px 0; }
 .prefs-row label { font-size: 13px; font-weight: 600; width: 70px; flex-shrink: 0; }
 .seg { display: flex; gap: 3px; background: var(--bg-alt); border: 1px solid var(--border); border-radius: 8px; padding: 3px; }
 .seg button { border: none; background: transparent; color: var(--text-muted); font-size: 12px; padding: 5px 10px; border-radius: 6px; cursor: pointer; font-family: var(--font); }
