input.content:
/* ---------------------------------------------------------------- tokens
   Shared design tokens for landing + app pages. Both CSS files import this
   via @import so there is a single source of truth for colors, spacing, and
   typography. */

:root {
  --bg: #fafbfc;
  --bg-alt: #f1f3f5;
  --surface: #ffffff;
  --surface-elevated: #ffffff;
  --accent: #2563eb;
  --accent-soft: #dbeafe;
  --accent-hover: #1d4ed8;
  --text: #111827;
  --text-secondary: #4b5563;
  --text-muted: #9ca3af;
  --border: #e5e7eb;
  --border-strong: #d1d5db;
  --green: #059669;
  --green-soft: #d1fae5;
  --rose: #e11d48;
  --rose-soft: #ffe4e6;
  --amber: #d97706;
  --amber-soft: #fef3c7;
  --grad: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow: 0 4px 12px rgba(0,0,0,0.06);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.08);
  --radius: 12px;
  --radius-lg: 18px;
  --font: "DM Sans", system-ui, -apple-system, sans-serif;
  --font-mono: "JetBrains Mono", "Cascadia Mono", monospace;
  --sidebar-w: 240px;
  --transition-fast: 0.15s ease;
  --transition-med: 0.25s ease;
}

:root[data-theme="dark"] {
  --bg: #0a0a0f;
  --bg-alt: #111118;
  --surface: #16161f;
  --surface-elevated: #1c1c27;
  --accent: #60a5fa;
  --accent-soft: rgba(37,99,235,0.15);
  --accent-hover: #93bbfd;
  --text: #e5e7eb;
  --text-secondary: #9ca3af;
  --text-muted: #6b7280;
  --border: #26262e;
  --border-strong: #33333d;
  --green-soft: rgba(5,150,105,0.15);
  --rose-soft: rgba(225,29,72,0.15);
  --amber-soft: rgba(217,119,6,0.15);
  --grad: linear-gradient(135deg, #60a5fa 0%, #a78bfa 100%);
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.2);
  --shadow: 0 4px 12px rgba(0,0,0,0.3);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.4);
}

html.fs-compact { zoom: 0.92; }
html.fs-large { zoom: 1.12; }

*, *::before, *::after { box-sizing: border-box; }
html { scroll-behavior: smooth; }

body {
  margin: 0;
  color: var(--text);
  font-family: var(--font);
  line-height: 1.6;
  background: var(--bg);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

::selection { background: rgba(37,99,235,0.15); }

::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: var(--border-strong); border-radius: 999px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* ---------------------------------------------------------------- utility animations */

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: none; }
}

@keyframes slideInRight {
  from { opacity: 0; transform: translateX(12px); }
  to { opacity: 1; transform: none; }
}

@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: none; }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

@keyframes shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

.animate-in { animation: fadeIn 0.3s ease both; }

/* ---------------------------------------------------------------- skeleton loading */

.skeleton {
  background: linear-gradient(90deg, var(--bg-alt) 25%, var(--border) 50%, var(--bg-alt) 75%);
  background-size: 200% 100%;
  animation: shimmer 1.5s ease-in-out infinite;
  border-radius: var(--radius);
}

.skeleton-text { height: 14px; margin-bottom: 8px; }
