/* ---------------------------------------------------------------- buttons */

.btn-primary, .btn-ghost {
  display: inline-flex; align-items: center; justify-content: center;
  font-weight: 600; border-radius: var(--radius); padding: 10px 20px;
  font-size: 14px; font-family: var(--font); cursor: pointer; border: none;
  transition: transform var(--transition-fast), box-shadow var(--transition-med), background var(--transition-fast);
}
