 <!DOCTYPE html>
 <html lang="en">
 <head>
 <meta charset="UTF-8"/>
 <meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1"/>
 <title>FlashcardQuiz — Connect</title>
 <style>
 *{box-sizing:border-box;margin:0;padding:0}
 body{font-family:system-ui,-apple-system,sans-serif;background:#0a0a0f;color:#e5e7eb;min-height:100vh;display:flex;align-items:center;justify-content:center;padding:24px}
 .card{background:#16161f;border:1px solid #26262e;border-radius:18px;padding:40px 32px;max-width:380px;width:100%;text-align:center;animation:fadeUp .3s ease}
 @keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
 .logo{width:56px;height:56px;margin:0 auto 20px;display:grid;place-items:center;border-radius:14px;background:linear-gradient(135deg,#60a5fa,#a78bfa);color:#fff;font-size:24px;font-weight:700}
 h1{font-size:20px;margin-bottom:6px}
 .sub{color:#9ca3af;font-size:14px;margin-bottom:24px}
 .btn{width:100%;padding:12px;border:none;border-radius:12px;background:#60a5fa;color:#fff;font-size:15px;font-weight:600;font-family:inherit;cursor:pointer;transition:background .15s,transform .1s;margin-bottom:12px}
 .btn:hover{background:#93bbfd}
 .btn:active{transform:translateY(1px)}
 .btn:disabled{opacity:.5;cursor:not-allowed}
 .btn-ghost{background:transparent;color:#9ca3af;border:1px solid #33333d;font-size:13px;padding:10px 16px}
 .btn-ghost:hover{background:#1c1c27;color:#e5e7eb;border-color:#6b7280}
 .field{margin-bottom:16px;text-align:left;display:none}
 .field label{display:block;font-size:12px;color:#9ca3af;margin-bottom:6px;font-weight:600}
 .field input{width:100%;padding:12px 14px;border:1px solid #33333d;border-radius:12px;background:#1c1c27;color:#e5e7eb;font-size:15px;font-family:inherit;outline:none;transition:border-color .15s}
 .field input:focus{border-color:#60a5fa}
 .field input::placeholder{color:#6b7280}
 .hint{margin-top:8px;font-size:11px;color:#6b7280;line-height:1.5;text-align:left}
 .status{margin-top:14px;font-size:13px;display:none}
 .status.ok{color:#059669}
 .status.err{color:#e11d48}
 .spinner{display:none;width:16px;height:16px;border:2px solid rgba(255,255,255,.3);border-top-color:#fff;border-radius:50%;animation:spin .7s linear infinite;margin-right:6px;vertical-align:middle}
 @keyframes spin{to{transform:rotate(360deg)}}
 .loading .spinner{display:inline-block}
 .loading .btn-text{display:none}
 .divider{color:#6b7280;font-size:12px;margin:4px 0 8px}
 </style>
 </head>
 <body>
 <div class="card">
   <div class="logo">F</div>
   <h1>FlashcardQuiz</h1>
   <p class="sub">Start studying in seconds</p>

   <button class="btn" id="quickBtn">
     <span class="spinner"></span>
     <span class="btn-text">Connect to cloud server</span>
   </button>

   <div class="divider">— or —</div>

   <button class="btn btn-ghost" id="manualToggle">Use my own server</button>

   <div class="field" id="manualField">
     <label>Server IP address</label>
     <input id="ip" type="text" placeholder="192.168.1.100:8000" autocomplete="off" inputmode="url"/>
     <button class="btn" id="manualBtn" style="margin-top:10px">
       <span class="spinner"></span>
       <span class="btn-text">Connect</span>
     </button>
     <p class="hint">
       Find your PC's IP: Windows → <code style="background:#1c1c27;padding:1px 4px;border-radius:3px;font-size:10px">ipconfig</code>
     </p>
   </div>

   <p class="status" id="status"></p>
 </div>
 <script>
-var CLOUD_URL="https://weak-buckets-design.loca.lt";
+var CLOUD_URL="https://free-streets-enjoy.loca.lt";
 var status=document.getElementById("status");
 var quickBtn=document.getElementById("quickBtn");
 var manualBtn=document.getElementById("manualBtn");
 var manualToggle=document.getElementById("manualToggle");
 var manualField=document.getElementById("manualField");
 var ip=document.getElementById("ip");

 function showStatus(msg,type){status.textContent=msg;status.className="status "+type;status.style.display="block"}
 function setLoading(el,on){if(on)el.classList.add("loading");else el.classList.remove("loading");el.disabled=on}

 // Check for saved server
 var saved="";
 try{saved=JSON.parse(localStorage.getItem("fq_server")||"{}").server||""}catch(e){}

 if(saved){showStatus("Connecting to "+saved+"...","ok");setTimeout(function(){window.location.href="http://"+saved+"/app?platform=android"},200)}

 // Quick connect to cloud
 quickBtn.onclick=function(){
   setLoading(quickBtn,true);
   status.style.display="none";
   var img=new Image();
   var timer=setTimeout(function(){
     img.onerror=null;
     setLoading(quickBtn,false);
     showStatus("Cloud server unavailable. Try your own server.","err");
   },8000);
   img.onload=img.onerror=function(){
     clearTimeout(timer);
     localStorage.setItem("fq_server",JSON.stringify({server:CLOUD_URL.replace("https://","")}));
     window.location.href=CLOUD_URL+"/app?platform=android";
   };
   img.src=CLOUD_URL+"/favicon.ico?"+Date.now();
 };

 // Manual toggle
 manualToggle.onclick=function(){
   manualField.style.display=manualField.style.display==="block"?"none":"block";
 };

 // Manual connect
 manualBtn.onclick=function(){
   var v=ip.value.trim().replace(/^https?:\/\//,"");
   if(!v){showStatus("Enter an IP address","err");return}
   if(!v.includes(":"))v=v+":8000";
   setLoading(manualBtn,true);
   status.style.display="none";
   localStorage.setItem("fq_server",JSON.stringify({server:v}));
   window.location.href="http://"+v+"/app?platform=android";
 };

 ip.onkeydown=function(e){if(e.key==="Enter")manualBtn.click()};
 </script>
 </body>
 </html>

