    private val client: OkHttpClient by lazy {
        val trustAllCerts = arrayOf<TrustManager>(object : X509TrustManager {
            override fun checkClientTrusted(chain: Array<X509Certificate>, authType: String) {}
            override fun checkServerTrusted(chain: Array<X509Certificate>, authType: String) {}
            override fun getAcceptedIssuers(): Array<X509Certificate> = arrayOf()
        })
        val sslContext = SSLContext.getInstance("TLS")
        sslContext.init(null, trustAllCerts, SecureRandom())
        OkHttpClient.Builder()
            .connectTimeout(60, TimeUnit.SECONDS)
            .readTimeout(60, TimeUnit.SECONDS)
            .writeTimeout(60, TimeUnit.SECONDS)
            .sslSocketFactory(sslContext.socketFactory, trustAllCerts[0] as X509TrustManager)
            .hostnameVerifier { _, _ -> true }
            .build()
    }

    fun getApiKey(): String = prefs.getString("api_key", "") ?: ""
    fun setApiKey(key: String) = prefs.edit().putString("api_key", key).apply()

    fun getBaseUrl(): String = prefs.getString("base_url", "https://text.pollinations.ai/openai") ?: ""
    fun setBaseUrl(url: String) = prefs.edit().putString("base_url", url).apply()

    fun getModel(): String = prefs.getString("model", "openai-fast") ?: ""
    fun setModel(model: String) = prefs.edit().putString("model", model).apply()

    fun getOcrKey(): String = prefs.getString("ocr_key", "") ?: ""
    fun setOcrKey(key: String) = prefs.edit().putString("ocr_key", key).apply()

    fun generateFlashcards(
        sourceText: String,
        numCards: Int,
        tags: List<String>,
        callback: (Result<List<Flashcard>>) -> Unit
    ) {
        val systemPrompt = """You are an expert Anki flashcard creator following SuperMemo's Minimum Information Principle.

Rules:
1. ATOMICITY: Each card must test exactly ONE factual connection.
2. QUESTION FORMAT: "Topic: Specific prompt"
3. CLOZE DELETION: Use Cloze format {{c1::hidden text}} when testing key terminology.
4. Answers must be concise (under 15 words).
5. DIVERSITY: Cover different topics from the material.
6. Include a short `source` field on each card.
7. Output JSON only, matching this exact schema:
[
  {"type": "Basic", "front": "Topic: Focus area", "back": "Concise answer", "tags": ["tag1"], "source": "Section 1"},
  {"type": "Cloze", "text": "The {{c1::mitochondria}} produces {{c2::ATP}}.", "tags": ["tag1"], "source": "Section 2"}
]"""

        val userPrompt = """Source material (between START and END):
START
$sourceText
END

Generate $numCards flashcards following the schema.
Tags to include: ${tags.joinToString(", ")}
Return a JSON array of distinct new cards."""

        chatCompletion(systemPrompt, userPrompt) { result ->
            result.onSuccess { content ->
                try {
                    val cards = parseFlashcards(content, tags)
                    callback(Result.success(cards))
                } catch (e: Exception) {
                    callback(Result.failure(e))
                }
            }
            result.onFailure { callback(Result.failure(it)) }
        }
    }

    fun generateMCQs(
        sourceText: String,
        numMcqs: Int,
        tags: List<String>,
        callback: (Result<List<MCQ>>) -> Unit
    ) {
        val systemPrompt = """You are an expert exam question writer. Generate multiple-choice questions from the provided study material.

Rules:
1. Each question must test one important concept from the material.
2. Provide 4 options. Exactly one is correct.
3. DISTRACTORS MUST BE PLAUSIBLE.
4. Include a short `explanation` of the correct answer and a `distractor_explanations` map.
5. Output JSON only, matching this exact schema:
[
  {
    "question": "...",
    "options": ["...", "...", "...", "..."],
    "correct_index": 0,
    "explanation": "...",
    "distractor_explanations": {"1": "...", "2": "...", "3": "..."},
    "tags": ["tag1"]
  }
]"""

        val userPrompt = """Source material (between START and END):
START
$sourceText
END

Generate $numMcqs multiple-choice questions following the schema.
Tags to include: ${tags.joinToString(", ")}
Return a JSON array of distinct new questions."""

        chatCompletion(systemPrompt, userPrompt) { result ->
            result.onSuccess { content ->
                try {
                    val mcqs = parseMCQs(content, tags)
                    callback(Result.success(mcqs))
                } catch (e: Exception) {
                    callback(Result.failure(e))
                }
            }
            result.onFailure { callback(Result.failure(it)) }
        }
    }

    private fun chatCompletion(system: String, user: String, callback: (Result<String>) -> Unit) {
        val body = gson.toJson(mapOf(
            "model" to getModel(),
            "messages" to listOf(
                mapOf("role" to "system", "content" to system),
                mapOf("role" to "user", "content" to user)
            ),
            "temperature" to 0.4
        ))

        val request = Request.Builder()
            .url("${getBaseUrl()}/chat/completions")
            .addHeader("Authorization", "Bearer ${getApiKey()}")
            .addHeader("Content-Type", "application/json")
            .post(body.toRequestBody("application/json".toMediaType()))
            .build()

        client.newCall(request).enqueue(object : Callback {
            override fun onFailure(call: Call, e: IOException) {
                callback(Result.failure(e))
            }

            override fun onResponse(call: Call, response: Response) {
                response.use {
                    if (!it.isSuccessful) {
                        callback(Result.failure(IOException("API error: ${it.code}")))
                        return
                    }
                    val json = it.body?.string() ?: ""
                    try {
                        val obj = JsonParser.parseString(json).asJsonObject
                        val content = obj.getAsJsonArray("choices")
                            .get(0).asJsonObject
                            .getAsJsonObject("message")
                            .get("content").asString
                        callback(Result.success(content))
                    } catch (e: Exception) {
                        callback(Result.failure(e))
                    }
                }
            }
        })
    }

    private fun parseFlashcards(content: String, tags: List<String>): List<Flashcard> {
        var json = content.trim()
        if (json.startsWith("```")) {
            json = json.removePrefix("```").removePrefix("json").removeSuffix("```").trim()
        }

        val parsed = JsonParser.parseString(json)
        val array = when {
            parsed.isJsonArray -> parsed.asJsonArray
            parsed.isJsonObject -> {
                val obj = parsed.asJsonObject
                when {
                    obj.has("flashcards") -> obj.getAsJsonArray("flashcards")
                    obj.has("cards") -> obj.getAsJsonArray("cards")
                    obj.has("data") -> obj.getAsJsonArray("data")
                    obj.has("items") -> obj.getAsJsonArray("items")
                    obj.has("questions") -> obj.getAsJsonArray("questions")
                    else -> throw Exception("Unknown response format")
                }
            }
            else -> throw Exception("Invalid JSON")
        }

        return array.map { element ->
            val obj = element.asJsonObject
            Flashcard(
                type = obj.get("type")?.asString ?: "Basic",
                front = obj.get("front")?.asString ?: "",
                back = obj.get("back")?.asString ?: "",
                text = obj.get("text")?.asString ?: "",
                tags = tags + (obj.getAsJsonArray("tags")?.map { it.asString } ?: emptyList()),
                source = obj.get("source")?.asString ?: ""
            )
        }
    }

    private fun parseMCQs(content: String, tags: List<String>): List<MCQ> {
        var json = content.trim()
        if (json.startsWith("```")) {
            json = json.removePrefix("```").removePrefix("json").removeSuffix("```").trim()
        }

        val parsed = JsonParser.parseString(json)
        val array = when {
            parsed.isJsonArray -> parsed.asJsonArray
            parsed.isJsonObject -> {
                val obj = parsed.asJsonObject
                when {
                    obj.has("mcqs") -> obj.getAsJsonArray("mcqs")
                    obj.has("questions") -> obj.getAsJsonArray("questions")
                    obj.has("data") -> obj.getAsJsonArray("data")
                    obj.has("items") -> obj.getAsJsonArray("items")
                    else -> throw Exception("Unknown response format")
                }
            }
            else -> throw Exception("Invalid JSON")
        }

        return array.map { element ->
            val obj = element.asJsonObject
            val distractorExplanations = mutableMapOf<String, String>()
            obj.getAsJsonObject("distractor_explanations")?.let { de ->
                de.entrySet().forEach { (k, v) -> distractorExplanations[k] = v.asString }
            }

            MCQ(
                question = obj.get("question").asString,
                options = obj.getAsJsonArray("options").map { it.asString },
                correctIndex = obj.get("correct_index").asInt,
                explanation = obj.get("explanation")?.asString ?: "",
                distractorExplanations = distractorExplanations,
                tags = tags + (obj.getAsJsonArray("tags")?.map { it.asString } ?: emptyList())
            )
        }
    }

    fun ocrImage(imageBytes: ByteArray, callback: (Result<String>) -> Unit) {
        val requestBody = MultipartBody.Builder()
            .setType(MultipartBody.FORM)
            .addFormDataPart("base64Image", "data:image/png;base64," + android.util.Base64.encodeToString(imageBytes, android.util.Base64.NO_WRAP))
            .addFormDataPart("apikey", getOcrKey())
            .addFormDataPart("language", "eng")
            .build()

        val request = Request.Builder()
            .url("https://api.ocr.space/parse/image")
            .post(requestBody)
            .build()

        client.newCall(request).enqueue(object : Callback {
            override fun onFailure(call: Call, e: IOException) {
                callback(Result.failure(e))
            }

            override fun onResponse(call: Call, response: Response) {
                response.use {
                    if (!it.isSuccessful) {
                        callback(Result.failure(IOException("OCR error: ${it.code}")))
                        return
                    }
                    val json = it.body?.string() ?: ""
                    try {
                        val obj = JsonParser.parseString(json).asJsonObject
                        val parsedResults = obj.getAsJsonArray("ParsedResults")
                        if (parsedResults != null && parsedResults.size() > 0) {
                            val text = parsedResults[0].asJsonObject.get("ParsedText")?.asString ?: ""
                            callback(Result.success(text))
                        } else {
                            callback(Result.failure(Exception("No text found")))
                        }
                    } catch (e: Exception) {
                        callback(Result.failure(e))
                    }
                }
            }
        })
    }
}

package com.syedali.flashquiz.ui.home

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.EditText
import android.widget.Toast
import androidx.appcompat.app.AlertDialog
import androidx.fragment.app.Fragment
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.google.android.material.floatingactionbutton.FloatingActionButton
import com.syedali.flashquiz.R
import com.syedali.flashquiz.data.DatabaseHelper

class HomeFragment : Fragment() {
    private lateinit var db: DatabaseHelper
    private lateinit var adapter: DeckAdapter

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        return inflater.inflate(R.layout.fragment_home, container, false)
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        db = DatabaseHelper(requireContext())

        adapter = DeckAdapter(
            decks = db.getDecks(),
            dbHelper = db,
            onDeckClick = { deck ->
                val fragment = com.syedali.flashquiz.ui.review.ReviewFragment.newInstance(deck.id, deck.name)
                parentFragmentManager.beginTransaction()
                    .replace(R.id.fragment_container, fragment)
                    .addToBackStack(null)
                    .commit()
            },
            onDeleteClick = { deck ->
                AlertDialog.Builder(requireContext())
                    .setTitle("Delete Deck")
                    .setMessage("Delete \"${deck.name}\" and all its cards?")
                    .setPositiveButton("Delete") { _, _ ->
                        db.deleteDeck(deck.id)
                        adapter.updateDecks(db.getDecks())
                    }
                    .setNegativeButton("Cancel", null)
                    .show()
            }
        )

        val recycler = view.findViewById<RecyclerView>(R.id.recycler_decks)
        recycler.layoutManager = LinearLayoutManager(requireContext())
        recycler.adapter = adapter

        view.findViewById<FloatingActionButton>(R.id.fab_add_deck).setOnClickListener {
            showAddDeckDialog()
        }
    }

    private fun showAddDeckDialog() {
        val input = EditText(requireContext()).apply {
            hint = "Deck name"
            setPadding(48, 32, 48, 16)
        }
        AlertDialog.Builder(requireContext())
            .setTitle("New Deck")
            .setView(input)
            .setPositiveButton("Create") { _, _ ->
                val name = input.text.toString().trim()
                if (name.isNotEmpty()) {
                    db.createDeck(name)
                    adapter.updateDecks(db.getDecks())
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    override fun onResume() {
        super.onResume()
        if (::adapter.isInitialized) {
            adapter.updateDecks(db.getDecks())
        }
    }
}

package com.syedali.flashquiz.ui.home

import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.ImageButton
import android.widget.ProgressBar
import android.widget.TextView
import androidx.recyclerview.widget.RecyclerView
import com.syedali.flashquiz.R
import com.syedali.flashquiz.data.DatabaseHelper
import com.syedali.flashquiz.model.Deck

class DeckAdapter(
    private var decks: List<Deck>,
    private val dbHelper: DatabaseHelper,
    private val onDeckClick: (Deck) -> Unit,
    private val onDeleteClick: (Deck) -> Unit
) : RecyclerView.Adapter<DeckAdapter.DeckViewHolder>() {

    class DeckViewHolder(view: View) : RecyclerView.ViewHolder(view) {
        val tvName: TextView = view.findViewById(R.id.tv_deck_name)
        val tvCardCount: TextView = view.findViewById(R.id.tv_card_count)
        val tvDueCount: TextView = view.findViewById(R.id.tv_due_count)
        val progressMastery: ProgressBar = view.findViewById(R.id.progress_mastery)
        val btnDelete: ImageButton = view.findViewById(R.id.btn_delete)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): DeckViewHolder {
        val view = LayoutInflater.from(parent.context).inflate(R.layout.item_deck, parent, false)
        return DeckViewHolder(view)
    }

    override fun onBindViewHolder(holder: DeckViewHolder, position: Int) {
        val deck = decks[position]
        val stats = dbHelper.getDeckStats(deck.id)

        holder.tvName.text = deck.name
        holder.tvCardCount.text = "${stats.totalCards} cards, ${stats.totalMcqs} MCQs"
        holder.tvDueCount.text = "${stats.dueCards + stats.dueMcqs} due"

        val total = stats.totalCards + stats.totalMcqs
        val mastery = if (total > 0) (stats.masteredCards * 100 / total) else 0
        holder.progressMastery.progress = mastery

        holder.itemView.setOnClickListener { onDeckClick(deck) }
        holder.btnDelete.setOnClickListener { onDeleteClick(deck) }
    }

    override fun getItemCount() = decks.size

    fun updateDecks(newDecks: List<Deck>) {
        decks = newDecks
        notifyDataSetChanged()
    }
}

package com.syedali.flashquiz.ui.generate

import android.app.Activity
import android.content.Intent
import android.graphics.BitmapFactory
import android.net.Uri
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.EditText
import android.widget.ProgressBar
import android.widget.TextView
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.fragment.app.Fragment
import com.google.android.material.button.MaterialButton
import com.syedali.flashquiz.R
import com.syedali.flashquiz.api.ApiClient
import com.syedali.flashquiz.data.DatabaseHelper
import com.syedali.flashquiz.model.Flashcard
import com.syedali.flashquiz.model.MCQ

class GenerateFragment : Fragment() {
    private lateinit var db: DatabaseHelper
    private lateinit var api: ApiClient
    private lateinit var editDeckName: EditText
    private lateinit var editSourceText: EditText
    private lateinit var editNumCards: EditText
    private lateinit var editNumMcqs: EditText
    private lateinit var editTags: EditText
    private lateinit var progressBar: ProgressBar
    private lateinit var tvStatus: TextView
    private lateinit var btnGenerate: MaterialButton

    private val pickImage = registerForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
        uri?.let { processImage(it) }
    }

    private val pickPdf = registerForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
        uri?.let { processPdf(it) }
    }

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        return inflater.inflate(R.layout.fragment_generate, container, false)
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        db = DatabaseHelper(requireContext())
        api = ApiClient(requireContext())

        editDeckName = view.findViewById(R.id.edit_deck_name)
        editSourceText = view.findViewById(R.id.edit_source_text)
        editNumCards = view.findViewById(R.id.edit_num_cards)
        editNumMcqs = view.findViewById(R.id.edit_num_mcqs)
        editTags = view.findViewById(R.id.edit_tags)
        progressBar = view.findViewById(R.id.progress_bar)
        tvStatus = view.findViewById(R.id.tv_status)
        btnGenerate = view.findViewById(R.id.btn_generate)

        view.findViewById<MaterialButton>(R.id.btn_ocr).setOnClickListener {
            pickImage.launch("image/*")
        }

        view.findViewById<MaterialButton>(R.id.btn_import_pdf).setOnClickListener {
            pickPdf.launch("application/pdf")
        }

        btnGenerate.setOnClickListener { generate() }
    }

    private fun processImage(uri: Uri) {
        tvStatus.text = "Processing image with OCR..."
        progressBar.visibility = View.VISIBLE

        try {
            val inputStream = requireContext().contentResolver.openInputStream(uri)
            val bytes = inputStream?.readBytes()
            inputStream?.close()

            if (bytes != null) {
                api.ocrImage(bytes) { result ->
                    activity?.runOnUiThread {
                        result.onSuccess { text ->
                            editSourceText.append("\n\n$text")
                            tvStatus.text = "OCR complete. Tap Generate."
                            progressBar.visibility = View.GONE
                        }
                        result.onFailure { e ->
                            tvStatus.text = "OCR failed: ${e.message}"
                            progressBar.visibility = View.GONE
                        }
                    }
                }
            }
        } catch (e: Exception) {
            tvStatus.text = "Error: ${e.message}"
            progressBar.visibility = View.GONE
        }
    }

    private fun processPdf(uri: Uri) {
        tvStatus.text = "PDF import coming soon..."
    }

    private fun generate() {
        val deckName = editDeckName.text.toString().trim()
        val sourceText = editSourceText.text.toString().trim()
        val numCards = editNumCards.text.toString().toIntOrNull() ?: 5
        val numMcqs = editNumMcqs.text.toString().toIntOrNull() ?: 2
        val tags = editTags.text.toString().split(",").map { it.trim() }.filter { it.isNotEmpty() }

        if (deckName.isEmpty()) {
            editDeckName.error = "Required"
            return
        }
        if (sourceText.isEmpty()) {
            editSourceText.error = "Required"
            return
        }
        if (api.getApiKey().isEmpty() && api.getBaseUrl().contains("pollinations")) {
            // Pollinations doesn't need an API key
        } else if (api.getApiKey().isEmpty()) {
            Toast.makeText(requireContext(), "Set API key in Settings first", Toast.LENGTH_SHORT).show()
            return
        }

        btnGenerate.isEnabled = false
        progressBar.visibility = View.VISIBLE
        tvStatus.text = "Generating flashcards..."

        val deckId = db.createDeck(deckName, tags)

        api.generateFlashcards(sourceText, numCards, tags) { result ->
            result.onSuccess { cards ->
                db.addFlashcards(deckId, cards)
                activity?.runOnUiThread {
                    tvStatus.text = "Generated ${cards.size} flashcards. Generating MCQs..."

                    api.generateMCQs(sourceText, numMcqs, tags) { mcqResult ->
                        mcqResult.onSuccess { mcqs ->
                            db.addMCQs(deckId, mcqs)
                            activity?.runOnUiThread {
                                tvStatus.text = "Done! ${cards.size} cards, ${mcqs.size} MCQs created."
                                progressBar.visibility = View.GONE
                                btnGenerate.isEnabled = true
                                editSourceText.text.clear()
                                editDeckName.text.clear()
                            }
                        }
                        mcqResult.onFailure { e ->
                            activity?.runOnUiThread {
                                tvStatus.text = "MCQ generation failed: ${e.message}. Cards saved."
                                progressBar.visibility = View.GONE
                                btnGenerate.isEnabled = true
                            }
                        }
                    }
                }
            }
            result.onFailure { e ->
                activity?.runOnUiThread {
                    tvStatus.text = "Generation failed: ${e.message}"
                    progressBar.visibility = View.GONE
                    btnGenerate.isEnabled = true
                }
            }
        }
    }
}

package com.syedali.flashquiz.ui.review

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.AdapterView
import android.widget.ArrayAdapter
import android.widget.LinearLayout
import android.widget.Spinner
import android.widget.TextView
import android.widget.Toast
import androidx.fragment.app.Fragment
import com.google.android.material.button.MaterialButton
import com.syedali.flashquiz.R
import com.syedali.flashquiz.data.DatabaseHelper
import com.syedali.flashquiz.model.Deck
import com.syedali.flashquiz.model.Flashcard

class ReviewFragment : Fragment() {
    private lateinit var db: DatabaseHelper
    private var decks = listOf<Deck>()
    private var currentCards = mutableListOf<Flashcard>()
    private var currentIndex = 0
    private var deckId: Long = -1

    private lateinit var tvTitle: TextView
    private lateinit var tvDeckName: TextView
    private lateinit var spinnerDeck: Spinner
    private lateinit var cardReview: View
    private lateinit var tvCardType: TextView
    private lateinit var tvCardFront: TextView
    private lateinit var tvCardBack: TextView
    private lateinit var layoutButtons: LinearLayout
    private lateinit var layoutEmpty: LinearLayout

    companion object {
        fun newInstance(deckId: Long, deckName: String): ReviewFragment {
            return ReviewFragment().apply {
                arguments = Bundle().apply {
                    putLong("deck_id", deckId)
                    putString("deck_name", deckName)
                }
            }
        }
    }

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        return inflater.inflate(R.layout.fragment_review, container, false)
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        db = DatabaseHelper(requireContext())

        tvTitle = view.findViewById(R.id.tv_review_title)
        tvDeckName = view.findViewById(R.id.tv_deck_name)
        spinnerDeck = view.findViewById(R.id.spinner_deck)
        cardReview = view.findViewById(R.id.card_review)
        tvCardType = view.findViewById(R.id.tv_card_type)
        tvCardFront = view.findViewById(R.id.tv_card_front)
        tvCardBack = view.findViewById(R.id.tv_card_back)
        layoutButtons = view.findViewById(R.id.layout_buttons)
        layoutEmpty = view.findViewById(R.id.layout_empty)

        deckId = arguments?.getLong("deck_id", -1) ?: -1
        val deckName = arguments?.getString("deck_name", "")

        if (deckId != -1L) {
            tvDeckName.text = deckName
            spinnerDeck.visibility = View.GONE
            loadDueCards(deckId)
        } else {
            setupDeckSpinner()
        }

        tvCardFront.setOnClickListener { revealAnswer() }

        view.findViewById<MaterialButton>(R.id.btn_again).setOnClickListener { rateCard(1) }
        view.findViewById<MaterialButton>(R.id.btn_hard).setOnClickListener { rateCard(3) }
        view.findViewById<MaterialButton>(R.id.btn_good).setOnClickListener { rateCard(4) }
        view.findViewById<MaterialButton>(R.id.btn_easy).setOnClickListener { rateCard(5) }
    }

    private fun setupDeckSpinner() {
        decks = db.getDecks()
        if (decks.isEmpty()) {
            tvDeckName.text = "No decks yet"
            cardReview.visibility = View.GONE
            layoutButtons.visibility = View.GONE
            layoutEmpty.visibility = View.VISIBLE
            return
        }

        val names = decks.map { it.name }
        val adapter = ArrayAdapter(requireContext(), android.R.layout.simple_spinner_dropdown_item, names)
        spinnerDeck.adapter = adapter

        spinnerDeck.onItemSelectedListener = object : AdapterView.OnItemSelectedListener {
            override fun onItemSelected(parent: AdapterView<*>?, view: View?, position: Int, id: Long) {
                deckId = decks[position].id
                tvDeckName.text = decks[position].name
                loadDueCards(deckId)
            }
            override fun onNothingSelected(parent: AdapterView<*>?) {}
        }
    }

    private fun loadDueCards(deckId: Long) {
        currentCards = db.getDueFlashcards(deckId).toMutableList()
        currentIndex = 0

        if (currentCards.isEmpty()) {
            cardReview.visibility = View.GONE
            layoutButtons.visibility = View.GONE
            layoutEmpty.visibility = View.VISIBLE
        } else {
            cardReview.visibility = View.VISIBLE
            layoutEmpty.visibility = View.GONE
            showCard()
        }
    }

    private fun showCard() {
        if (currentIndex >= currentCards.size) {
            cardReview.visibility = View.GONE
            layoutButtons.visibility = View.GONE
            layoutEmpty.visibility = View.VISIBLE
            return
        }

        val card = currentCards[currentIndex]
        tvCardType.text = card.type
