import com.syedali.flashquiz.model.Flashcard
import com.syedali.flashquiz.model.MCQ

class DatabaseHelper(context: Context) : SQLiteOpenHelper(context, "flashcardquiz.db", null, 1) {
    private val gson = Gson()

    override fun onCreate(db: SQLiteDatabase) {
        db.execSQL("""
            CREATE TABLE decks (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                tags TEXT DEFAULT '[]',
                created_at INTEGER DEFAULT (strftime('%s','now') * 1000)
            )
        """)
        db.execSQL("""
            CREATE TABLE flashcards (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                deck_id INTEGER NOT NULL,
                type TEXT DEFAULT 'Basic',
                front TEXT DEFAULT '',
                back TEXT DEFAULT '',
                text TEXT DEFAULT '',
                tags TEXT DEFAULT '[]',
                source TEXT DEFAULT '',
                ease_factor REAL DEFAULT 2.5,
                interval INTEGER DEFAULT 0,
                repetitions INTEGER DEFAULT 0,
                next_review INTEGER DEFAULT 0,
                last_review INTEGER DEFAULT 0,
                FOREIGN KEY (deck_id) REFERENCES decks(id) ON DELETE CASCADE
            )
        """)
        db.execSQL("""
            CREATE TABLE mcqs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                deck_id INTEGER NOT NULL,
                question TEXT NOT NULL,
                options TEXT NOT NULL,
                correct_index INTEGER NOT NULL,
                explanation TEXT DEFAULT '',
                distractor_explanations TEXT DEFAULT '{}',
                tags TEXT DEFAULT '[]',
                ease_factor REAL DEFAULT 2.5,
                interval INTEGER DEFAULT 0,
                repetitions INTEGER DEFAULT 0,
                next_review INTEGER DEFAULT 0,
                last_review INTEGER DEFAULT 0,
                FOREIGN KEY (deck_id) REFERENCES decks(id) ON DELETE CASCADE
            )
        """)
    }

    override fun onUpgrade(db: SQLiteDatabase, oldVersion: Int, newVersion: Int) {
        db.execSQL("DROP TABLE IF EXISTS mcqs")
        db.execSQL("DROP TABLE IF EXISTS flashcards")
        db.execSQL("DROP TABLE IF EXISTS decks")
        onCreate(db)
    }

    fun createDeck(name: String, tags: List<String> = emptyList()): Long {
        val cv = ContentValues().apply {
            put("name", name)
            put("tags", gson.toJson(tags))
        }
        return writableDatabase.insert("decks", null, cv)
    }

    fun getDecks(): List<Deck> {
        val decks = mutableListOf<Deck>()
        val cursor = readableDatabase.rawQuery("SELECT * FROM decks ORDER BY created_at DESC", null)
        while (cursor.moveToNext()) {
            decks.add(Deck(
                id = cursor.getLong(cursor.getColumnIndexOrThrow("id")),
                name = cursor.getString(cursor.getColumnIndexOrThrow("name")),
                tags = gson.fromJson(cursor.getString(cursor.getColumnIndexOrThrow("tags")), object : TypeToken<List<String>>() {}.type),
                createdAt = cursor.getLong(cursor.getColumnIndexOrThrow("created_at"))
            ))
        }
        cursor.close()
        return decks
    }

    fun deleteDeck(id: Long) {
        writableDatabase.delete("decks", "id=?", arrayOf(id.toString()))
        writableDatabase.delete("flashcards", "deck_id=?", arrayOf(id.toString()))
        writableDatabase.delete("mcqs", "deck_id=?", arrayOf(id.toString()))
    }

    fun getDeckStats(deckId: Long): DeckStats {
        val now = System.currentTimeMillis()
        val cards = readableDatabase.rawQuery("SELECT COUNT(*) FROM flashcards WHERE deck_id=?", arrayOf(deckId.toString()))
        cards.moveToFirst()
        val totalCards = cards.getInt(0)
        cards.close()

        val mcqs = readableDatabase.rawQuery("SELECT COUNT(*) FROM mcqs WHERE deck_id=?", arrayOf(deckId.toString()))
        mcqs.moveToFirst()
        val totalMcqs = mcqs.getInt(0)
        mcqs.close()

        val dueCards = readableDatabase.rawQuery("SELECT COUNT(*) FROM flashcards WHERE deck_id=? AND next_review<=?", arrayOf(deckId.toString(), now.toString()))
        dueCards.moveToFirst()
        val due = dueCards.getInt(0)
        dueCards.close()

        val dueMcqs = readableDatabase.rawQuery("SELECT COUNT(*) FROM mcqs WHERE deck_id=? AND next_review<=?", arrayOf(deckId.toString(), now.toString()))
        dueMcqs.moveToFirst()
        val dueM = dueMcqs.getInt(0)
        dueMcqs.close()

        val mastered = readableDatabase.rawQuery("SELECT COUNT(*) FROM flashcards WHERE deck_id=? AND interval>=21", arrayOf(deckId.toString()))
        mastered.moveToFirst()
        val m = mastered.getInt(0)
        mastered.close()

        return DeckStats(totalCards, totalMcqs, due, dueM, m)
    }

    fun addFlashcards(deckId: Long, cards: List<Flashcard>) {
        writableDatabase.beginTransaction()
        try {
            for (card in cards) {
                val cv = ContentValues().apply {
                    put("deck_id", deckId)
                    put("type", card.type)
                    put("front", card.front)
                    put("back", card.back)
                    put("text", card.text)
                    put("tags", gson.toJson(card.tags))
                    put("source", card.source)
                }
                writableDatabase.insert("flashcards", null, cv)
            }
            writableDatabase.setTransactionSuccessful()
        } finally {
            writableDatabase.endTransaction()
        }
    }

    fun getFlashcards(deckId: Long): List<Flashcard> {
        val cards = mutableListOf<Flashcard>()
        val cursor = readableDatabase.rawQuery("SELECT * FROM flashcards WHERE deck_id=?", arrayOf(deckId.toString()))
        while (cursor.moveToNext()) {
            cards.add(Flashcard(
                id = cursor.getLong(cursor.getColumnIndexOrThrow("id")),
                deckId = cursor.getLong(cursor.getColumnIndexOrThrow("deck_id")),
                type = cursor.getString(cursor.getColumnIndexOrThrow("type")),
                front = cursor.getString(cursor.getColumnIndexOrThrow("front")),
                back = cursor.getString(cursor.getColumnIndexOrThrow("back")),
                text = cursor.getString(cursor.getColumnIndexOrThrow("text")),
                tags = gson.fromJson(cursor.getString(cursor.getColumnIndexOrThrow("tags")), object : TypeToken<List<String>>() {}.type),
                source = cursor.getString(cursor.getColumnIndexOrThrow("source")),
                easeFactor = cursor.getDouble(cursor.getColumnIndexOrThrow("ease_factor")),
                interval = cursor.getInt(cursor.getColumnIndexOrThrow("interval")),
                repetitions = cursor.getInt(cursor.getColumnIndexOrThrow("repetitions")),
                nextReview = cursor.getLong(cursor.getColumnIndexOrThrow("next_review")),
                lastReview = cursor.getLong(cursor.getColumnIndexOrThrow("last_review"))
            ))
        }
        cursor.close()
        return cards
    }

    fun getDueFlashcards(deckId: Long): List<Flashcard> {
        val now = System.currentTimeMillis()
        val cards = mutableListOf<Flashcard>()
        val cursor = readableDatabase.rawQuery(
            "SELECT * FROM flashcards WHERE deck_id=? AND next_review<=? ORDER BY next_review",
            arrayOf(deckId.toString(), now.toString())
        )
        while (cursor.moveToNext()) {
            cards.add(Flashcard(
                id = cursor.getLong(cursor.getColumnIndexOrThrow("id")),
                deckId = cursor.getLong(cursor.getColumnIndexOrThrow("deck_id")),
                type = cursor.getString(cursor.getColumnIndexOrThrow("type")),
                front = cursor.getString(cursor.getColumnIndexOrThrow("front")),
                back = cursor.getString(cursor.getColumnIndexOrThrow("back")),
                text = cursor.getString(cursor.getColumnIndexOrThrow("text")),
                tags = gson.fromJson(cursor.getString(cursor.getColumnIndexOrThrow("tags")), object : TypeToken<List<String>>() {}.type),
                source = cursor.getString(cursor.getColumnIndexOrThrow("source")),
                easeFactor = cursor.getDouble(cursor.getColumnIndexOrThrow("ease_factor")),
                interval = cursor.getInt(cursor.getColumnIndexOrThrow("interval")),
                repetitions = cursor.getInt(cursor.getColumnIndexOrThrow("repetitions")),
                nextReview = cursor.getLong(cursor.getColumnIndexOrThrow("next_review")),
                lastReview = cursor.getLong(cursor.getColumnIndexOrThrow("last_review"))
            ))
        }
        cursor.close()
        return cards
    }

    fun updateFlashcardSM2(id: Long, quality: Int) {
        val card = readableDatabase.rawQuery("SELECT * FROM flashcards WHERE id=?", arrayOf(id.toString()))
        if (card.moveToFirst()) {
            var ef = card.getDouble(card.getColumnIndexOrThrow("ease_factor"))
            var interval = card.getInt(card.getColumnIndexOrThrow("interval"))
            var rep = card.getInt(card.getColumnIndexOrThrow("repetitions"))

            if (quality >= 3) {
                if (rep == 0) interval = 1
                else if (rep == 1) interval = 6
                else interval = (interval * ef).toInt()
                rep++
            } else {
                rep = 0
                interval = 1
            }

            ef = ef + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02))
            if (ef < 1.3) ef = 1.3

            val now = System.currentTimeMillis()
            val nextReview = now + interval * 24L * 60 * 60 * 1000

            val cv = ContentValues().apply {
                put("ease_factor", ef)
                put("interval", interval)
                put("repetitions", rep)
                put("next_review", nextReview)
                put("last_review", now)
            }
            writableDatabase.update("flashcards", cv, "id=?", arrayOf(id.toString()))
        }
        card.close()
    }

    fun addMCQs(deckId: Long, mcqs: List<MCQ>) {
        writableDatabase.beginTransaction()
        try {
            for (mcq in mcqs) {
                val cv = ContentValues().apply {
                    put("deck_id", deckId)
                    put("question", mcq.question)
                    put("options", gson.toJson(mcq.options))
                    put("correct_index", mcq.correctIndex)
                    put("explanation", mcq.explanation)
                    put("distractor_explanations", gson.toJson(mcq.distractorExplanations))
                    put("tags", gson.toJson(mcq.tags))
                }
                writableDatabase.insert("mcqs", null, cv)
            }
            writableDatabase.setTransactionSuccessful()
        } finally {
            writableDatabase.endTransaction()
        }
    }

    fun getDueMCQs(deckId: Long): List<MCQ> {
        val now = System.currentTimeMillis()
        val mcqs = mutableListOf<MCQ>()
        val cursor = readableDatabase.rawQuery(
            "SELECT * FROM mcqs WHERE deck_id=? AND next_review<=? ORDER BY next_review",
            arrayOf(deckId.toString(), now.toString())
        )
        while (cursor.moveToNext()) {
            mcqs.add(MCQ(
                id = cursor.getLong(cursor.getColumnIndexOrThrow("id")),
                deckId = cursor.getLong(cursor.getColumnIndexOrThrow("deck_id")),
                question = cursor.getString(cursor.getColumnIndexOrThrow("question")),
                options = gson.fromJson(cursor.getString(cursor.getColumnIndexOrThrow("options")), object : TypeToken<List<String>>() {}.type),
                correctIndex = cursor.getInt(cursor.getColumnIndexOrThrow("correct_index")),
                explanation = cursor.getString(cursor.getColumnIndexOrThrow("explanation")),
                distractorExplanations = gson.fromJson(cursor.getString(cursor.getColumnIndexOrThrow("distractor_explanations")), object : TypeToken<Map<String, String>>() {}.type),
                tags = gson.fromJson(cursor.getString(cursor.getColumnIndexOrThrow("tags")), object : TypeToken<List<String>>() {}.type),
                easeFactor = cursor.getDouble(cursor.getColumnIndexOrThrow("ease_factor")),
                interval = cursor.getInt(cursor.getColumnIndexOrThrow("interval")),
                repetitions = cursor.getInt(cursor.getColumnIndexOrThrow("repetitions")),
                nextReview = cursor.getLong(cursor.getColumnIndexOrThrow("next_review")),
                lastReview = cursor.getLong(cursor.getColumnIndexOrThrow("last_review"))
            ))
        }
        cursor.close()
        return mcqs
    }

    fun updateMCQSM2(id: Long, quality: Int) {
        val mcq = readableDatabase.rawQuery("SELECT * FROM mcqs WHERE id=?", arrayOf(id.toString()))
        if (mcq.moveToFirst()) {
            var ef = mcq.getDouble(mcq.getColumnIndexOrThrow("ease_factor"))
            var interval = mcq.getInt(mcq.getColumnIndexOrThrow("interval"))
            var rep = mcq.getInt(mcq.getColumnIndexOrThrow("repetitions"))

            if (quality >= 3) {
                if (rep == 0) interval = 1
                else if (rep == 1) interval = 6
                else interval = (interval * ef).toInt()
                rep++
            } else {
                rep = 0
                interval = 1
            }

            ef = ef + (0.1 - (5 - quality) * (0.08 + (5 - quality) * 0.02))
            if (ef < 1.3) ef = 1.3

            val now = System.currentTimeMillis()
            val nextReview = now + interval * 24L * 60 * 60 * 1000

            val cv = ContentValues().apply {
                put("ease_factor", ef)
                put("interval", interval)
                put("repetitions", rep)
                put("next_review", nextReview)
                put("last_review", now)
            }
            writableDatabase.update("mcqs", cv, "id=?", arrayOf(id.toString()))
        }
        mcq.close()
    }
}

package com.syedali.flashquiz.ui.generate

import android.app.Activity
import android.content.Intent
import android.graphics.BitmapFactory
import android.net.Uri
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.EditText
import android.widget.ProgressBar
import android.widget.TextView
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.fragment.app.Fragment
import com.google.android.material.button.MaterialButton
import com.syedali.flashquiz.R
import com.syedali.flashquiz.api.ApiClient
import com.syedali.flashquiz.data.DatabaseHelper
import com.syedali.flashquiz.model.Flashcard
import com.syedali.flashquiz.model.MCQ

class GenerateFragment : Fragment() {
    private lateinit var db: DatabaseHelper
    private lateinit var api: ApiClient
    private lateinit var editDeckName: EditText
    private lateinit var editSourceText: EditText
    private lateinit var editNumCards: EditText
    private lateinit var editNumMcqs: EditText
    private lateinit var editTags: EditText
    private lateinit var progressBar: ProgressBar
    private lateinit var tvStatus: TextView
    private lateinit var btnGenerate: MaterialButton

    private val pickImage = registerForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
        uri?.let { processImage(it) }
    }

    private val pickPdf = registerForActivityResult(ActivityResultContracts.GetContent()) { uri: Uri? ->
        uri?.let { processPdf(it) }
    }

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        return inflater.inflate(R.layout.fragment_generate, container, false)
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        db = DatabaseHelper(requireContext())
        api = ApiClient(requireContext())

        editDeckName = view.findViewById(R.id.edit_deck_name)
        editSourceText = view.findViewById(R.id.edit_source_text)
        editNumCards = view.findViewById(R.id.edit_num_cards)
        editNumMcqs = view.findViewById(R.id.edit_num_mcqs)
        editTags = view.findViewById(R.id.edit_tags)
        progressBar = view.findViewById(R.id.progress_bar)
        tvStatus = view.findViewById(R.id.tv_status)
        btnGenerate = view.findViewById(R.id.btn_generate)

        view.findViewById<MaterialButton>(R.id.btn_ocr).setOnClickListener {
            pickImage.launch("image/*")
        }

        view.findViewById<MaterialButton>(R.id.btn_import_pdf).setOnClickListener {
            pickPdf.launch("application/pdf")
        }

        btnGenerate.setOnClickListener { generate() }
    }

    private fun processImage(uri: Uri) {
        tvStatus.text = "Processing image with OCR..."
        progressBar.visibility = View.VISIBLE

        try {
            val inputStream = requireContext().contentResolver.openInputStream(uri)
            val bytes = inputStream?.readBytes()
            inputStream?.close()

            if (bytes != null) {
                api.ocrImage(bytes) { result ->
                    activity?.runOnUiThread {
                        result.onSuccess { text ->
                            editSourceText.append("\n\n$text")
                            tvStatus.text = "OCR complete. Tap Generate."
                            progressBar.visibility = View.GONE
                        }
                        result.onFailure { e ->
                            tvStatus.text = "OCR failed: ${e.message}"
                            progressBar.visibility = View.GONE
                        }
                    }
                }
            }
        } catch (e: Exception) {
            tvStatus.text = "Error: ${e.message}"
            progressBar.visibility = View.GONE
        }
    }

    private fun processPdf(uri: Uri) {
        tvStatus.text = "PDF import coming soon..."
    }

    private fun generate() {
        val deckName = editDeckName.text.toString().trim()
        val sourceText = editSourceText.text.toString().trim()
        val numCards = editNumCards.text.toString().toIntOrNull() ?: 5
        val numMcqs = editNumMcqs.text.toString().toIntOrNull() ?: 2
        val tags = editTags.text.toString().split(",").map { it.trim() }.filter { it.isNotEmpty() }

        if (deckName.isEmpty()) {
            editDeckName.error = "Required"
            return
        }
        if (sourceText.isEmpty()) {
            editSourceText.error = "Required"
            return
        }

        btnGenerate.isEnabled = false
        progressBar.visibility = View.VISIBLE
        tvStatus.text = "Generating cards..."

        val deckId = db.createDeck(deckName, tags)

        // Run flashcard and MCQ generation in parallel for speed
        var cardsDone = false
        var mcqsDone = false
        var savedCards = listOf<com.syedali.flashquiz.model.Flashcard>()
        var savedMcqs = listOf<com.syedali.flashquiz.model.MCQ>()

        fun checkComplete() {
            if (cardsDone && mcqsDone) {
                activity?.runOnUiThread {
                    tvStatus.text = "Done! ${savedCards.size} cards, ${savedMcqs.size} MCQs created."
                    progressBar.visibility = View.GONE
                    btnGenerate.isEnabled = true
                    editSourceText.text.clear()
                    editDeckName.text.clear()
                }
            }
        }

        api.generateFlashcards(sourceText, numCards, tags) { result ->
            result.onSuccess { cards ->
                db.addFlashcards(deckId, cards)
                savedCards = cards
            }
            result.onFailure { e ->
                activity?.runOnUiThread {
                    tvStatus.text = "Card generation failed: ${e.message}"
                }
            }
            cardsDone = true
            checkComplete()
        }

        api.generateMCQs(sourceText, numMcqs, tags) { result ->
            result.onSuccess { mcqs ->
                db.addMCQs(deckId, mcqs)
                savedMcqs = mcqs
            }
            result.onFailure { e ->
                activity?.runOnUiThread {
                    tvStatus.text = "MCQ generation failed: ${e.message}"
                }
            }
            mcqsDone = true
            checkComplete()
        }
    }
}

package com.syedali.flashquiz.ui.review

import android.animation.AnimatorInflater
import android.animation.AnimatorSet
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.view.animation.AccelerateDecelerateInterpolator
import android.widget.AdapterView
import android.widget.ArrayAdapter
import android.widget.LinearLayout
import android.widget.Spinner
import android.widget.TextView
import androidx.cardview.widget.CardView
import androidx.fragment.app.Fragment
import com.google.android.material.button.MaterialButton
import com.syedali.flashquiz.R
import com.syedali.flashquiz.data.DatabaseHelper
import com.syedali.flashquiz.model.Deck
import com.syedali.flashquiz.model.Flashcard

class ReviewFragment : Fragment() {
    private lateinit var db: DatabaseHelper
    private var decks = listOf<Deck>()
    private var currentCards = mutableListOf<Flashcard>()
    private var currentIndex = 0
    private var deckId: Long = -1
    private var isShowingAnswer = false

    private lateinit var tvTitle: TextView
    private lateinit var tvDeckName: TextView
    private lateinit var tvProgress: TextView
    private lateinit var spinnerDeck: Spinner
    private lateinit var cardReview: CardView
    private lateinit var tvCardType: TextView
    private lateinit var tvCardFront: TextView
    private lateinit var tvCardBack: TextView
    private lateinit var tvTapHint: TextView
    private lateinit var layoutButtons: LinearLayout
    private lateinit var layoutEmpty: LinearLayout

    companion object {
        fun newInstance(deckId: Long, deckName: String): ReviewFragment {
            return ReviewFragment().apply {
                arguments = Bundle().apply {
                    putLong("deck_id", deckId)
                    putString("deck_name", deckName)
                }
            }
        }
    }

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        return inflater.inflate(R.layout.fragment_review, container, false)
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        db = DatabaseHelper(requireContext())

        tvTitle = view.findViewById(R.id.tv_review_title)
        tvDeckName = view.findViewById(R.id.tv_deck_name)
        tvProgress = view.findViewById(R.id.tv_progress)
        spinnerDeck = view.findViewById(R.id.spinner_deck)
        cardReview = view.findViewById(R.id.card_review)
        tvCardType = view.findViewById(R.id.tv_card_type)
        tvCardFront = view.findViewById(R.id.tv_card_front)
        tvCardBack = view.findViewById(R.id.tv_card_back)
        tvTapHint = view.findViewById(R.id.tv_tap_hint)
        layoutButtons = view.findViewById(R.id.layout_buttons)
        layoutEmpty = view.findViewById(R.id.layout_empty)

        deckId = arguments?.getLong("deck_id", -1) ?: -1
        val deckName = arguments?.getString("deck_name", "")

        if (deckId != -1L) {
            tvDeckName.text = deckName
            spinnerDeck.visibility = View.GONE
            loadDueCards(deckId)
        } else {
            setupDeckSpinner()
        }

        cardReview.setOnClickListener { flipCard() }

        view.findViewById<MaterialButton>(R.id.btn_again).setOnClickListener { rateCard(1) }
        view.findViewById<MaterialButton>(R.id.btn_hard).setOnClickListener { rateCard(3) }
        view.findViewById<MaterialButton>(R.id.btn_good).setOnClickListener { rateCard(4) }
        view.findViewById<MaterialButton>(R.id.btn_easy).setOnClickListener { rateCard(5) }
    }

    private fun setupDeckSpinner() {
        decks = db.getDecks()
        if (decks.isEmpty()) {
            tvDeckName.text = "No decks yet"
            cardReview.visibility = View.GONE
            layoutButtons.visibility = View.GONE
            layoutEmpty.visibility = View.VISIBLE
            return
        }

        val names = decks.map { it.name }
        val adapter = ArrayAdapter(requireContext(), android.R.layout.simple_spinner_dropdown_item, names)
        spinnerDeck.adapter = adapter
        spinnerDeck.visibility = View.VISIBLE

        spinnerDeck.onItemSelectedListener = object : AdapterView.OnItemSelectedListener {
            override fun onItemSelected(parent: AdapterView<*>?, view: View?, position: Int, id: Long) {
                deckId = decks[position].id
                tvDeckName.text = decks[position].name
                loadDueCards(deckId)
            }
            override fun onNothingSelected(parent: AdapterView<*>?) {}
        }
    }

    private fun loadDueCards(deckId: Long) {
        currentCards = db.getDueFlashcards(deckId).toMutableList()
        currentIndex = 0
        isShowingAnswer = false

        if (currentCards.isEmpty()) {
            cardReview.visibility = View.GONE
            layoutButtons.visibility = View.GONE
            layoutEmpty.visibility = View.VISIBLE
            tvProgress.text = "0/0"
        } else {
            cardReview.visibility = View.VISIBLE
            layoutEmpty.visibility = View.GONE
            layoutButtons.visibility = View.GONE
            tvProgress.text = "${currentIndex + 1}/${currentCards.size}"
            showCard()
        }
    }

    private fun showCard() {
        if (currentIndex >= currentCards.size) {
            cardReview.visibility = View.GONE
            layoutButtons.visibility = View.GONE
            layoutEmpty.visibility = View.VISIBLE
            return
        }

        val card = currentCards[currentIndex]
        tvCardType.text = card.type.uppercase()
        tvCardFront.text = if (card.type == "Cloze") card.text else card.front
        tvCardBack.text = card.back
        tvCardBack.visibility = View.GONE
        tvTapHint.visibility = View.VISIBLE
        layoutButtons.visibility = View.GONE
        tvProgress.text = "${currentIndex + 1}/${currentCards.size}"
        isShowingAnswer = false

        cardReview.rotationY = 0f
    }

    private fun flipCard() {
        if (currentIndex >= currentCards.size) return

        if (!isShowingAnswer) {
            // Flip to show answer
            val scale = resources.displayMetrics.density
            cardReview.cameraDistance = 8000 * scale

            val flipOut = AnimatorInflater.loadAnimator(context, R.animator.flip_out)
            val flipIn = AnimatorInflater.loadAnimator(context, R.animator.flip_in)

            flipOut.setTarget(cardReview)
            flipIn.setTarget(cardReview)

            flipOut.addListener(object : android.animation.AnimatorListenerAdapter() {
                override fun onAnimationEnd(animation: android.animation.Animator) {
                    tvCardBack.visibility = View.VISIBLE
                    tvTapHint.visibility = View.GONE
                    layoutButtons.visibility = View.VISIBLE
                    isShowingAnswer = true
                }
            })

            flipOut.start()
            flipIn.start()
        }
    }

    private fun rateCard(quality: Int) {
        if (currentIndex >= currentCards.size) return

        val card = currentCards[currentIndex]
        db.updateFlashcardSM2(card.id, quality)

        currentIndex++
        isShowingAnswer = false
        showCard()
    }
}

