private fun cleanError(msg: String?): String {
    if (msg == null) return "Unknown error"
    return when {
        msg.contains("429") -> "Rate limited. Wait a few seconds and try again."
        msg.contains("Unterminated") || msg.contains("malformed") -> "AI response was cut off. Try again."
        msg.contains("Queue full") -> "Server busy. Wait a moment and try again."
        msg.contains("timeout") -> "Request timed out. Try shorter text."
        else -> msg.take(100)
    }
