package com.syedali.flashquiz.ui.home

import android.graphics.drawable.GradientDrawable
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.TextView
import androidx.recyclerview.widget.RecyclerView
import com.syedali.flashquiz.R
import com.syedali.flashquiz.data.DeckRepository
import com.syedali.flashquiz.model.Deck
import com.syedali.flashquiz.theme.ThemeManager

class DeckAdapter(
    private var decks: List<Deck>,
    private val deckRepo: DeckRepository,
    private val onDeckClick: (Deck) -> Unit,
    private val onDeleteClick: (Deck) -> Unit
) : RecyclerView.Adapter<DeckAdapter.DeckViewHolder>() {

    inner class DeckViewHolder(view: View) : RecyclerView.ViewHolder(view) {
        val tvName: TextView = view.findViewById(R.id.tv_name)
        val tvCardCount: TextView = view.findViewById(R.id.tv_card_count)
        val tvDueCount: TextView = view.findViewById(R.id.tv_due_count)
        val tvArrow: TextView = view.findViewById(R.id.tv_arrow)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): DeckViewHolder {
        val view = LayoutInflater.from(parent.context).inflate(R.layout.item_deck, parent, false)
        return DeckViewHolder(view)
    }

    override fun onBindViewHolder(holder: DeckViewHolder, position: Int) {
        val deck = decks[position]
        val theme = ThemeManager.getCurrentTheme(holder.itemView.context)

        holder.tvName.text = deck.name

        val stats = deckRepo.getStats(deck.id)
        val total = stats.totalCards + stats.totalMcqs
        val due = stats.dueCards + stats.dueMcqs

        holder.tvCardCount.text = "$total cards"
        holder.tvCardCount.setTextColor(theme.textMuted)

        holder.tvDueCount.text = "$due due"
        if (due > 0) {
            holder.tvDueCount.setTextColor(theme.accent)
        } else {
            holder.tvDueCount.setTextColor(theme.textMuted)
        }

        holder.tvArrow.setTextColor(theme.textMuted)

        val bg = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 32f
            setColor(theme.surface)
        }
        holder.itemView.background = bg

        holder.itemView.setOnClickListener { onDeckClick(deck) }
        holder.itemView.setOnLongClickListener {
            onDeleteClick(deck)
            true
        }
    }

    override fun getItemCount() = decks.size

    fun updateDecks(newDecks: List<Deck>) {
        decks = newDecks
        notifyDataSetChanged()
    }
}

package com.syedali.flashquiz.ui.review

import android.animation.AnimatorSet
import android.animation.ObjectAnimator
import android.graphics.drawable.GradientDrawable
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.view.animation.AccelerateInterpolator
import android.view.animation.DecelerateInterpolator
import android.view.animation.OvershootInterpolator
import android.widget.AdapterView
import android.widget.ArrayAdapter
import android.widget.LinearLayout
import android.widget.Spinner
import android.widget.TextView
import android.widget.ViewFlipper
import androidx.fragment.app.Fragment
import com.google.android.material.button.MaterialButton
import com.syedali.flashquiz.R
import com.syedali.flashquiz.data.DatabaseHelper
import com.syedali.flashquiz.data.DeckRepository
import com.syedali.flashquiz.data.FlashcardRepository
import com.syedali.flashquiz.model.Deck
import com.syedali.flashquiz.model.Flashcard
import com.syedali.flashquiz.theme.ThemeManager

class ReviewFragment : Fragment() {
    private lateinit var deckRepo: DeckRepository
    private lateinit var flashcardRepo: FlashcardRepository
    private var decks = listOf<Deck>()
    private var currentCards = mutableListOf<Flashcard>()
    private var currentIndex = 0
    private var showingAnswer = false
    private var deckId: Long = -1

    private lateinit var tvTitle: TextView
    private lateinit var tvDeckName: TextView
    private lateinit var tvProgress: TextView
    private lateinit var spinnerDeck: Spinner
    private lateinit var viewFlipper: ViewFlipper
    private lateinit var tvCard: TextView
    private lateinit var btnShowAnswer: MaterialButton
    private lateinit var layoutRatings: LinearLayout
    private lateinit var btnAgain: MaterialButton
    private lateinit var btnGood: MaterialButton
    private lateinit var btnEasy: MaterialButton
    private lateinit var layoutEmpty: LinearLayout

    companion object {
        fun newInstance(deckId: Long, deckName: String): ReviewFragment {
            return ReviewFragment().apply {
                arguments = Bundle().apply {
                    putLong("deck_id", deckId)
                    putString("deck_name", deckName)
                }
            }
        }
    }

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        return inflater.inflate(R.layout.fragment_review, container, false)
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        val dbHelper = DatabaseHelper(requireContext())
        deckRepo = DeckRepository(dbHelper)
        flashcardRepo = FlashcardRepository(dbHelper)

        tvTitle = view.findViewById(R.id.tv_title)
        tvDeckName = view.findViewById(R.id.tv_deck_name)
        tvProgress = view.findViewById(R.id.tv_progress)
        spinnerDeck = view.findViewById(R.id.spinner_deck)
        viewFlipper = view.findViewById(R.id.viewFlipper)
        tvCard = view.findViewById(R.id.tv_card)
        btnShowAnswer = view.findViewById(R.id.btn_show_answer)
        layoutRatings = view.findViewById(R.id.layout_ratings)
        btnAgain = view.findViewById(R.id.btn_again)
        btnGood = view.findViewById(R.id.btn_good)
        btnEasy = view.findViewById(R.id.btn_easy)
        layoutEmpty = view.findViewById(R.id.layout_empty)

        applyTheme(view)

        deckId = arguments?.getLong("deck_id", -1) ?: -1
        val deckName = arguments?.getString("deck_name", "")

        if (deckId != -1L) {
            tvDeckName.text = deckName
            spinnerDeck.visibility = View.GONE
            loadDueCards(deckId)
        } else {
            setupDeckSpinner()
        }

        btnShowAnswer.setOnClickListener {
            if (!showingAnswer && currentCards.isNotEmpty()) {
                showingAnswer = true
                animateFlip()
            }
        }

        btnAgain.setOnClickListener { rateCard(1) }
        btnGood.setOnClickListener { rateCard(4) }
        btnEasy.setOnClickListener { rateCard(5) }
    }

    private fun applyTheme(view: View) {
        val theme = ThemeManager.getCurrentTheme(requireContext())
        view.setBackgroundColor(theme.background)
        tvTitle.setTextColor(theme.textPrimary)
        tvDeckName.setTextColor(theme.textSecondary)
        tvProgress.setTextColor(theme.textMuted)
        tvCard.setTextColor(theme.textPrimary)

        btnShowAnswer.background = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 24f
            setColor(theme.accent)
        }
        btnShowAnswer.setTextColor(theme.textPrimary)

        btnAgain.background = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 24f
            setColor(theme.error)
        }
        btnAgain.setTextColor(theme.textPrimary)

        btnGood.background = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 24f
            setColor(theme.accent)
        }
        btnGood.setTextColor(theme.textPrimary)

        btnEasy.background = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 24f
            setColor(theme.success)
        }
        btnEasy.setTextColor(theme.textPrimary)

        val emptyIcon = view.findViewById<TextView>(R.id.tv_empty_icon)
        emptyIcon?.setTextColor(theme.textMuted)
        val emptyTitle = view.findViewById<TextView>(R.id.tv_empty_title)
        emptyTitle?.setTextColor(theme.textPrimary)
        val emptySubtitle = view.findViewById<TextView>(R.id.tv_empty_subtitle)
        emptySubtitle?.setTextColor(theme.textMuted)
    }

    private fun setupDeckSpinner() {
        decks = deckRepo.getAll()
        if (decks.isEmpty()) {
            tvDeckName.text = "No decks yet"
            layoutEmpty.visibility = View.VISIBLE
            viewFlipper.visibility = View.GONE
            btnShowAnswer.visibility = View.GONE
            layoutRatings.visibility = View.GONE
            return
        }

        val names = decks.map { it.name }
        val adapter = ArrayAdapter(requireContext(), android.R.layout.simple_spinner_dropdown_item, names)
        spinnerDeck.adapter = adapter
        spinnerDeck.visibility = View.VISIBLE

        spinnerDeck.onItemSelectedListener = object : AdapterView.OnItemSelectedListener {
            override fun onItemSelected(parent: AdapterView<*>?, view: View?, position: Int, id: Long) {
                deckId = decks[position].id
                tvDeckName.text = decks[position].name
                loadDueCards(deckId)
            }
            override fun onNothingSelected(parent: AdapterView<*>?) {}
        }
    }

    private fun loadDueCards(deckId: Long) {
        currentCards = flashcardRepo.getDue(deckId).toMutableList()
        currentIndex = 0
        showingAnswer = false

        if (currentCards.isEmpty()) {
            viewFlipper.visibility = View.GONE
            btnShowAnswer.visibility = View.GONE
            layoutRatings.visibility = View.GONE
            layoutEmpty.visibility = View.VISIBLE
            tvProgress.text = "0/0"
        } else {
            viewFlipper.visibility = View.VISIBLE
            layoutEmpty.visibility = View.GONE
            tvProgress.text = "${currentIndex + 1}/${currentCards.size}"
            showCard()
        }
    }

    private fun showCard() {
        if (currentIndex >= currentCards.size) {
            viewFlipper.visibility = View.GONE
            btnShowAnswer.visibility = View.GONE
            layoutRatings.visibility = View.GONE
            layoutEmpty.visibility = View.VISIBLE
            tvProgress.text = "${currentCards.size}/${currentCards.size}"
            return
        }

        val card = currentCards[currentIndex]
        tvCard.text = card.front
        showingAnswer = false
        tvProgress.text = "${currentIndex + 1}/${currentCards.size}"

        btnShowAnswer.visibility = View.VISIBLE
        layoutRatings.visibility = View.GONE
    }

    private fun animateFlip() {
        val theme = ThemeManager.getCurrentTheme(requireContext())

        val scale = resources.displayMetrics.density
        viewFlipper.cameraDistance = 8000 * scale

        val flipOut = ObjectAnimator.ofFloat(viewFlipper, "rotationY", 0f, 90f).apply {
            duration = 200
            interpolator = AccelerateInterpolator()
        }
        val flipIn = ObjectAnimator.ofFloat(viewFlipper, "rotationY", -90f, 0f).apply {
            duration = 200
            interpolator = DecelerateInterpolator()
        }

        flipOut.addListener(object : android.animation.AnimatorListenerAdapter() {
            override fun onAnimationEnd(animation: android.animation.Animator) {
                val card = currentCards[currentIndex]
                tvCard.text = card.back
                tvCard.setTextColor(theme.accent)
                flipIn.start()
            }
        })

        flipIn.addListener(object : android.animation.AnimatorListenerAdapter() {
            override fun onAnimationEnd(animation: android.animation.Animator) {
                tvCard.setTextColor(theme.textPrimary)
                btnShowAnswer.visibility = View.GONE
                layoutRatings.visibility = View.VISIBLE

                btnAgain.translationY = 50f
                btnGood.translationY = 50f
                btnEasy.translationY = 50f
                btnAgain.alpha = 0f
                btnGood.alpha = 0f
                btnEasy.alpha = 0f

                AnimatorSet().apply {
                    playTogether(
                        ObjectAnimator.ofFloat(btnAgain, "translationY", 50f, 0f),
                        ObjectAnimator.ofFloat(btnGood, "translationY", 50f, 0f),
                        ObjectAnimator.ofFloat(btnEasy, "translationY", 50f, 0f),
                        ObjectAnimator.ofFloat(btnAgain, "alpha", 0f, 1f),
                        ObjectAnimator.ofFloat(btnGood, "alpha", 0f, 1f),
                        ObjectAnimator.ofFloat(btnEasy, "alpha", 0f, 1f)
                    )
                    duration = 300
                    interpolator = OvershootInterpolator(1.5f)
                    start()
                }
            }
        })

        flipOut.start()
    }

    private fun rateCard(quality: Int) {
        val card = currentCards[currentIndex]

        val slideOut = ObjectAnimator.ofFloat(viewFlipper, "translationX", 0f, -300f).apply {
            duration = 250
            interpolator = AccelerateInterpolator()
        }

        slideOut.addListener(object : android.animation.AnimatorListenerAdapter() {
            override fun onAnimationEnd(animation: android.animation.Animator) {
                flashcardRepo.updateSM2(card.id, quality)
                viewFlipper.translationX = 300f

                val slideIn = ObjectAnimator.ofFloat(viewFlipper, "translationX", 300f, 0f).apply {
                    duration = 300
                    interpolator = DecelerateInterpolator()
                }

                slideIn.addListener(object : android.animation.AnimatorListenerAdapter() {
                    override fun onAnimationEnd(animation: android.animation.Animator) {
                        currentIndex++
                        showingAnswer = false
                        showCard()
                    }
                })

                slideIn.start()
            }
        })

        slideOut.start()
    }
}

