package com.syedali.flashquiz.ui.home

import android.graphics.drawable.GradientDrawable
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.view.animation.DecelerateInterpolator
import android.widget.TextView
import androidx.recyclerview.widget.RecyclerView
import com.syedali.flashquiz.R
import com.syedali.flashquiz.data.DeckRepository
import com.syedali.flashquiz.model.Deck
import com.syedali.flashquiz.theme.ThemeManager

class DeckAdapter(
    private var decks: List<Deck>,
    private val deckRepo: DeckRepository,
    private val onDeckClick: (Deck) -> Unit,
    private val onDeleteClick: (Deck) -> Unit
) : RecyclerView.Adapter<DeckAdapter.DeckViewHolder>() {

    private var lastAnimatedPosition = -1

    inner class DeckViewHolder(view: View) : RecyclerView.ViewHolder(view) {
        val tvName: TextView = view.findViewById(R.id.tv_name)
        val tvCardCount: TextView = view.findViewById(R.id.tv_card_count)
        val tvDueCount: TextView = view.findViewById(R.id.tv_due_count)
        val tvArrow: TextView = view.findViewById(R.id.tv_arrow)
        val viewAccentBar: View = view.findViewById(R.id.view_accent_bar)
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): DeckViewHolder {
        val view = LayoutInflater.from(parent.context).inflate(R.layout.item_deck, parent, false)
        return DeckViewHolder(view)
    }

    override fun onBindViewHolder(holder: DeckViewHolder, position: Int) {
        val deck = decks[position]
        val theme = ThemeManager.getCurrentTheme(holder.itemView.context)

        holder.tvName.text = deck.name
        holder.tvName.setTextColor(theme.textPrimary)

        val stats = deckRepo.getStats(deck.id)
        val total = stats.totalCards + stats.totalMcqs
        val due = stats.dueCards + stats.dueMcqs

        holder.tvCardCount.text = "$total cards"
        holder.tvCardCount.setTextColor(theme.textSecondary)

        if (due > 0) {
            holder.tvDueCount.text = "$due due"
            holder.tvDueCount.setTextColor(theme.accent)
        } else {
            holder.tvDueCount.text = "Done"
            holder.tvDueCount.setTextColor(theme.success)
        }

        holder.tvArrow.setTextColor(theme.textMuted)

        // Accent bar color based on due status
        val barColor = if (due > 0) theme.accent else theme.success
        val barBg = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 4f
            setColor(barColor)
        }
        holder.viewAccentBar.background = barBg

        // Card background
        val cardBg = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 20f
            setColor(theme.surface)
            setStroke(1, theme.border)
        }
        holder.itemView.background = cardBg

        // Slide-in animation
        if (position > lastAnimatedPosition) {
            holder.itemView.alpha = 0f
            holder.itemView.translationX = 60f
            holder.itemView.animate()
                .alpha(1f)
                .translationX(0f)
                .setDuration(350)
                .setStartDelay(position * 50L)
                .setInterpolator(DecelerateInterpolator(1.5f))
                .start()
            lastAnimatedPosition = position
        }

        holder.itemView.setOnClickListener { onDeckClick(deck) }
        holder.itemView.setOnLongClickListener {
            onDeleteClick(deck)
            true
        }
    }

    override fun getItemCount() = decks.size

    fun updateDecks(newDecks: List<Deck>) {
        lastAnimatedPosition = -1
        decks = newDecks
        notifyDataSetChanged()
    }
}

package com.syedali.flashquiz.ui.generate

import android.graphics.drawable.GradientDrawable
import android.net.Uri
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.view.animation.DecelerateInterpolator
import android.widget.EditText
import android.widget.ProgressBar
import android.widget.TextView
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.fragment.app.Fragment
import com.google.android.material.button.MaterialButton
import com.syedali.flashquiz.R
import com.syedali.flashquiz.api.ApiClient
import com.syedali.flashquiz.data.DatabaseHelper
import com.syedali.flashquiz.data.DeckRepository
import com.syedali.flashquiz.data.FlashcardRepository
import com.syedali.flashquiz.data.MCQRepository
import com.syedali.flashquiz.theme.ThemeManager
import com.tom_roush.pdfbox.android.PDFBoxResourceLoader
import com.tom_roush.pdfbox.pdmodel.PDDocument
import com.tom_roush.pdfbox.text.PDFTextStripper
import java.io.BufferedReader
import java.io.InputStreamReader

class GenerateFragment : Fragment() {
    private lateinit var flashcardRepo: FlashcardRepository
    private lateinit var mcqRepo: MCQRepository
    private lateinit var api: ApiClient
    private lateinit var editDeckName: EditText
    private lateinit var editSourceText: EditText
    private lateinit var editNumCards: EditText
    private lateinit var editNumMcqs: EditText
    private lateinit var editTags: EditText
    private lateinit var progressBar: ProgressBar
    private lateinit var tvStatus: TextView
    private lateinit var btnGenerate: MaterialButton

    companion object {
        private const val MAX_FILE_SIZE_MB = 50
        private const val MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024L * 1024L
    }

    private val pickFiles = registerForActivityResult(ActivityResultContracts.OpenMultipleDocuments()) { uris: List<Uri> ->
        if (uris.isNotEmpty()) {
            processFiles(uris)
        }
    }

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        return inflater.inflate(R.layout.fragment_generate, container, false)
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        PDFBoxResourceLoader.init(requireContext())

        val dbHelper = DatabaseHelper(requireContext())
        flashcardRepo = FlashcardRepository(dbHelper)
        mcqRepo = MCQRepository(dbHelper)
        api = ApiClient(requireContext())

        editDeckName = view.findViewById(R.id.edit_deck_name)
        editSourceText = view.findViewById(R.id.edit_source_text)
        editNumCards = view.findViewById(R.id.edit_num_cards)
        editNumMcqs = view.findViewById(R.id.edit_num_mcqs)
        editTags = view.findViewById(R.id.edit_tags)
        progressBar = view.findViewById(R.id.progress_bar)
        tvStatus = view.findViewById(R.id.tv_status)
        btnGenerate = view.findViewById(R.id.btn_generate)

        applyTheme(view)

        view.findViewById<MaterialButton>(R.id.btn_ocr).setOnClickListener {
            pickFiles.launch(arrayOf("image/*"))
        }

        view.findViewById<MaterialButton>(R.id.btn_import_pdf).setOnClickListener {
            pickFiles.launch(arrayOf("application/pdf", "text/*"))
        }

        btnGenerate.setOnClickListener { generate() }

        // Animate in
        view.alpha = 0f
        view.translationY = 20f
        view.animate()
            .alpha(1f)
            .translationY(0f)
            .setDuration(350)
            .setInterpolator(DecelerateInterpolator(1.5f))
            .start()
    }

    private fun applyTheme(view: View) {
        val theme = ThemeManager.getCurrentTheme(requireContext())
        view.setBackgroundColor(theme.background)

        view.findViewById<TextView>(R.id.tv_title)?.setTextColor(theme.textPrimary)
        view.findViewById<TextView>(R.id.tv_subtitle)?.setTextColor(theme.textSecondary)
        tvStatus.setTextColor(theme.textSecondary)

        val inputs = listOf(editDeckName, editSourceText, editNumCards, editNumMcqs, editTags)
        inputs.forEach { applyInputStyle(it, theme) }

        val btnOcr = view.findViewById<MaterialButton>(R.id.btn_ocr)
        val btnPdf = view.findViewById<MaterialButton>(R.id.btn_import_pdf)
        applySecondaryButtonStyle(btnOcr, theme)
        applySecondaryButtonStyle(btnPdf, theme)

        val btnGenerateBg = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 20f
            setColor(theme.accent)
        }
        btnGenerate.background = btnGenerateBg
        btnGenerate.setTextColor(-1)

        progressBar.indeterminateTintList = android.content.res.ColorStateList.valueOf(theme.accent)

        val hintTextView = view.findViewById<TextView>(R.id.tv_file_hint)
        hintTextView?.setTextColor(theme.textMuted)

        // Step labels
        for (i in 1..3) {
            val label = view.findViewWithTag<TextView>("step_label_$i")
            label?.setTextColor(theme.textSecondary)
        }
    }

    private fun applyInputStyle(editText: EditText, theme: com.syedali.flashquiz.theme.AppTheme) {
        val bg = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 14f
            setColor(theme.surface)
            setStroke(1, theme.border)
        }
        editText.background = bg
        editText.setTextColor(theme.textPrimary)
        editText.setHintTextColor(theme.textMuted)
    }

    private fun applySecondaryButtonStyle(button: MaterialButton, theme: com.syedali.flashquiz.theme.AppTheme) {
        val bg = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 14f
            setColor(theme.surfaceHigh)
            setStroke(1, theme.border)
        }
        button.background = bg
        button.setTextColor(theme.textSecondary)
    }

    private fun processFiles(uris: List<Uri>) {
        tvStatus.text = "Processing ${uris.size} file(s)..."
        progressBar.visibility = View.VISIBLE

        Thread {
            val allText = StringBuilder()
            var processedCount = 0
            var errorCount = 0

            for (uri in uris) {
                try {
                    val fileSize = getFileSize(uri)
                    if (fileSize > MAX_FILE_SIZE_BYTES) {
                        errorCount++
                        activity?.runOnUiThread {
                            Toast.makeText(requireContext(), "File too large (${fileSize / 1024 / 1024}MB). Max: ${MAX_FILE_SIZE_MB}MB", Toast.LENGTH_LONG).show()
                        }
                        continue
                    }

                    val mimeType = requireContext().contentResolver.getType(uri) ?: ""

                    when {
                        mimeType.startsWith("image/") -> {
                            val text = processImageUri(uri)
                            if (text.isNotBlank()) {
                                allText.appendLine(text)
                                allText.appendLine()
                                processedCount++
                            }
                        }
                        mimeType == "application/pdf" -> {
                            val text = processPdfUri(uri)
                            if (text.isNotBlank()) {
                                allText.appendLine(text)
                                allText.appendLine()
                                processedCount++
                            }
                        }
                        mimeType.startsWith("text/") -> {
                            val text = processTextUri(uri)
                            if (text.isNotBlank()) {
                                allText.appendLine(text)
                                allText.appendLine()
                                processedCount++
                            }
                        }
                        else -> errorCount++
                    }
                } catch (e: Exception) {
                    errorCount++
                    activity?.runOnUiThread {
                        Toast.makeText(requireContext(), "Error: ${e.message}", Toast.LENGTH_SHORT).show()
                    }
                }
            }

            activity?.runOnUiThread {
                if (allText.isNotBlank()) {
                    editSourceText.append(allText.toString())
                    tvStatus.text = "Processed $processedCount file(s). Ready to generate."
                } else {
                    tvStatus.text = "No text extracted from files."
                }
                progressBar.visibility = View.GONE
            }
        }.start()
    }

    private fun getFileSize(uri: Uri): Long {
        val cursor = requireContext().contentResolver.query(uri, null, null, null, null)
        cursor?.use {
            if (it.moveToFirst()) {
                val sizeIndex = it.getColumnIndex(android.provider.OpenableColumns.SIZE)
                if (sizeIndex >= 0) return it.getLong(sizeIndex)
            }
        }
        return 0L
    }

    private fun processImageUri(uri: Uri): String {
        val inputStream = requireContext().contentResolver.openInputStream(uri) ?: return ""
        val bytes = inputStream.readBytes()
        inputStream.close()
        if (bytes.isEmpty()) return ""

        var result = ""
        val latch = java.util.concurrent.CountDownLatch(1)
        api.ocrImage(bytes) { ocrResult ->
            ocrResult.onSuccess { text -> result = text }
            latch.countDown()
        }
        latch.await(60, java.util.concurrent.TimeUnit.SECONDS)
        return result
    }

    private fun processPdfUri(uri: Uri): String {
        val inputStream = requireContext().contentResolver.openInputStream(uri) ?: return ""
        val document = PDDocument.load(inputStream)
        val text = PDFTextStripper().getText(document)
        document.close()
        inputStream.close()
        return text.trim()
    }

    private fun processTextUri(uri: Uri): String {
        val inputStream = requireContext().contentResolver.openInputStream(uri) ?: return ""
        val reader = BufferedReader(InputStreamReader(inputStream))
        val text = reader.readText()
        reader.close()
        return text.trim()
    }

    private fun generate() {
        val deckName = editDeckName.text.toString().trim()
        val sourceText = editSourceText.text.toString().trim()
        val numCards = editNumCards.text.toString().toIntOrNull() ?: 5
        val numMcqs = editNumMcqs.text.toString().toIntOrNull() ?: 2
        val tags = editTags.text.toString().split(",").map { it.trim() }.filter { it.isNotEmpty() }

        if (deckName.isEmpty()) { editDeckName.error = "Required"; return }
        if (sourceText.isEmpty()) { editSourceText.error = "Required"; return }

        btnGenerate.isEnabled = false
        progressBar.visibility = View.VISIBLE
        tvStatus.text = "Generating cards..."

        val deckId = DeckRepository(DatabaseHelper(requireContext())).create(deckName, tags)

        api.generateFlashcards(sourceText, numCards, tags) { result ->
            result.onSuccess { cards ->
                flashcardRepo.add(deckId, cards)
                activity?.runOnUiThread { tvStatus.text = "Flashcards done. Generating MCQs..." }

                api.generateMCQs(sourceText, numMcqs, tags) { mcqResult ->
                    mcqResult.onSuccess { mcqs ->
                        mcqRepo.add(deckId, mcqs)
                        activity?.runOnUiThread {
                            tvStatus.text = "Done! ${cards.size} cards, ${mcqs.size} MCQs created."
                            progressBar.visibility = View.GONE
                            btnGenerate.isEnabled = true
                            editSourceText.text.clear()
                            editDeckName.text.clear()
                        }
                    }
                    mcqResult.onFailure { e ->
                        activity?.runOnUiThread {
                            tvStatus.text = "MCQs failed: ${cleanError(e.message)}. Cards saved."
                            progressBar.visibility = View.GONE
                            btnGenerate.isEnabled = true
                        }
                    }
                }
            }
            result.onFailure { e ->
                activity?.runOnUiThread {
                    tvStatus.text = "Error: ${cleanError(e.message)}"
                    progressBar.visibility = View.GONE
                    btnGenerate.isEnabled = true
                }
            }
        }
    }

    private fun cleanError(msg: String?): String {
        if (msg == null) return "Unknown error"
        return when {
            msg.contains("429") || msg.contains("Queue full") -> "Server busy. Wait a few seconds and try again."
            msg.contains("Unterminated") || msg.contains("malformed") || msg.contains("parse") -> "AI response cut off. Try again."
            msg.contains("timeout") -> "Request timed out. Try shorter text."
            msg.contains("Could not find card data") -> "AI returned empty response. Try again."
            else -> msg.take(120)
        }
    }
}

package com.syedali.flashquiz.ui.review

import android.animation.AnimatorSet
import android.animation.ObjectAnimator
import android.graphics.drawable.GradientDrawable
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.view.animation.AccelerateInterpolator
import android.view.animation.DecelerateInterpolator
import android.view.animation.OvershootInterpolator
import android.widget.AdapterView
import android.widget.ArrayAdapter
import android.widget.LinearLayout
import android.widget.ProgressBar
import android.widget.Spinner
import android.widget.TextView
import android.widget.ViewFlipper
import androidx.fragment.app.Fragment
import com.google.android.material.button.MaterialButton
import com.syedali.flashquiz.R
import com.syedali.flashquiz.data.DatabaseHelper
import com.syedali.flashquiz.data.DeckRepository
import com.syedali.flashquiz.data.FlashcardRepository
import com.syedali.flashquiz.model.Deck
import com.syedali.flashquiz.model.Flashcard
import com.syedali.flashquiz.theme.ThemeManager

class ReviewFragment : Fragment() {
    private lateinit var deckRepo: DeckRepository
    private lateinit var flashcardRepo: FlashcardRepository
    private var decks = listOf<Deck>()
    private var currentCards = mutableListOf<Flashcard>()
    private var currentIndex = 0
    private var showingAnswer = false
    private var deckId: Long = -1

    private lateinit var tvTitle: TextView
    private lateinit var tvDeckName: TextView
    private lateinit var tvProgress: TextView
    private lateinit var spinnerDeck: Spinner
    private lateinit var viewFlipper: ViewFlipper
    private lateinit var tvCard: TextView
    private lateinit var btnShowAnswer: MaterialButton
    private lateinit var layoutRatings: LinearLayout
    private lateinit var btnAgain: MaterialButton
    private lateinit var btnGood: MaterialButton
    private lateinit var btnEasy: MaterialButton
    private lateinit var layoutEmpty: LinearLayout
    private lateinit var progressIndicator: ProgressBar

    companion object {
        fun newInstance(deckId: Long, deckName: String): ReviewFragment {
            return ReviewFragment().apply {
                arguments = Bundle().apply {
                    putLong("deck_id", deckId)
                    putString("deck_name", deckName)
                }
            }
        }
    }

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        return inflater.inflate(R.layout.fragment_review, container, false)
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)
        val dbHelper = DatabaseHelper(requireContext())
        deckRepo = DeckRepository(dbHelper)
        flashcardRepo = FlashcardRepository(dbHelper)

        tvTitle = view.findViewById(R.id.tv_title)
        tvDeckName = view.findViewById(R.id.tv_deck_name)
        tvProgress = view.findViewById(R.id.tv_progress)
        spinnerDeck = view.findViewById(R.id.spinner_deck)
        viewFlipper = view.findViewById(R.id.viewFlipper)
        tvCard = view.findViewById(R.id.tv_card)
        btnShowAnswer = view.findViewById(R.id.btn_show_answer)
        layoutRatings = view.findViewById(R.id.layout_ratings)
        btnAgain = view.findViewById(R.id.btn_again)
        btnGood = view.findViewById(R.id.btn_good)
        btnEasy = view.findViewById(R.id.btn_easy)
        layoutEmpty = view.findViewById(R.id.layout_empty)
        progressIndicator = view.findViewById(R.id.progress_indicator)

        applyTheme(view)

        deckId = arguments?.getLong("deck_id", -1) ?: -1
        val deckName = arguments?.getString("deck_name", "")

        if (deckId != -1L) {
            tvDeckName.text = deckName
            spinnerDeck.visibility = View.GONE
            loadDueCards(deckId)
        } else {
            setupDeckSpinner()
        }

        btnShowAnswer.setOnClickListener {
            if (!showingAnswer && currentCards.isNotEmpty()) {
                showingAnswer = true
                animateFlip()
            }
        }

        btnAgain.setOnClickListener { rateCard(1) }
        btnGood.setOnClickListener { rateCard(4) }
        btnEasy.setOnClickListener { rateCard(5) }
    }

    private fun applyTheme(view: View) {
        val theme = ThemeManager.getCurrentTheme(requireContext())
        view.setBackgroundColor(theme.background)
        tvTitle.setTextColor(theme.textPrimary)
        tvDeckName.setTextColor(theme.textSecondary)
        tvProgress.setTextColor(theme.accent)
        tvCard.setTextColor(theme.textPrimary)

        // Card container
        val cardBg = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 28f
            setColor(theme.surface)
            setStroke(1, theme.border)
        }
        view.findViewById<View>(R.id.layout_card)?.background = cardBg

        val btnShowBg = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 16f
            setColor(theme.accent)
        }
        btnShowAnswer.background = btnShowBg
        btnShowAnswer.setTextColor(-1)

        btnAgain.background = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 16f
            setColor(theme.error)
        }
        btnAgain.setTextColor(-1)

        btnGood.background = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 16f
            setColor(theme.accent)
        }
        btnGood.setTextColor(-1)

        btnEasy.background = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 16f
            setColor(theme.success)
        }
        btnEasy.setTextColor(-1)

        val emptyIcon = view.findViewById<TextView>(R.id.tv_empty_icon)
        emptyIcon?.setTextColor(theme.textMuted)
        val emptyTitle = view.findViewById<TextView>(R.id.tv_empty_title)
        emptyTitle?.setTextColor(theme.textPrimary)
        val emptySubtitle = view.findViewById<TextView>(R.id.tv_empty_subtitle)
        emptySubtitle?.setTextColor(theme.textSecondary)
    }

    private fun setupDeckSpinner() {
        decks = deckRepo.getAll()
        if (decks.isEmpty()) {
            tvDeckName.text = "No decks"
            layoutEmpty.visibility = View.VISIBLE
            viewFlipper.visibility = View.GONE
            btnShowAnswer.visibility = View.GONE
            layoutRatings.visibility = View.GONE
            return
        }

        val names = decks.map { it.name }
        val adapter = ArrayAdapter(requireContext(), android.R.layout.simple_spinner_dropdown_item, names)
        spinnerDeck.adapter = adapter
        spinnerDeck.visibility = View.VISIBLE

        spinnerDeck.onItemSelectedListener = object : AdapterView.OnItemSelectedListener {
            override fun onItemSelected(parent: AdapterView<*>?, view: View?, position: Int, id: Long) {
                deckId = decks[position].id
                tvDeckName.text = decks[position].name
                loadDueCards(deckId)
            }
            override fun onNothingSelected(parent: AdapterView<*>?) {}
        }
    }

    private fun loadDueCards(deckId: Long) {
        currentCards = flashcardRepo.getDue(deckId).toMutableList()
        currentIndex = 0
        showingAnswer = false

        if (currentCards.isEmpty()) {
            viewFlipper.visibility = View.GONE
            btnShowAnswer.visibility = View.GONE
            layoutRatings.visibility = View.GONE
            layoutEmpty.visibility = View.VISIBLE
            tvProgress.text = "0/0"
        } else {
            viewFlipper.visibility = View.VISIBLE
            layoutEmpty.visibility = View.GONE
            tvProgress.text = "${currentIndex + 1}/${currentCards.size}"
            showCard()
        }
    }

    private fun showCard() {
        if (currentIndex >= currentCards.size) {
            viewFlipper.visibility = View.GONE
            btnShowAnswer.visibility = View.GONE
            layoutRatings.visibility = View.GONE
            layoutEmpty.visibility = View.VISIBLE
            tvProgress.text = "${currentCards.size}/${currentCards.size}"
            return
        }

        val card = currentCards[currentIndex]
        tvCard.text = card.front
        showingAnswer = false
        tvProgress.text = "${currentIndex + 1}/${currentCards.size}"

        btnShowAnswer.visibility = View.VISIBLE
        layoutRatings.visibility = View.GONE
    }

    private fun animateFlip() {
        val theme = ThemeManager.getCurrentTheme(requireContext())
        val scale = resources.displayMetrics.density
        viewFlipper.cameraDistance = 8000 * scale

        val flipOut = ObjectAnimator.ofFloat(viewFlipper, "rotationY", 0f, 90f).apply {
            duration = 200
            interpolator = AccelerateInterpolator()
        }
        val flipIn = ObjectAnimator.ofFloat(viewFlipper, "rotationY", -90f, 0f).apply {
            duration = 200
            interpolator = DecelerateInterpolator()
        }

        flipOut.addListener(object : android.animation.AnimatorListenerAdapter() {
            override fun onAnimationEnd(animation: android.animation.Animator) {
                val card = currentCards[currentIndex]
                tvCard.text = card.back
                tvCard.setTextColor(theme.accent)
                flipIn.start()
            }
        })

        flipIn.addListener(object : android.animation.AnimatorListenerAdapter() {
            override fun onAnimationEnd(animation: android.animation.Animator) {
                tvCard.setTextColor(theme.textPrimary)
                btnShowAnswer.visibility = View.GONE
                layoutRatings.visibility = View.VISIBLE

                // Staggered button animation
                btnAgain.translationY = 40f
                btnGood.translationY = 40f
                btnEasy.translationY = 40f
                btnAgain.alpha = 0f
                btnGood.alpha = 0f
                btnEasy.alpha = 0f

                AnimatorSet().apply {
                    playTogether(
                        ObjectAnimator.ofFloat(btnAgain, "translationY", 40f, 0f),
                        ObjectAnimator.ofFloat(btnGood, "translationY", 40f, 0f),
                        ObjectAnimator.ofFloat(btnEasy, "translationY", 40f, 0f),
                        ObjectAnimator.ofFloat(btnAgain, "alpha", 0f, 1f),
                        ObjectAnimator.ofFloat(btnGood, "alpha", 0f, 1f),
                        ObjectAnimator.ofFloat(btnEasy, "alpha", 0f, 1f)
                    )
                    duration = 300
                    startDelay = 50
                    interpolator = OvershootInterpolator(1.2f)
                    start()
                }
            }
        })

        flipOut.start()
    }

    private fun rateCard(quality: Int) {
        val card = currentCards[currentIndex]

        val slideOut = ObjectAnimator.ofFloat(viewFlipper, "translationX", 0f, -300f).apply {
            duration = 250
            interpolator = AccelerateInterpolator()
        }

        slideOut.addListener(object : android.animation.AnimatorListenerAdapter() {
            override fun onAnimationEnd(animation: android.animation.Animator) {
                flashcardRepo.updateSM2(card.id, quality)
                viewFlipper.translationX = 300f

                val slideIn = ObjectAnimator.ofFloat(viewFlipper, "translationX", 300f, 0f).apply {
                    duration = 300
                    interpolator = DecelerateInterpolator()
                }

                slideIn.addListener(object : android.animation.AnimatorListenerAdapter() {
                    override fun onAnimationEnd(animation: android.animation.Animator) {
                        currentIndex++
                        showingAnswer = false
                        showCard()
                    }
                })

                slideIn.start()
            }
        })

        slideOut.start()
    }
}

package com.syedali.flashquiz.theme

import android.app.Activity
import android.graphics.drawable.GradientDrawable
import android.view.View
import android.widget.Button
import android.widget.EditText
import android.widget.ImageButton
import android.widget.ProgressBar
import android.widget.TextView
import androidx.cardview.widget.CardView
import com.google.android.material.button.MaterialButton
import com.google.android.material.chip.Chip
import com.google.android.material.textfield.TextInputLayout

object ThemeHelper {

    fun applyTheme(activity: Activity, theme: AppTheme) {
        activity.window.decorView.setBackgroundColor(theme.background)
        activity.window.statusBarColor = theme.background
        activity.window.navigationBarColor = theme.background
    }

    fun applyToView(view: View, theme: AppTheme) {
        when (view) {
            is CardView -> applyToCard(view, theme)
            is MaterialButton -> applyToMaterialButton(view, theme)
            is Button -> applyToButton(view, theme)
            is TextView -> applyToTextView(view, theme)
            is EditText -> applyToEditText(view, theme)
            is TextInputLayout -> applyToInputLayout(view, theme)
            is Chip -> applyToChip(view, theme)
            is ProgressBar -> applyToProgressBar(view, theme)
            is ImageButton -> applyToImageButton(view, theme)
        }
    }

    private fun applyToCard(card: CardView, theme: AppTheme) {
        card.setCardBackgroundColor(theme.surface)
    }

    private fun applyToMaterialButton(button: MaterialButton, theme: AppTheme) {
        val tag = button.tag?.toString()
        when (tag) {
            "accent" -> {
                button.setBackgroundColor(theme.accent)
                button.setTextColor(-1)
            }
            "surface" -> {
                val bg = GradientDrawable().apply {
                    shape = GradientDrawable.RECTANGLE
                    cornerRadius = 16f
                    setColor(theme.surfaceHigh)
                    setStroke(1, theme.border)
                }
                button.background = bg
                button.setTextColor(theme.textSecondary)
            }
            else -> {
                val bg = GradientDrawable().apply {
                    shape = GradientDrawable.RECTANGLE
                    cornerRadius = 16f
                    setColor(theme.surfaceHigh)
                    setStroke(1, theme.border)
                }
                button.background = bg
                button.setTextColor(theme.textSecondary)
            }
        }
    }

    private fun applyToButton(button: Button, theme: AppTheme) {
        val bg = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 16f
            setColor(theme.surfaceHigh)
        }
        button.background = bg
        button.setTextColor(theme.textSecondary)
    }

    private fun applyToTextView(textView: TextView, theme: AppTheme) {
        val tag = textView.tag?.toString()
        when (tag) {
            "primary" -> textView.setTextColor(theme.textPrimary)
            "secondary" -> textView.setTextColor(theme.textSecondary)
            "muted" -> textView.setTextColor(theme.textMuted)
            "accent" -> textView.setTextColor(theme.accent)
            "error" -> textView.setTextColor(theme.error)
            "success" -> textView.setTextColor(theme.success)
        }
    }

    private fun applyToEditText(editText: EditText, theme: AppTheme) {
        val bg = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 14f
            setColor(theme.surface)
            setStroke(1, theme.border)
        }
        editText.background = bg
        editText.setTextColor(theme.textPrimary)
        editText.setHintTextColor(theme.textMuted)
    }

    private fun applyToInputLayout(layout: TextInputLayout, theme: AppTheme) {
        val boxBg = GradientDrawable().apply {
            setColor(theme.surface)
            cornerRadius = 14f
            setStroke(1, theme.border)
        }
        layout.boxBackgroundMode = TextInputLayout.BOX_BACKGROUND_NONE
        layout.background = boxBg
        layout.hintTextColor = android.content.res.ColorStateList.valueOf(theme.accent)
    }

    private fun applyToChip(chip: Chip, theme: AppTheme) {
        val bg = GradientDrawable().apply {
            setColor(theme.accentSoft)
            cornerRadius = 48f
        }
        chip.background = bg
        chip.setTextColor(theme.accent)
    }

    private fun applyToProgressBar(progressBar: ProgressBar, theme: AppTheme) {
        progressBar.indeterminateTintList = android.content.res.ColorStateList.valueOf(theme.accent)
    }

    private fun applyToImageButton(button: ImageButton, theme: AppTheme) {
        button.setColorFilter(theme.textMuted)
    }

    fun getAccentColor(theme: AppTheme): Int = theme.accent
    fun getBackgroundColor(theme: AppTheme): Int = theme.background
    fun getSurfaceColor(theme: AppTheme): Int = theme.surface
    fun getErrorColor(theme: AppTheme): Int = theme.error
    fun getSuccessColor(theme: AppTheme): Int = theme.success
}

package com.syedali.flashquiz.theme

import android.graphics.drawable.GradientDrawable
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.TextView
import androidx.fragment.app.DialogFragment
import androidx.recyclerview.widget.GridLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.google.android.material.button.MaterialButton
import com.syedali.flashquiz.R

class ThemePickerDialogFragment : DialogFragment() {

    interface ThemeSelectionListener {
        fun onThemeSelected(theme: AppTheme)
    }

    private var listener: ThemeSelectionListener? = null
    private var currentThemeId: String = "dark"

    fun setListener(listener: ThemeSelectionListener) {
        this.listener = listener
    }

    fun setCurrentTheme(themeId: String) {
        this.currentThemeId = themeId
    }

    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {
        return inflater.inflate(R.layout.dialog_theme_picker, container, false)
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        val theme = ThemeManager.getCurrentTheme(requireContext())
        val dialogBg = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 28f
            setColor(theme.surface)
        }
        view.background = dialogBg

        val recycler = view.findViewById<RecyclerView>(R.id.recycler_themes)
        recycler.layoutManager = GridLayoutManager(requireContext(), 2)

        val adapter = ThemeAdapter(
            themes = ThemeManager.themes,
            currentThemeId = currentThemeId,
            onSelect = { selectedTheme ->
                listener?.onThemeSelected(selectedTheme)
                dismiss()
            }
        )
        recycler.adapter = adapter

        val btnCancel = view.findViewById<MaterialButton>(R.id.btn_cancel)
        val cancelBg = GradientDrawable().apply {
            shape = GradientDrawable.RECTANGLE
            cornerRadius = 16f
            setColor(theme.surfaceHigh)
            setStroke(1, theme.border)
        }
        btnCancel.background = cancelBg
        btnCancel.setTextColor(theme.textSecondary)
        btnCancel.setOnClickListener { dismiss() }
    }

    override fun onStart() {
        super.onStart()
        dialog?.window?.setLayout(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        dialog?.window?.setBackgroundDrawableResource(android.R.color.transparent)
    }

    class ThemeAdapter(
        private val themes: List<AppTheme>,
        private val currentThemeId: String,
        private val onSelect: (AppTheme) -> Unit
    ) : RecyclerView.Adapter<ThemeAdapter.ThemeViewHolder>() {

        class ThemeViewHolder(view: View) : RecyclerView.ViewHolder(view) {
            val viewPreview: View = view.findViewById(R.id.view_preview)
            val tvName: TextView = view.findViewById(R.id.tv_name)
            val tvCheck: TextView = view.findViewById(R.id.tv_check)
        }

        override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ThemeViewHolder {
            val view = LayoutInflater.from(parent.context).inflate(R.layout.item_theme, parent, false)
            return ThemeViewHolder(view)
        }

        override fun onBindViewHolder(holder: ThemeViewHolder, position: Int) {
            val theme = themes[position]
            val isSelected = theme.id == currentThemeId

            val previewBg = GradientDrawable().apply {
                shape = GradientDrawable.RECTANGLE
                cornerRadius = 20f
                colors = intArrayOf(theme.background, theme.surface, theme.accent)
            }
            holder.viewPreview.background = previewBg

            val borderBg = GradientDrawable().apply {
                shape = GradientDrawable.RECTANGLE
                cornerRadius = 36f
                setColor(0x00000000)
                setStroke(3, if (isSelected) theme.accent else theme.border)
            }
            (holder.viewPreview.parent as? View)?.background = borderBg

            holder.tvName.text = theme.name
            holder.tvName.setTextColor(theme.textPrimary)

            holder.tvCheck.visibility = if (isSelected) View.VISIBLE else View.GONE
            holder.tvCheck.setTextColor(theme.accent)

            holder.itemView.setOnClickListener { onSelect(theme) }
        }

        override fun getItemCount() = themes.size
    }
}

