.op .lt{width:30px;height:30px;border-radius:8px;background:var(--sf2);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:var(--t2);flex-shrink:0;transition:all .2s}
.op .ox{font-size:14px;color:var(--t1);flex:1}
.op.ok{border-color:var(--ok);background:rgba(26,127,55,.06)}
.op.ok .lt{background:var(--ok);color:#fff}
.op.wr{border-color:var(--er);background:rgba(207,34,46,.06)}
.op.wr .lt{background:var(--er);color:#fff}
.op.dm{opacity:.4;pointer-events:none}
.ex{padding:14px;border-radius:12px;background:var(--sf2);margin-top:12px;display:none}
.ex.on{display:block}
.ex strong{color:var(--ac);font-size:11px;letter-spacing:.06;text-transform:uppercase;display:block;margin-bottom:6px}
.ex p{font-size:13px;color:var(--t2);line-height:1.55}
.nav{position:absolute;bottom:0;left:0;right:0;height:80px;background:var(--nv);border-top:1px solid var(--nvb);display:flex;z-index:50;padding-bottom:12px}
.ni{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;cursor:pointer;color:var(--t3);transition:color .2s;-webkit-tap-highlight-color:transparent}
.ni:active{transform:scale(.9)}
.ni.on{color:var(--ac)}
.ni svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.ni span{font-size:10px;font-weight:600}
@keyframes fu{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}
:root{--bg:#F6F8FA;--sf:#FFF;--sf2:#F0F2F5;--ac:#0969DA;--acs:#DDF4FF;--t1:#1F2328;--t2:#656D76;--t3:#8C959F;--bd:#D0D7DE;--er:#CF222E;--ok:#1A7F37;--sh:0 1px 3px rgba(0,0,0,.06);--nv:#FFF;--nvb:#E1E4E8}
[data-theme="dark"]{--bg:#0D1117;--sf:#161B22;--sf2:#21262D;--ac:#58A6FF;--acs:#1F3A5F;--t1:#F0F6FC;--t2:#8B949E;--t3:#484F58;--bd:#30363D;--er:#F85149;--ok:#3FB950;--sh:0 1px 3px rgba(0,0,0,.3);--nv:#161B22;--nvb:#21262D}
</style>
</head>
