Add-Content -Path "F:\Downloads\hm\preview\index.html" -Value @'
<script>
function setTheme(t){
  document.documentElement.setAttribute('data-theme',t);
  document.getElementById('lb').classList.toggle('on',t==='light');
  document.getElementById('db').classList.toggle('on',t==='dark');
}
function go(id){
  document.querySelectorAll('.sc').forEach(function(s){s.classList.remove('on')});
  document.getElementById(id).classList.add('on');
  var tabs=['t1','t2','t3','t4'];
  tabs.forEach(function(t,i){
    document.querySelectorAll('.ni')[i].classList.toggle('on',t===id);
  });
}
var decks=[
  {name:'Biology Chapter 5',cards:12,due:3,color:'var(--ac)'},
  {name:'History Dates',cards:8,due:0,color:'#8250DF'},
  {name:'Chemistry Formulas',cards:5,due:1,color:'#BF3989'},
  {name:'Spanish Vocab',cards:20,due:0,color:'var(--ok)'}
];
function renderDecks(){
  var h='';
  decks.forEach(function(d){
    var dueText=d.due>0?d.due+' due':'Done';
    var dueCls=d.due>0?'':' style="color:var(--ok)"';
    h+='<div class="dk" onclick="go(\'t3\')">';
    h+='<div class="dk-bar" style="background:'+d.color+'"></div>';
    h+='<div class="dk-body"><div class="dk-name">'+d.name+'</div>';
    h+='<div class="dk-meta">'+d.cards+' cards</div></div>';
    h+='<div class="badge dk-badge"'+dueCls+'>'+dueText+'</div></div>';
  });
  document.getElementById('deckList').innerHTML=h;
}
renderDecks();
var rvCards=[
  {q:'What is the powerhouse of the cell?',a:'Mitochondria generate most of the cell supply of ATP through oxidative phosphorylation.'},
  {q:'What is osmosis?',a:'The movement of water across a semipermeable membrane from low to high solute concentration.'},
  {q:'Define homeostasis.',a:'The process by which organisms maintain stable internal conditions despite external changes.'},
  {q:'What are the phases of mitosis?',a:'Prophase, Metaphase, Anaphase, and Telophase.'},
  {q:'What is the role of ribosomes?',a:'Ribosomes synthesize proteins by translating mRNA into amino acid chains.'}
];
var rvIdx=0,rvAns=false;
function showAns(){
  if(rvAns)return;
  rvAns=true;
  document.getElementById('rvText').textContent=rvCards[rvIdx].a;
  document.getElementById('rvText').classList.add('aw');
  document.getElementById('rvShowBtn').style.display='none';
  setTimeout(function(){document.getElementById('rvRate').classList.add('on')},100);
}
function rate(){
  rvAns=false;
  var c=document.getElementById('rvCard');
  c.classList.add('sl');
  setTimeout(function(){
    rvIdx=(rvIdx+1)%rvCards.length;
    document.getElementById('rvText').textContent=rvCards[rvIdx].q;
    document.getElementById('rvText').classList.remove('aw');
    document.getElementById('rvShowBtn').style.display='block';
    document.getElementById('rvRate').classList.remove('on');
    document.getElementById('rvBar').style.width=((rvIdx+1)/rvCards.length*100)+'%';
    document.getElementById('rvBadge').textContent=(rvIdx+1)+'/'+rvCards.length;
    c.classList.remove('sl');
    c.classList.add('si');
    setTimeout(function(){c.classList.remove('si')},400);
  },350);
}
var qzData=[
  {q:'What is the powerhouse of the cell?',o:['Nucleus','Mitochondria','Ribosome','Golgi Apparatus'],c:1,w:'Mitochondria generate most of the cell ATP.'},
  {q:'What is the basic unit of life?',o:['Atom','Molecule','Cell','Tissue'],c:2,w:'The cell is the smallest structural and functional unit of life.'},
  {q:'Which molecule carries genetic info?',o:['RNA','DNA','Protein','Lipid'],c:1,w:'DNA stores the genetic instructions for all living organisms.'},
  {q:'What converts glucose to energy?',o:['Photosynthesis','Fermentation','Cellular Respiration','Transcription'],c:2,w:'Cellular respiration produces ATP from glucose and oxygen.'}
];
var qzIdx=0,qzOk=0,qzWr=0,qzDone=false;
function renderOpts(){
  var d=qzData[qzIdx];
  var h='';
  var letters='ABCD';
  d.o.forEach(function(o,i){
    h+='<div class="op" onclick="selOpt('+i+')">';
    h+='<span class="lt">'+letters[i]+'</span>';
    h+='<span class="ox">'+o+'</span></div>';
  });
  document.getElementById('qzOpts').innerHTML=h;
}
function selOpt(i){
  if(qzDone)return;
  qzDone=true;
  var d=qzData[qzIdx];
  var opts=document.querySelectorAll('#qzOpts .op');
  opts.forEach(function(o,j){
    if(j===d.c)o.classList.add('ok');
    else if(j===i&&i!==d.c)o.classList.add('wr');
    else o.classList.add('dm');
  });
  if(i===d.c)qzOk++;else qzWr++;
  document.getElementById('qzOk').textContent=qzOk+' correct';
  document.getElementById('qzWr').textContent=qzWr+' wrong';
  document.getElementById('qzExT').textContent=d.w;
  document.getElementById('qzEx').classList.add('on');
  document.getElementById('qzNext').style.display='block';
  document.getElementById('qzNext').textContent=qzIdx+1>=qzData.length?'See Results':'Next Question';
}
function nextQ(){
  qzIdx=(qzIdx+1)%qzData.length;
  qzDone=false;
  renderOpts();
  var d=qzData[qzIdx];
  document.getElementById('qzQ').textContent=d.q;
  document.getElementById('qzNum').textContent='Question '+(qzIdx+1)+' of '+qzData.length;
  document.getElementById('qzBadge').textContent=(qzIdx+1)+'/'+qzData.length;
  document.getElementById('qzEx').classList.remove('on');
  document.getElementById('qzNext').style.display='none';
}
renderOpts();
function gen(){
  var f=document.getElementById('gf'),s=document.getElementById('gs'),p=document.getElementById('gp');
  p.classList.add('on');f.style.width='0%';s.textContent='Generating flashcards...';
  setTimeout(function(){f.style.width='40%'},200);
  setTimeout(function(){f.style.width='70%';s.textContent='Flashcards done. Generating MCQs...'},800);
  setTimeout(function(){f.style.width='100%'},1400);
  setTimeout(function(){s.textContent='Done! 5 cards, 3 MCQs created.';p.classList.remove('on')},2000);
}
</script>
</body></html>
